(window.GIM_TS=window.GIM_TS||{})["Yoma.6"]={"from":144,"a":[["\u0003ואליבא\u0004 \u0005[ולפי שיטתו]\u0006 של \u0003ר' עקיבא\u0004 ש\u0003אמר: אדם אוסר עצמו בכל שהוא,\u0004 שאם נשבע שלא יאכל — הרי אסר על עצמו בכל שיעור. משמע שריש לקיש עצמו סבור כי חצי שיעור אין בו איסור כלל!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 שמא סבור ריש לקיש \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 לחצי שיעור \u0003היתר מן התורה, קא חייל\u0004 \u0005[חל]\u0006 \u0003קרבן שבועה\u0004 עליו אף שאסור מדברי סופרים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003שבועת העדות,\u0004 שמשביעים אדם שיעיד על דבר שראה וידע, \u0003אינה נוהגת אלא בראויין להעיד,\u0004 ואם השביעו אדם שאינו ראוי להעיד, אף שלא העיד — אין השבועה חלה עליו. \u0003והוינן בה\u0004 \u0005[והיינו עוסקים\u0006 ומתקשים בבעיה \u0005זו]:\u0006 \u0003למעוטי מאי\u0004 \u0005[למעט את מה]\u0006 באה ההגדרה \"הראויין להעיד\"? שהרי קודם לכן נאמר ששבועת העדות אינה חלה על נשים, קרובים ופסולים! \u0003רב פפא אמר: למעוטי\u0004 \u0005[למעט]\u0006 \u0003מלך,\u0004 שאף שאין המלך נמנה ברשימה של הבלתי ראויים, דין הוא שאין המלך מעיד בפני בית דין מפני כבודו.","\u0003רב אחא בר יעקב אמר: למעוטי\u0004 \u0005[למעט]\u0006 \u0003משחק בקוביא\u0004 (שהוא פסול לעדות מדברי סופרים) \u0003והא\u0004 \u0005[והרי]\u0006 \u0003משחק בקוביא מדאורייתא מיחזי חזי\u0004 \u0005[מן התורה ראוי הוא]\u0006 להעיד \u0003ורבנן הוא\u0004 \u0005[וחכמים הם]\u0006 ש\u0003פסלוהו\u0004 מלהעיד, ובכל זאת אומרים אנו כי \u0003לא קא חיילא עליה שבועה\u0004 \u0005[שלא חלה עליו שבועת\u0006 העדות\u0005]\u0006 מן התורה, אף שאין איסורו אלא מדברי חכמים. אף כאן, אין שבועת הביטוי חלה אף כאשר אין הדבר אסור אלא מדברי סופרים!","ודוחים: יש לחלק, \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בענין העדות ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אם לוא יגיד\u0004 ונשא עוונו\u0003\"\u0004 (ויקרא ה, א), שהעונש בא לאדם שצריך להעיד ולא העיד, \u0003והאי לאו בר הגדה הוא כלל\u0004 \u0005[וזה אינו בן הגדת\u0006 עדות \u0005כלל]\u0006 שכיון שבפועל אין בית הדין מקבל את עדותו, והתורה תלתה את שבועת העדות ביכולת להעיד, הרי מי שנבצר ממנו להעיד מפני כל סיבה שהיא, אין שבועת העדות חלה עליו. אבל אין הדבר כן לגבי שבועת ביטוי, ואין איפוא להוכיח דבר, ופירושנו הראשון עומד במקומו.","ההנחה הראשונה שבה התחלנו את הדיון היתה שלשון המשנה \"אסור\" כוונתה לאיסור שאין בו חיוב כרת. ושואלים: \u0003וכל היכא דתני\u0004 \u0005[וכל מקום שהוא שונה]\u0006 דבר שהוא \u0003ענוש כרת, לא תני\u0004 \u0005[אינו שונה]\u0006 בלשון \u0003אסור? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אף על פי שאמרו\u0004 לשון \u0003\"אסור\" בכולן,\u0004 בכל חמשת העינויים המנויים ביום הכיפורים — \u0003לא אמרו ענוש כרת אלא על האוכל ושותה ועושה מלאכה בלבד.\u0004 משמע שלשון איסור חלה גם דבר שיש בו עונש כרת! ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין את הדברים: \u0003כשאמרו אסור — לא אמרו אלא בכחצי שיעור, אבל כשיעור — ענוש כרת, ואף על פי שענוש כרת — אין ענוש כרת אלא\u0004 ה\u0003אוכל ושותה ועושה מלאכה בלבד.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006 במשנתנו\u0005]\u0006 לשון \u0003\"אסור\" —\u0004 הרי הוא מדבר \u0003אשארא\u0004 \u0005[על השאר],\u0006 על האיסורים שאין בהן כרת. \u0003דתנו\u0004 \u0005[ששנו]\u0006 \u0003רבה ורב יוסף בשאר סיפרי דבי\u0004 \u0005[הספרים שבבית\u0006 מדרשו\u0005]\u0006 של \u0003רב.\u0004 כלומר: במדרש ההלכה של ספרי \"במדבר\" ו\"דברים\", וכך שנו: \u0003מניין ליום הכפורים שאסור ברחיצה בסיכה ובנעילת הסנדל ובתשמיש המטה — תלמוד לומר: \"שבתון\"\u0004 (ויקרא טז, לא). כלומר: \u0003שבות\u0004 והמנע מלעשות בו כמה דברים. הרי שלשון איסור חלה על אלה, אבל אין בהם עונש כרת.","כיון שהזכרנו את מחלוקתם של ר' יוחנן וריש לקיש באים עתה לדון ב\u0003גופא\u0004 (בגופה) של המחלוקת: \u0003חצי שיעור\u0004 מה דינו: \u0003ר' יוחנן אמר: אסור מן התורה, ריש לקיש אמר: מותר מן התורה.\u0004 ומפרטים: \u0003ר' יוחנן אמר: אסור מן התורה,\u0004 וטעמו: \u0003כיון דחזי לאיצטרופי\u0004 \u0005[שהוא ראוי להצטרף]\u0006 לחצי שיעור אחר, ולהוות שיעור שלם ויהא בו עונש מן התורה אם כן גם כעת \u0003איסורא קא אכיל\u0004 \u0005[דבר איסור הוא אוכל].\u0006 \u0003ריש לקיש אמר: מותר מן התורה,\u0004 וטעמו: לשון \u0003\"אכילה\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 בכל איסורי אכילה \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 אכילה, שכלל בידינו שאין אכילה בפחות מכשיעור כזית.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו בענין איסור חלב: \u0003אין לי אלא כל שישנו בעונש\u0004 כרת על אכילת חלב הוא ש\u0003ישנו באזהרה\u0004 באיסור לא תעשה על אכילתו, אבל \u0003כוי\u0004 שהוא ספק בהמה ספק חיה \u0003וחצי שיעור, הואיל ואינו בעונש — יכול אינו\u0004 אף \u0003באזהרה — תלמוד לומר: \"כל חלב\"\u0004 (ויקרא ז, כג), משמע: כל חלב שהוא, ובכלל זה גם חלב של ספק, וגם חצי שיעור חלב. הרי שחצי שיעור יש בו איסור מן התורה! את ההוכחה הזו דוחה ריש לקיש: איסור זה אינו אלא \u0003מדרבנן\u0004 (מדברי סופרים) \u0003וקרא\u0004 \u0005[והכתוב]\u0006 המובא לראיה \u0005—\u0006 אינו אלא \u0003אסמכתא בעלמא\u0004 \u0005[בלבד]\u0006 לרמז ולזכרון, אבל אין הכוונה לומר שמדברי תורה יש בכך איסור.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר שברייתא זו משתמשת בכתוב רק לצורך סיוע בדרך רמז בלבד, ולא כמקור וראיה לאיסור, \u0003דאי סלקא דעתך דאורייתא\u0004 \u0005[שאם יעלה על דעתך לומר\u0006 שמדרש זה הוא \u0005מן התורה]\u0006 הלא \u0003כוי ספיקא\u0004 \u0005[ספק]\u0006 בלבד \u0003הוא,\u0004 שאיננו יודעים אם הוא מין חיה או בהמה, והאם \u0003איצטריך קרא לאתויי ספיקא\u0004 \u0005[צריך כתוב\u0006 מיוחד \u0005להביא את הספק]?\u0006 והלא כלל בידינו שכל ספק מן התורה דנים בו לחומרה, ואין הכוי יוצא מכלל כל הספיקות, אלא ודאי הפסוק שהביאה הברייתא אינו אלא לאסמכתא בלבד. ומשיבים: \u0003אי משום הא\u0004 \u0005[אם משום כך],\u0006 מפני הוכחה זו \u0005—\u0006 \u0003לא איריא\u0004 \u0005[אינו שייך],\u0006 שאין זו ראיה גמורה, שהרי אפשר לפרש כי \u0003קסברי\u0004 \u0005[סבורים]\u0006 החכמים בעלי ברייתא זו"],["כי \u0003כוי בריה בפני עצמה היא\u0004 שאין הדבר רק בגדר ספק אם חיה או בהמה הוא, אלא מין יצור מיוחד הוא, שאין שייכותו להגדרת חיה ובהמה ברורה כל עיקר. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 שיש להבין שכוי נחשב לפי דעה מסויימת כבריה בפני עצמה, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב אידי בר אבין\u0004 כי \u0003אף \"כל\"\u0004 שנאמר באיסור אכילת דם (\"כל דם לא תאכלו לעוף ולבהמה\") בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 את ה\u0003כוי,\u0004 והלא \u0003כוי ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא,\u0004 וכי \u0003איצטריך קרא לרבויי ספיקא\u0004 \u0005[הצטרך הכתוב לרבות\u0006 את ה\u0005ספק]?\u0006 \u0003אלא\u0004 ודאי היא נחשבת כ\u0003בריה\u0004 בפני עצמה ולכך \u0003שאני\u0004 \u0005[שונה]\u0006 ולכן צריך מקרא מיוחד כדי לרבותה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יכול אתה לומר ש\u0003בריה שאני\u0004 \u0005[שונה].\u0006 ולכן אין לדחות מכאן את דברי ריש לקיש.","לאחר בירור לשון המשנה באים למדרש הלכה המבסס את עיקרי הדינים הכתובים בה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \"והיתה לכם לחוקת עולם בחודש השביעי בעשור לחודש \u0003תענו את נפשתיכם\"\u0004 (ויקרא טז, כט). \u0003יכול ישב בחמה או בצנה כדי שיצטער\u0004 ויענה את נפשו — \u0003תלמוד לומר: \"וכל מלאכה לא תעשו\u0004 האזרח והגר הגר בתוככם\" (ויקרא טז, כט). ללמדנו: \u0003מה מלאכה שב ואל תעשה,\u0004 שלא נצטוינו לעשות מעשה כלשהו, אלא להימנע ממעשה — \u0003אף ענוי נפש שב ואל תעשה,\u0004 שאין אדם מחוייב לעשות דבר כדי לענות את נפשו אלא רק להימנע ממעשה, כגון מאכילה ושתיה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003היכא דיתיב בשימשא וחיים ליה\u0004 \u0005[היכן שיושב\u0006 אדם \u0005בשמש וחם לו]\u0006 \u0003לא נימא ליה קום תוב בטולא\u0004 \u0005[נאמר לו קום שב בצל],\u0006 אי \u0003יתיב בטולא וקריר ליה\u0004 \u0005[אם יושב בצל וקר לו]\u0006 \u0003לא נימא ליה קום תוב בשימשא\u0004 \u0005[נאמר לו קום שב בשמש],\u0006 שיש כאן שב ואל תעשה, ונאמר שהוא בכלל חובת העינוי! ודוחים: לא! \u0003דומיא\u0004 \u0005[בדומה]\u0006 לאיסור \u0003מלאכה, מה\u0004 איסור \u0003מלאכה לא חלקת בה\u0004 שמהות מלאכה היא האסורה ואין הדבר תלוי במצבו באותה שעה — \u0003אף ענוי לא תחלוק בו\u0004 שעינוי זה הוא בדבר שממהותו הוא שב ואל תעשה, ולא במקרה מיוחד כלשהו.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 נאמר: \u0003\"תענו את נפשתיכם\"\u0004 (ויקרא טז, כט), \u0003יכול ישב בחמה ובצנה ויצטער — תלמוד לומר: \"וכל מלאכה לא תעשו\"\u0004 (ויקרא טז, כט), \u0003מה מלאכה דבר שחייבין עליו\u0004 כרת \u0003במקום אחר\u0004 כגון בשבת, \u0003אף ענוי נפש\u0004 חייבים להתענות מדבר \u0003שחייבין עליו\u0004 כרת \u0003במקום אחר, ואי זה זה? זה פגול ונותר\u0004 שיש חיוב כרת באכילתם, ועליהם נאמר שצריך להתענות מהם ביום הכיפורים.","ומרחיבים את הלימוד: \u0003אביא פגול ונותר שהן\u0004 באיסור \u0003כרת\u0004 לאוכל אותם בכל ימות השנה, \u0003ולא אביא את הטבל שאינו בכרת\u0004 לזה שאוכלו, \u0003תלמוד לומר:\u0004 נאמר: \u0003\"תענו\",\u0004 ונאמר: \u0003\"ועניתם את נפשתיכם\"\u0004 (ויקרא טז, כט), \u0003ריבה\u0004 לעוד עינויי נפש שיש באכילתם איסור חמור.","ועוד: \u0003אביא הטבל שהוא במיתה\u0004 שהאוכלו חייב מיתה בידי שמים \u0003ולא אביא את הנבילה שאינה במיתה\u0004 לזה שאוכלה — \u0003תלמוד לומר \"תענו\" \"ועניתם את נפשתיכם\" — ריבה\u0004 אף אלה שיש בהם איסור ואין חייבים עליו מיתה.","\u0003אביא את הנבילה, שהוא\u0004 על כל פנים באיסור \u0003לאו\u0004 (לא תעשה) \u0003ולא אביא את החולין\u0004 סתם מאכלים שאין בהם כל איסור, \u0003שאינן בלאו? תלמוד לומר: \"תענו\" \"ועניתם את נפשתיכם\" — ריבה,\u0004 שיש להתענות אף מחולין שאין בהם כל איסור\u0003.\u0004","ועוד נרחיב: \u0003אביא\u0004 את \u0003החולין שאינן\u0004 בכל מקום \u0003בקום אכול,\u0004 שאין מצוה מיוחדת על האדם לאכול חולין, \u0003ולא אביא את התרומה שהיא בקום אכול,\u0004 שהרי מצווים הכהנים על אכילתה — \u0003תלמוד לומר: \"תענו\" \"ועניתם את נפשתיכם\" — ריבה. אביא את התרומה שאינה ב\"בל תותירו\"\u0004 שאינו חייב לאכלה דווקא בתוך זמן מוגדר, \u0003ולא אביא את הקדשים\u0004 שלא רק שיש מצוה באכילתן אלא גם \u0003הן ב\"בל תותירו\",\u0004 שיש איסור אם הוא מותיר מהם לאחר הזמן הראוי להם. — \u0003תלמוד לומר \"תענו\" \"ועניתם את נפשתיכם\" — ריבה.\u0004 הרי בדרך של ריבוי בשלבים למדים אנו שכל מיני אוכל אסורים ביום הכיפורים.","\u0003ואם נפשך לומר\u0004 דבר כדי להקשות על לימוד זה, אביא לך ראיה אחרת: \u0003הרי הוא אומר\u0004 במחלל יום הכיפורים: \u0003\"והאבדתי את הנפש ההוא\"\u0004 (ויקרא כג, ל), הרי שמהות העינוי הוא \u0003ענוי שהוא אבידת הנפש, ואי זה זה — זה אכילה ושתיה,\u0004 שאם אינו אוכל ושותה כלל הריהו מת, ואין מדובר בעינויים אחרים שאין בהם משום איבוד נפש. עד כאן לשון הברייתא.","ומבארים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003\"ואם נפשך לומר\",\u0004 כלומר: מה היתה אותה טענה שאפשר לטעון כנגד המדרש הראשון? וכך יש לבאר: \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 הרי \u0003בעריות קא מישתעי קרא\u0004 \u0005[מדבר הכתוב],\u0006 שאין הכתוב מדבר כלל בעינוי מאכילה ושתיה, אלא בהמנעות מתשמיש שאף הוא קרוי עינוי — לכך \u0003הרי הוא אומר: \"והאבדתי את הנפש\",\u0004 לומר: \u0003ענוי שיש בו אבידת נפש, ואי זה זה — זה\u0004 המנעות \u0003מאכילה ושתיה.\u0004","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 ולמד את מהות בעינוי ביום הכיפורים באופן זה: \u0003נאמר כאן\u0004 ביום הכיפורים מצות \u0003\"ענוי\" ונאמר להלן\u0004 במקום אחר \u0003\"ענוי\"\u0004 (\"ויענך וירעיבך\". דברים ח, ג) \u0003מה להלן ענוי\u0004 הכוונה לעינוי של \u0003רעבון — אף כאן\u0004 מדובר ב\u0003ענוי רעבון.\u0004","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 לא מן המקרא שמשמעותו עינוי של רעב, אלא ממה שנאמר: \u0003\"אם תענה את בנתי\"\u0004 (בראשית לא, נ), שלפי עניינו אינו ענין של רעב אלא בענייני תשמיש? ומשיבים: \u0003דנין\u0004 ולמדים \u0003ענוי\u0004 שנאמר ל\u0003רבים\u0004 (עינוי יום הכיפורים) \u0003מענוי\u0004 שנאמר ל\u0003רבים\u0004 לעם ישראל במדבר, \u0003ואין דנין ענוי\u0004 של \u0003רבים מענוי\u0004 של \u0003יחיד\u0004 שנאמר בנשי יעקב.","ומקשים מצד אחר: אם כן \u0003ונילף\u0004 \u0005[שנלמד]\u0006 \u0003מענוי\u0004 שנאמר \u0003במצרים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וירא את ענינו\"\u0004 (דברים כו, ז) \u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 בפירוש הביטוי: \u0003זו פרישות דרך ארץ,\u0004 כלומר: פרישות מתשמיש, שנכפתה על ישראל בידי המצריים, ואם כן הרי לנו עינוי של רבים שאינו בהמנעות מאכילה! \u0003אלא\u0004 יש ללמוד לא כפי שאמרנו, ולומר כך: \u0003דנין ענוי בידי שמים מענוי בידי שמים\u0004 שבשניהם הדבר בא מידי או בציווי הקדוש ברוך הוא, \u0003ואין דנין ענוי בידי שמים מענוי\u0004 ש\u0003בידי אדם.\u0004","כיון שהבאנו את הפסוק \"ויענך וירעיבך ויאכילך את המן\" מפרשים את המקראות בענין זה בכמה פנים. נאמר: \u0003\"המאכלך מן במדבר\u0004 אשר לא ידעון אבותיך \u0003למען ענתך\"\u0004 (דברים ח, טז) והתמיהה ברורה: מה עינוי יש באכילת המן? \u0003ר' אמי ור' אסי\u0004 נחלקו בדבר, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: אינו דומה מי שיש לו פת בסלו למי שאין לו פת בסלו,\u0004 והעינוי שבאכילת המן היה בכך שלא היה מן מוכן למחרת, והיה כל אדם דואג למה שיהיה למחר, והוא העינוי שבמן. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אינו דומה מי שרואה ואוכל למי שאינו רואה ואוכל.\u0004 שאף שניתן היה לחוש במן כל טעם שרצו, אך כיון שלמראה עיניהם היה כל הזמן רק מן, היה בכך משום עינוי.","\u0003אמר רב יוסף: מכאן,\u0004 מדברי חכמים אלה, \u0003רמז לסומין\u0004 (לעוורים) \u0003שאוכלין ואין שבעין\u0004 לגמרי, משום שאינם רואים את מאכלם. שאף בראיית המאכל יש כדי לגרום לתחושת השובע בנוסף לאכילתו. \u0003אמר אביי: הלכך\u0004 (על כן) מכל הדברים שלמדנו, \u0003מאן דאית ליה סעודתא\u0004 \u0005[מי שיש לו סעודה]\u0006 מצומצמת \u0003לא ליכלה\u0004 \u0005[יאכלנה]\u0006 \u0003אלא ביממא\u0004 \u0005[ביום],\u0006 שאוכל הנאכל באור וניתן לראותו משביע יותר מזה הנאכל בחשיכה. \u0003אמר ר' זירא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על רעיון זה — \u0003\"טוב מראה עינים מהלך נפש\"\u0004 (קהלת ו, ט). על אותו פסוק \u0003אמר ריש לקיש: טוב מראה עינים באשה יותר מגופו של מעשה\u0004 (תשמיש), \u0003שנאמר: \"טוב מראה עינים מהלך נפש\".\u0004","כיון שהבאנו כאן מחלוקת בפירוש הפסוק של שני האמוראים החברים ר' אמי ור' אסי, מביאים עוד מחלוקת דומה: נאמר: \u0003\"כי יתן בכוס עינו יתהלך במישרים\"\u0004 (משלי כג, לא) \u0003ר' אמי ור' אסי\u0004 נחלקו; \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: כל הנותן\u0004"],["\u0003עינו בכוסו\u0004 כלומר משתכר, כל איסורי \u0003עריות כולן דומות עליו כמישור,\u0004 שאינו חש שיש מכשול בעבירות והולך בדרכו אף במקום מעוקש ומסוכן. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: כל הנותן עינו בכוסו כל העולם כולו דומה עליו כמישור,\u0004 שלא רק איסורי ערוה אין חשובים בעיניו, אלא אף שאר האיסורים, כאיסורי ממונות וכדומה נראים קלים בעיניו.","ועוד בפירוש הכתוב; נאמר: \u0003\"דאגה בלב איש ישחנה\"\u0004 (משלי יב, כה), ונחלקו \u0003ר' אמי ור' אסי\u0004 בפירוש הכתוב. \u0003חד\u0004 \u0005[אחד]\u0006 \u0003אמר: ישחנה מדעתו,\u0004 שלדעתו הכוונה היא שאדם דואג ראוי לו להסיח דעתו מדאגתו, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר:\u0004 שהכוונה היא \u0003ישיחנה\u0004 (יספר אותה) \u0003לאחרים,\u0004 ויוקל לו.","ועוד נאמר: \u0003\"ונחש עפר לחמו\"\u0004 (ישעיה סה, כה), ואף בפירוש כתוב זה נחלקו \u0003ר' אמי ור' אסי, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: אפילו אוכל\u0004 הנחש \u0003כל מעדני עולם — טועם בהם טעם עפר, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אפילו אוכל כל מעדני עולם אין דעתו מיושבת עליו עד שיאכל\u0004 גם מעט \u0003עפר.\u0004","באותו ענין \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' יוסי: בוא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם. מדת בשר ודם\u0004 מה היא? אדם \u0003מקניט את חבירו\u0004 — הרי הוא \u0003יורד עמו לחייו\u0004 ומציק לו בכל דבר, \u0003אבל הקדוש ברוך הוא אינו כן,\u0004 הרי \u0003קלל את הנחש\u0004 ומה אירע לו, \u0003עולה\u0004 הנחש \u0003לגג — מזונותיו עמו, יורד למטה — מזונותיו עמו,\u0004 שהקללה שקללו אינה מקפחת את חייו, ואף יש בה כמה יתרונות.","וכן \u0003קלל את כנען\u0004 שיהא עבד עבדים, ויש לו בזה אף הנאה מסויימת, כי \u0003אוכל מה שרבו אוכל ושותה מה שרבו שותה\u0004 ואינו צריך לדאוג לעצמו כבני חורין. \u0003קלל את האשה — הכל רצין אחריה. קלל את האדמה — הכל ניזונין הימנה\u0004 \u0005[ממנה].\u0006 שאף בשעת כעס אין הקדוש ברוך הוא מעניש את הבריות בעונש חמור מדי.","ועוד באותו ענין, בפירוש הכתוב \u0003\"זכרנו את הדגה אשר נאכל במצרים חנם\"\u0004 (במדבר יא, ה), נחלקו \u0003רב ושמואל, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר:\u0004 הכונה היתה כפשוטה \u0003דגים, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר:\u0004 רמזו בדבר לאיסורי \u0003עריות,\u0004 שעוד לא נאסרו בדבר זה, ובכו על שאסרה עליהם התורה. ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 שהכוונה ל\u0003דגים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נאכל\",\u0004 פשוטו כמשמעו. \u0003ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 שהכוונה ל\u0003עריות — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"חנם\".\u0004 שלדעתו ודאי לא היו אוכלים דגים של ממש חינם.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ו\u0006לשיטת \u0005מי שאומר]\u0006 שהכוונה היא \u0003עריות, הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"נאכל\"!\u0004 ומשיבים: \u0003לישנא מעליא נקט\u0004 \u0005[לשון מעולה,\u0006 נקיה, \u0005תפס],\u0006 שלא לומר לשון תשמיש במפורש, וראיה לשימוש לשון זה בענין תשמיש — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 על האשה הרעה: \u0003\"אכלה ומחתה פיה ואמרה לא פעלתי און\"\u0004 (משלי ל, כ), ששם בודאי הוא רמז לתשמיש. \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 שהכוונה ל\u0003דגים, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חנם\" — דהוו מייתין להו מהפקירא\u0004 \u0005[שהיו מביאים אותם מן ההפקר],\u0006 כי ודאי שלא היו המצריים מפרנסים אותם בדגים חינם, אלא שהם היו מוצאים דגים בנהר. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כשהיו ישראל שואבין מים,\u0004 היה \u0003הקדוש ברוך הוא מזמין להם בתוך המים דגים קטנים בכדיהן.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שעל ה\u0003דגים\u0004 ממש בכו, \u0003אבל עריות לא פריצי\u0004 \u0005[פרוצים]\u0006 היו \u0003בהו\u0004 \u0005[בהם]\u0006 אף במצרים — \u0003היינו דכתב\u0004 \u0005[זהו שאמר]\u0006 הכתוב בשבח ישראל בלשון מליצה: \u0003\"גן נעול אחתי כלה\u0004 גל נעול מעין חתום\" (שיר השירים ד, יב), ללמד שבנות ישראל היו כגן נעול שאין הכל דורכים בו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי הכוונה ל\u0003עריות, — מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מעין חתום\"?\u0004 ומשיבים: \u0003מהנך דאסירין לא פריצי בהו\u0004 \u0005[מאותן שהיו אסורות להם לא היו פרוצים בהם],\u0006 ששמרו על דיני העריות האסורים לבני נח ובכו על האיסורים הנוספים שיש בדיני ישראל.","ושואלים עוד: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהכוונה ל\u0003עריות — היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"וישמע משה את העם בכה למשפחתיו\"\u0004 (במדבר יא, י) וכוונתו: \u0003על עסקי משפחותיו, שנאסרו להם לשכב אצלם. אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהכוונה ל\u0003דגים, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בוכה למשפחותיו\",\u0004 מה ענין משפחות לכאן? ומשיבים: \u0003הא והא הואי\u0004 \u0005[זה וזה היה]\u0006 שבכו גם על דיני עריות, וגם על המן כפשוטו.","ועוד בפירושי המקראות בענין זה. נאמר: \u0003\"את הקשאים ואת האבטחים\u0004 ואת החציר ואת הבצלים ואת השומים\u0003\"\u0004 (במדבר יא, ח), \u0003ר' אמי ור' אסי\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: טעם כל המינין טעמו במן,\u0004 ואילו \u0003טעם חמשת המינין הללו\u0004 שהזכירו בדבריהם \u0003לא טעמו בו\u0004 ומשום כך בכו, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: טעם כל המינין טעמו טעמן וממשן,\u0004 כלומר: שהתחושה היתה כה חזקה שהיה נראה להם כאילו טועמין ממשן, אבל במינים אלה טעמו את \u0003טעמן ולא ממשן.\u0004","ועוד לענין המן, נאמר: \u0003\"והוא כזרע גד לבן וטעמו\u0004 כצפיחית בדבש\" (שמות טז, לא). \u0003אמר ר' אסי: עגול\u0004 היה המן \u0003כגידא\u0004 \u0005[כמו\u0006 זרע \u0005הגד]\u0006 \u0003ולבן כמרגלית,\u0004 ולא שחור כגד. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גד — שדומה לזרע פשתן בגבעולין,\u0004 שהוא אגוד.","\u0003אחרים אומרים:\u0004 נקרא \u0003גד — שדומה להגדה, שמושכת לבו של אדם כמים. תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 למה נקרא \u0003גד — שמגיד להם לישראל\u0004 כל דבר של ספק. כגון: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בן תשעה לראשון ואי\u0004 \u0005[או]\u0006 \u0003בן שבעה לאחרון.\u0004 שאם נישאה אשה תוך חודשיים מגירושיה או ממות בעלה לאיש אחר, וילדה לאחר שבעה חדשים, ולא ברור אם הילד הוא בן שבעה חדשים לבעלה השני או בן תשעה חדשים לבעלה הראשון, וכיון שהמן היה בא לכל משפחה לפי גולגולת היה מתברר על ידו לאיזה משפחה שייך הילד.","ולמה נקרא המן \u0003\"לבן\" — שמלבין עונותיהן של ישראל\u0004 שמתוך שחששו שבשל חטאיהם לא ירד להם מן, לכך היו עסוקים תמיד בהרהור על מעשיהם ובחזרה בתשובה.","מעין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יוסי אומר: כשם שהנביא היה מגיד להם לישראל מה שבחורין ומה שבסדקין, כך המן מגיד להם לישראל מה שבחורין ומה שבסדקין. כיצד? שנים שבאו לפני משה לדין, זה אומר: עבדי גנבת, וזה אומר:\u0004 לא גנבתיו אלא \u0003אתה מכרתו לי. אמר להם משה: לבקר משפט.\u0004 וכיצד מתברר הדבר? \u0003למחר אם נמצא עומרו בבית רבו ראשון — בידוע שזה גנבו,\u0004 שהרי המן מגיע עוד לבעליו הראשון. \u0003ואם נמצא עומרו בבית רבו שני — בידוע שזה מכרו לו.\u0004","\u0003וכן\u0004 אם \u0003איש ואשה שבאו לפני משה לדין, זה אומר היא סרחה\u0004 (פשעה) \u0003עלי\u0004 וראוי לגרשה, \u0003והיא אומרת הוא סרח\u0004 (פשע) \u0003עלי\u0004 ואני אינני אשמה, ורצונה שיגרשנה ויתן כתובתה. \u0003אמר להם משה: לבקר משפט. למחר, אם נמצא עומרה בבית בעלה — בידוע שהיא סרחה עליו, נמצא עומרה בבית אביה בידוע שהוא סרח עליה.\u0004","\u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וברדת הטל על המחנה לילה ירד המן עליו\"\u0004 (במדבר יא, ט), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויצא העם ולקטו\"\u0004 (שמות טז, ד), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"שטו העם ולקטו\"\u0004 (במדבר יא, ח), \u0003הא כיצד\u0004 ניישב את הלשונות השונים הללו? \u0003צדיקים\u0004 שבישראל \u0003ירד\u0004 המן \u0003על פתח בתיהם\u0004 ולא הוצרכו לטרוח כלל. \u0003בינונים יצאו\u0004 מחוץ למחנה \u0003ולקטו\u0004 מה שהיה מכונס להם שם. \u0003רשעים שטו\u0004 היו צריכים להלך הרבה \u0003ולקטו.\u0004","\u0003כתיב\u0004 \u0005[נאמר]\u0006 בו במן לשון \u0003\"לחם\"\u0004 (שמות טז, ד) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בו לשון \u0003\"עגות\"\u0004 (במדבר יא, ח) \u0003וכתיב \"וטחנו\u0004 בריחים\" (במדבר יא, ח), \u0003הא כיצד\u0004 ניישב את התיאורים השונים? ל\u0003צדיקים\u0004 היה יורד כ\u0003לחם\u0004 אפוי, ל\u0003בינונים\u0004 היה יורד כ\u0003עוגות,\u0004 ככרות בלתי אפויים, ל\u0003רשעים\u0004 היה בא כצורתו ולכן \u0003\"טחנו בריחים\".\u0004","נאמר כאן: \u0003\"או דכו במדכה\"\u0004 (במדבר יא, ח), \u0003אמר רב יהודה אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' חמא בר' חנינא: מלמד שירד להם לישראל עם המן תכשיטי נשים\u0004 (מיני בשמים), שהם \u0003דבר שנידוך במדוכה.\u0004 נאמר: \u0003\"ובשלו בפרור\"\u0004 (במדבר יא, ח), \u0003אמר ר' חמא: מלמד שירד להם לישראל עם המן ציקי קדירה\u0004 שהם תוספות שמוסיפים בתוך תבשיל.","בתרומת המשכן נאמר: \u0003\"והם הביאו אליו עוד נדבה בבקר בבקר\"\u0004 (שמות לו, ג), ושאלו \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בבקר בבקר\"? אמר ר' שמואל בר נחמני אמר ר' יונתן:\u0004 הביאו \u0003מדבר שירד להם\u0004 עם המן שהיה יורד \u0003\"בבקר בבקר\". מלמד שירדו להם לישראל אבנים טובות ומרגליות עם המן.\u0004 נאמר שם: \u0003\"והנשאם הביאו את אבני השהם\"\u0004 (שמות לה, כז) \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003נשיאים\u0004 (עננים) \u0003ממש\u0004 הם שהביאו להם. \u0003וכן הוא אומר: \"נשיאים ורוח וגשם אין\"\u0004 (משלי כה, יד) והרי אנו למדים ש\"נשיאים\" הם עננים והם שהיו מביאים איתם את האבנים הטובות.","עוד נאמר במן: \u0003\"והיה טעמו כטעם לשד השמן\"\u0004 (במדבר יא, ח). \u0003אמר ר' אבהו:\u0004 \"לשד\" פירושו כמו \"שד\" \u0003מה שד זה תינוק טועם בה כמה טעמים\u0004 שהוא נהנה מכל מה שאימו אוכלת, \u0003אף המן, כל זמן שישראל אוכלין אותו — מוצאין בו כמה טעמים\u0004 כפי רצונם. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003לשד ממש,\u0004 כיצד? \u0003מה שד זה מתהפך לכמה גוונין\u0004 (צורות וצבעים) — \u0003אף המן מתהפך לכמה טעמים.\u0004","נאמר: \u0003\"ויאמר משה בתת ה' לכם בערב בשר לאכל ולחם בבקר לשבע\"\u0004 (שמות טז, ח), \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהושע בן קרחה: בשר ששאלו\u0004 ישראל \u0003שלא כהוגן,\u0004 שהרי אין הבשר חיוני לאדם — אף \u0003ניתן להם שלא כהוגן\u0004 שלא בדרך נוחה, והיו צריכים ללקט ולשטוח אותו."],["ואילו \u0003לחם ששאלו כהוגן,\u0004 שהרי הוא חיוני, \u0003ניתן להם כהוגן\u0004 בשעות הבוקר שיש שהות להכינו. ובדרך אגב: \u0003מכאן למדה תורה דרך ארץ שלא יאכל אדם בשר אלא בלילה,\u0004 שכן אמר משה לבני ישראל: \"בערב בשר לאכול\" (שמות טז, ח). ושואלים: \u0003והאמר\u0004 \u0005[והרי\u0006 כבר \u0005אמר]\u0006 \u0003אביי: האי מאן דאית ליה סעודתא\u0004 \u0005[מי שיש לו סעודה] —\u0006 \u0003לא לאכליה\u0004 \u0005[שלא יאכל אותה]\u0006 \u0003אלא ביממא\u0004 \u0005[ביום]!\u0006 ומשיבים: \u0003כעין יממא קא אמרינן\u0004 \u0005[כעין יום אומרים אנו],\u0006 שאין להקפיד שיהא האוכל ביום דווקא, ועיקר הוא שיהא לו אור בשעת סעודתו. \u0003אמר רב אחא בר יעקב: בתחלה היו ישראל דומין כתרנגולים שמנקרין באשפה,\u0004 שכל זמן שיש אוכל היו חוטפים ואוכלים, \u0003עד שבא משה וקבע להן זמן סעודה,\u0004 וכפי שאמר בכתוב, שקבע להם זמנים בבוקר ובערב לארוחה.","נאמר בפרשת השליו: \u0003\"הבשר עודנו בין שניהם\u0004 ויך ה' בעם מכה רבה מאד\" (במדבר יא, לג), משמע שמתו מיד, ונאמר \u0003\"עד חדש ימים\u0004 עד אשר יצא מאפכם והיה לכם לזרא\" (במדבר יא, כ), \u0003הא כיצד\u0004 מיישבים את הכתובים? \u0003בינונים\u0004 שבהם \u0003לאלתר\u0004 (מיד) \u0003מתו. רשעים\u0004 היו \u0003מצטערין והולכין עד חדש ימים\u0004 ביסורין ומתו אחר כך.","נאמר: \u0003\"וישטחו להם שטוח\"\u0004 (במדבר יא, לב). על זה \u0003אמר ריש לקיש: אל תקרי \"וישטחו\" אלא \"וישחטו\" — מלמד שנתחייבו שונאיהן של ישראל\u0004 (בלשון נקיה, והכוונה לישראל) \u0003שחיטה\u0004 בגלל דרישה זו. \u0003\"שטוח\", תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהושע בן קרחה: אל תיקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שטוח\" אלא \"שחוט\", מלמד שירד להם לישראל עם המן דבר שטעון שחיטה,\u0004 כלומר: מיני עופות. \u0003אמר רבי: וכי מכאן אתה למד\u0004 וצריך לעקם את לשון הכתוב לצורך זה? \u0003והלא כבר נאמר\u0004 בפירוש: \u0003\"וימטר עליהם כעפר שאר וכחול ימים עוף כנף\"\u0004 (תהלים עח, כז).","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 אחרת קצת בקשר לזה \u0003רבי אומר:\u0004 נאמר: \u0003\"וזבחת\u0004 מבקרך ומצאנך אשר נתן ה' לך \u0003כאשר צויתך\"\u0004 (דברים יב, כא) \u0003מלמד שנצטוה משה\u0004 על דיני שחיטה שיש לשחוט את \u0003הושט\u0004 ואת \u0003הקנה\u0004 שבצוואר \u0003ועל\u0004 שחיטת \u0003רוב אחד\u0004 משני אלה \u0003בעוף, ועל רוב שנים בבהמה,\u0004 ושאר דיני שחיטה. וכיון שלשיטת רבי אין אנו למדים מ\"שטוח\" לענין שחיטה, \u0003אלא מה תלמוד לומר \"שטוח\" — מלמד שירד להם משטיחין משטיחין\u0004 (משטחים משטחים) בשורה ישרה.","נאמר במן: \u0003\"לחם\"\u0004 (שמות טז, ד), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"שמן\"\u0004 (במדבר יא, ח), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"דבש\"\u0004 (שמות טז, לא). \u0003אמר ר' יוסי בר' חנינא: לנערים\u0004 היה כ\u0003לחם, לזקנים —\u0004 כ\u0003שמן, לתינוקות —\u0004 כ\u0003דבש,\u0004 כל אחד כפי שערב לו.","ומעירים עוד: \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"שליו\"\u0004 ב\"ש\" \u0003וקרינן\u0004 \u0005[ואנו קוראים]\u0006 ב\"ש\" כמו \u0003סליו,\u0004 ומה בא הדבר ללמדנו? \u0003אמר ר' חנינא: צדיקים אוכלין אותו בשלוה\u0004 והרי הוא להם שליו כפי הכתיב, \u0003רשעים אוכלין אותו ודומה להן כסילוין\u0004 (כקוצים) והוא להם כפי הקרי סליו.","ועוד בענין השליו: \u0003אמר רב חנין בר רבא: ארבעה מיני סליו הן, ואלו הן: שיכלי, וקיבלי, ופסיוני, ושליו. מעליא דכולהו\u0004 \u0005[המעולה שבכולם]\u0006 בטעמו: \u0003שיכלי, גריעא דכולהו\u0004 \u0005[הגרוע שבכולם]\u0006 הוא ה\u0003שליו.\u0004 ומספרים עד כמה יפה טעמו של השלו \u0003והוי כציפורתא\u0004 \u0005[והוא\u0006 גדול \u0005כציפור]\u0006 \u0003ומותבינן לה בתנורא ותפח והוה מלי תנורא\u0004 \u0005[מושיבים,\u0006 מניחים, \u0005אותו בתנור\u0006 להיצלות \u0005והוא תופח\u0006 עד \u0005שהוא ממלא את התנור],\u0006 \u0003ומסקינן ליה אתליסר ריפי\u0004 \u0005[ומניחים אותו על שלושה עשר ככרות\u0006 לחם\u0005]\u0006 ואף ככר \u0003אחרונה\u0004 שלמטה מכולן \u0003אינה נאכלת אלא על ידי תערובת,\u0004 מרוב השומן שיש בה.","מסופר: \u0003רב יהודה משתכח ליה בי דני\u0004 \u0005[\u0006היה \u0005נמצא\u0006 לו שליו \u0005בין חביות היין\u0006 שלו\u0005]\u0006 ו\u0003רב חסדא משתכח ליה בי ציבי\u0004 \u0005[\u0006היה \u0005נמצא\u0006 לו השליו \u0005בין העצים\u0006 במחסנו\u0005],\u0006 \u0003רבא מייתי ליה אריסיה כל יומא\u0004 \u0005[היה מביא לו אריסו כל יום]\u0006 שליו אחד שהיה מוצא בשדותיו. \u0003יומא חד לא אייתי\u0004 \u0005[יום אחד לא הביא],\u0006 שאותו היום לא מצא. \u0003אמר\u0004 רבא בליבו: \u0003מאי האי\u0004 \u0005[מה זה]\u0006 נשתנה היום מכל הימים? \u0003סליק לאיגרא\u0004 \u0005[עלה לגג]\u0006 להרהר בדבר, \u0003שמעיה לינוקא דקאמר\u0004 \u0005[שמע תינוק שאומר]\u0006 וחוזר על הפסוק: \u0003\"שמעתי ותרגז בטני\u0004 לקול צללו שפתי יבוא רקב בעצמי ותחתי ארגז אשר אנוח ליום צרה לעלות לעם יגודנו\" (חבקוק ג, טז). \u0003אמר\u0004 רבא: \u0003שמע מניה נח נפשיה\u0004 \u0005[למד מכאן שנחה נפשו,\u0006 נפטר\u0005],\u0006 \u0003רב חסדא\u0004 ולכן איני ראוי עוד לשליו, כי \u0003בדיל רבה אכיל תלמידא\u0004 \u0005[בשל הרב אכל התלמיד],\u0006 שכל עוד היה רב חסדא בחיים הרי בזכותו היו מביאים גם לי שליו, ועכשיו שנפטר שוב איני ראוי לכך.","ועוד לענין המן, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ותעל שכבת הטל\u0004 והנה על פני המדבר דק מחוספס דק ככפור על הארץ\" (שמות טז, יד), הרי שהטל היה מכסה את המן, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וברדת הטל\u0004 על המחנה לילה ירד המן עליו\" (במדבר יא, ט), שהמן היה מעל הטל, וכיצד מיישבים את הכתובים? \u0003אמר ר' יוסי בר' חנינא:\u0004 כך היה: \u0003טל מלמעלה, וטל מלמטה\u0004 והמן באמצע, \u0003ודומה כמו שמונח בקופסא\u0004 של טל.","נאמר בו \u0003\"דק מחספס\"\u0004 (שמות טז, יד) \u0003אמר ריש לקיש:\u0004 מחוספס הוא \u0003דבר שנימוח\u0004 (\"מח\") \u0003על פיסת\u0004 (\"פס\") \u0003היד\u0004 שהיה רך מאד והיה נמס מיד בהגיעו לכף היד. \u0003ר' יוחנן אמר: דבר שנבלע במאתים וארבעים ושמונה אברים\u0004 כמנין \"מחספס\" ותוהים: \u0003מחוספס\u0004 אם חושב אתה את כל האותיות \u0003טובא הוי\u0004 \u0005[יותר הוא]\u0006 ממאתים ארבעים ושמונה! \u0003אמר רב נחמן בר יצחק: \"מחספס\"\u0004 חסר \u0003כתיב\u0004 \u0005[נאמר]\u0006 וכפי הכתיב החסר הרי הוא בדיוק מאתים ארבעים ושמונה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \"וימטר עליהם מן לאכול ודגן שמים נתן למו \u0003לחם אבירים אכל איש\"\u0004 (תהלים עח, כד-כה) ופירשוהו: \u0003לחם שמלאכי השרת אוכלין אותו,\u0004 אלו \u0003דברי ר' עקיבא. וכשנאמרו דברים\u0004 אלה \u0003לפני ר' ישמעאל, אמר להם: צאו ואמרו לו לעקיבא: עקיבא טעית! וכי מלאכי השרת אוכלין לחם? והלא כבר נאמר\u0004 במשה שעלה למרום: \u0003\"לחם לא אכלתי ומים לא שתיתי\"\u0004 (דברים ט, ט) ומה אדם העולה למרום אינו זקוק לאכילה ושתיה, מלאכים על אחת כמה וכמה! \u0003אלא, מה אני מקים \"אבירים\"\u0004 יש לפרשו: \u0003לחם שנבלע במאתים וארבעים ושמונה אברים,\u0004 שאין בו כל פסולת.","ושואלים: אם כן \u0003אלא מה אני מקיים\u0004 את מאמר הכתוב: \u0003\"ויתד תהיה לך על אזנך\u0004 והיה בשבתך חוץ וחפרת בה ושבת וכיסית את צאתך\u0003\"\u0004 (דברים כג, יד), וכן מה שנאמר: \"ויד תהיה לך מחוץ למחנה \u0003ויצאת שמה חוץ\"\u0004 (דברים כג, יג), שמכאן אפשר ללמוד שהיתה פסולת במעיהם שהיו צריכים לצאת לצרכיהם. אלא דבר זה לא היה מן המן, כי אם מאותם \u0003דברים שתגרי אומות העולם מוכרין אותן להם\u0004 לאכילה ומהם היתה פסולת.","\u0003ר' אלעזר בן פרטא אומר: אף דברים שתגרי אומות העולם מוכרין להן — מן מפיגן\u0004 שהיה ממיס אותם, וגורם שיתעכל הכל בשלמות. \u0003אלא מה אני מקיים \"ויתד תהיה לך על אזנך\" — לאחר שסרחו\u0004 (שחטאו) ושוב לא היה המן מועיל עד כדי כך, ש\u0003אמר הקדוש ברוך הוא: אני אמרתי\u0004 מתחילה ש\u0003יהיו כמלאכי השרת\u0004 שאינם צריכים ליציאת בני מעים, \u0003עכשיו אני מטריח אותם שלש פרסאות\u0004 לצאת אל מחוץ למחנה לצרכיהם.","ומניין לנו שמחנה ישראל שלש פרסאות היה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויחנו על הירדן מבית הישמת עד אבל השטים\"\u0004 (במדבר לג, מט) \u0003ואמר רבה בר בר חנה: לדידי חזי לי ההוא אתרא\u0004 \u0005[אני עצמי ראיתי מקום זה]\u0006 \u0003והויא\u0004 \u0005[והיה]\u0006 אורכו \u0003תלתא פרסי\u0004 \u0005[שלוש פרסאות].\u0006 \u0003ותנא\u0004 \u0005[ושנינו]:\u0006 \u0003כשנפנין\u0004 היו ישראל במדבר לצרכיהם, \u0003אין נפנין לא לפניהן\u0004 בכיוון הליכתם, \u0003ולא לצדדיהן, אלא לאחוריהן\u0004 אחרי המחנה במקום שעברו בו כבר. ולכן היו כולם צריכים ללכת מרחק זה מחוץ למחנה.","ועוד בפרשת המן, נאמר בתלונת ישראל: \u0003\"ועתה נפשנו יבשה אין כל\u0004 בלתי אל המן עינינו\" (במדבר יא, ו). \u0003אמרו: עתיד מן זה שתיפח במעיהם\u0004 וגורם שם מחלה, \u0003כלום יש ילוד אשה שמכניס\u0004 אוכל \u0003ואינו מוציא\u0004 כלום? לחזק מה שאמרנו שלא היתה במן כל פסולת.","\u0003וכשנאמרו דברים\u0004 של ר' אלעזר בן פרטא \u0003לפני ר' ישמעאל, אמר להם: אל תקרי \"אבירים\" אלא \"איברים\"\u0004 שהוא \u0003דבר שנבלע במאתים וארבעים ושמונה איברים\u0004 ודבר זה היה מתכונתו של המן, \u0003אלא מה אני מקיים \"ויתד תהיה לך על אזנך\" — בדברים שבאין להם ממדינת הים.\u0004","\u0003דבר אחר: \"לחם אבירים אכל איש\"\u0004 —"],["\u0003זה יהושע שירד לו מן כנגד כל ישראל,\u0004 כאשר המתין למשה סמוך להר סיני כל אותם ארבעים יום ששהה משה על ההר. ורמז לדבר: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"איש\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"קח לך את יהושע בן נון איש אשר רוח בו\u0004 וסמכת את ידך עליו\u0003\"\u0004 (במדבר כז, יח), מכאן ש\"איש\" הוא יהושע. ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה היא ל\u0003משה\u0004 עצמו, שנאמר גם בו \u0003\"והאיש משה ענו מאד\"\u0004 (במדבר יב, ג) ומשיבים: \u0003דנין \"איש\" מ\"איש\", ואין דנין איש מ\"והאיש\".\u0004","ועוד לענין המן: \u0003שאלו תלמידיו את ר' שמעון בן יוחי: מפני מה לא ירד להם לישראל מן פעם אחת בשנה\u0004 להספיק כל צרכיהם, והיה צריך לרדת בכל יום מחדש? \u0003אמר להם: אמשול לכם משל; למה הדבר דומה — למלך בשר ודם שיש לו בן אחד, פסק\u0004 (קבע) \u0003לו מזונותיו פעם אחת בשנה\u0004 והיה נותן לו ממון בשביל כל השנה, \u0003ולא היה\u0004 הבן \u0003מקביל פני אביו אלא פעם אחת בשנה\u0004 לפי צורכו. \u0003עמד ופסק מזונותיו בכל יום, והיה מקביל פני אביו כל יום.\u0004","\u0003אף ישראל\u0004 כן, \u0003מי שיש לו ארבעה וחמשה בנים היה דואג ואומר: שמא לא ירד מן למחר, ונמצאו כולן מתים ברעב,\u0004 ולכן \u0003נמצאו כולן מכוונים את לבם לאביהן שבשמים\u0004 בכל יום, ולכן ירד כל יום לצורך אותו יום בלבד, כדי שכל ישראל יכוונו לבם למקום ויבקשו על מזון יום המחר.","\u0003דבר אחר: שהיו אוכלין אותו כשהוא חם\u0004 וטרי. \u0003דבר אחר: מפני משאוי הדרך.\u0004 שהרי לא היו כל אותם שנים קבועים במקום אחד, ואם היו צריכים לשאת מן ממקום למקום היה מכביד עליהם, וכך בכל מקום שהגיעו — ירד להם המן.","מסופר: \u0003וכבר היה ר' טרפון ור' ישמעאל וזקנים יושבין ועוסקין בפרשת המן, והיה ר' אלעזר המודעי יושב ביניהן. נענה ר' אלעזר המודעי ואמר: מן שירד להן לישראל היה גבוה ששים אמה. אמר לו ר' טרפון: מודעי, עד מתי אתה מגבב דברים ומביא עלינו\u0004 דברים שאין להם שחר!","\u0003אמר לו: מקרא אני דורש.\u0004 כיצד? נאמר במבול: \u0003\"חמש עשרה אמה מלמעלה גברו המים ויכסו ההרים\"\u0004 (בראשית ז, כ), \u0003וכי חמש עשרה אמה ב\u0004מקום \u0003עמק, חמש עשרה\u0004 אמה \u0003בשפלה, חמש עשרה\u0004 אמה \u0003בהרים? וכי מיא שורי שורי קיימי\u0004 \u0005[המים חומות חומות עמדו]\u0006 שהמים עמדו בדיוק לפי גובה המקום. \u0003ועוד:\u0004 ה\u0003תיבה היכי סגיא\u0004 \u0005[היאך הלכה]\u0006 וצפה על המים אם לא היו המים שוים? \u0003אלא, נבקעו כל מעינות תהום רבה עד דאשוו מיא בהדי טורי\u0004 \u0005[שהושוו המים לראשי ההרים]\u0006 \u0003והדר\u0004 \u0005[וחזר\u0006 שוב\u0005]\u0006 אחרי זאת לומר כי \u0003\"חמש עשרה אמה מלמעלה גברו המים\".\u0004","ומעתה נדון: \u0003וכי אי זה מדה מרובה, מדה טובה או מדת פורענות? הוי אומר: מדה טובה מרובה ממדת פורענות,\u0004 והנה \u0003במדת פורענות הוא אומר: \"וארבת השמים נפתחו\"\u0004 (בראשית ז, יא) ארובות בלבד, שהם חלונות. ואילו \u0003במדה טובה\u0004 במן \u0003הוא אומר: \"ויצו שחקים ממעל ודלתי שמים פתח וימטר עליהם מן לאכל ודגן שמים נתן למו\"\u0004 (תהלים עח, כג-כד) ומעתה נערוך חשבון:","\u0003כמה ארובות יש בדלת\u0004 — לפחות \u0003ארבע\u0004 לפי הגודל, ארבע \u0003ארבע\u0004 לשתי דלתות (\"דלתי שמים\") \u0003הרי כאן שמונה,\u0004 ואם המבול ירד לפי הביטוי מ\"ארובות השמים\" (ומיעוט רבים שנים) הרי שירד המן פי ארבע מן המבול, \u0003ונמצא מן שירד להם לישראל גבוה ששים אמה,\u0004 פי ארבע מחמש עשרה אמות של המבול.","בדומה לזה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003איסי בן יהודה אומר: מן שירד להם לישראל היה מתגבר ועולה עד שרואין אותו כל מלכי מזרח ומערב, שנאמר: \"תערך לפני שלחן נגד צררי\u0004 דשנת בשמן ראשי כוסי רויה\u0003\"\u0004 (תהלים כג, ה), שערך ה' לישראל שיראו כל צורריהם בגדולתם על העולם. \u0003\"כוסי רויה\"\u0004 שבפסוק זה, \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003כסא\u0004 \u0005[כוסו]\u0006 של \u0003דוד לעלמא דאתי\u0004 \u0005[לעולם הבא],\u0006 \u0003מאתן ועשרין וחד לוגא\u0004 \u0005[מאתים ועשרים ואחד לוג]\u0006 \u0003מחזיק\u0004 (מכיל), \u0003שנאמר: \"כוסי רויה\", \"רויה\" בגימטריא הכי הוי\u0004 \u0005[כך הוא\u0006 המספר\u0005].\u0006","על מדרשו של ר' אלעזר המודעי שואלים: \u0003הא לא דמיא\u0004 \u0005[הרי אינו דומה]\u0006 ואין החישוב מדוייק. שהרי \u0003התם בארבעין יומין\u0004 \u0005[שם\u0006 גברו המים חמש עשרה אמה \u0005במשך ארבעים ימים]\u0006 של מבול, ואילו \u0003הכא חדא שעתא\u0004 \u0005[\u0006ואילו \u0005כאן שעה אחת\u0006 בכל יום\u0005].\u0006 ומצד שני — \u0003התם לכולי עלמא\u0004 \u0005[שם\u0006 היה המבול \u0005לכל העולם]\u0006 ואילו \u0003הכא לישראל לחודיה\u0004 \u0005[לבדם],\u0006 \u0003ונפיש להו טפי\u0004 \u0005[והיה מרובה להם הרבה יותר]\u0006 מגובה זה לפי החשבון. ומשיבים: \u0003ר' אלעזר המודעי \"פתיחה\" \"פתיחה\" גמר\u0004 \u0005[למד]\u0006 בגזירה שווה, שנאמרה לשון פתיחת שמים בשני המקרים, ללמד שאותה פתיחה היתה גם פה וגם שם.","במשנה למדנו כי בין חמשת הדברים האסורים ביום הכיפורים, הוא ש\u0003אסור באכילה. ושואלים: הני חמשה ענויין כנגד מי?\u0004 כלומר, מהו המקור והרמז להם? \u0003אמר רב חסדא: כנגד חמשה ענויין שבתורה,\u0004 שחמש פעמים מוזכרת בתורה חובת העינוי ביום הכפורים. שנאמר: \u0003\"ובעשור\u0004 לחודש השביעי הזה מקרא קודש יהיה לכם ועניתם את נפשותיכם\" (במדבר כט, ז). ונאמר: \u0003\"אך בעשור\u0004 לחודש השביעי הזה יום הכיפורים הוא מקרא קודש יהיה לכם ועניתם את נפשותיכם\" (ויקרא כג, כז). ונאמר עוד: \u0003\"שבת שבתון\u0004 הוא לכם ועניתם את נפשותיכם\" (ויקרא כג, לב). וכן: \u0003\"שבת שבתון\u0004 היא לכם ועניתם את נפשותיכם\" (ויקרא טז, לא). ועוד נאמר: \u0003\"והיתה לכם\u0004 לחוקת עולם בחודש השביעי בעשור לחודש תענו את נפשותיכם\" (ויקרא טז, כט).","ומקשים: וכי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003חמשה הוו\u0004 \u0005[הם]\u0006 העינויים? \u0003ואנן שיתא תנן\u0004 \u0005[ואנחנו\u0006 הרי \u0005ששה\u0006 עינויים \u0005למדנו]:\u0006 אכילה, שתיה, רחיצה, סיכה, תשמיש המיטה, ונעילת הסנדל! ומשיבים: \u0003שתיה בכלל אכילה היא,\u0004 ושתיהן נחשבות כעינוי אחד. ש\u0003אמר ריש לקיש: מנין לשתיה שהיא בכלל אכילה — שנאמר: \"ואכלת לפני ה' אלהיך\u0004 במקום אשר יבחר לשכן שמו שם \u0003מעשר דגנך תירשך ויצהרך\"\u0004 (דברים יד, כג), והלוא \u0003תירוש חמרא\u0004 \u0005[יין]\u0006 \u0003הוא וקרי ליה\u0004 \u0005[וקורא לו]\u0006 הכתוב בלשון \u0003\"ואכלת\",\u0004 משמע שלשון אכילה מתייחסת גם לשתיה.","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה דבר זה? \u0003ודילמא דאכליה\u0004 \u0005[ושמא שאוכל]\u0006 את היין ממש, \u0003על ידי אניגרון\u0004 (סוג מאכל שמעורב בו יין)! ש\u0003אמר רבה בר שמואל: אניגרון —\u0004 הוא \u0003מיא דסילקא\u0004 \u0005[מי סלק]\u0006 ויין מעורבים כאחד, ו\u0003אכסיגרון —\u0004 הוא \u0003מיא דכולהו שלקי\u0004 \u0005[מים שבאים מכל מיני דברים שלוקים],\u0006 שמערבים בהם יין ואוכלים. ואם כן אין הוכחה מכאן ששתיה בכלל אכילה.","\u0003אלא אמר רב אחא בר יעקב: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה: נאמר: \u0003\"ונתתה הכסף בכל אשר תאוה נפשך בבקר ובצאן וביין ובשכר\u0004 ובכל אשר תשאלך נפשך \u0003ואכלת\"\u0004 (דברים יד, כו), והלא \u0003שכר שתיה הוא, וקרייה רחמנא\u0004 \u0005[וקראה לו התורה]\u0006 \u0003\"ואכלת\".\u0004","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוכיח אתה? \u0003ודילמא הכא נמי\u0004 \u0005[ושמא גם כן כאן]\u0006 הכוונה היא \u0003דאכליה\u0004 \u0005[שאכל אותו]\u0006 \u0003על ידי אניגרון\u0004 (בתערובת)! ודוחים: שם אי אפשר לומר כן, כי \u0003\"שכר\" כתב\u0004 \u0005[נאמר]\u0006 וכונתו \u0003מידי\u0004 \u0005[דבר]\u0006 ש\u0003משכר,\u0004 ויין בתערובת איננו משכר. ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 אין פירוש \"שכר\" יין, אלא אוכל שגורם לשכרות, כגון \u0003דבילה קעילית\u0004 — שהיא תאנה יבשה מתוקה ביותר הבאה מקעילה וגורמת לשכרות? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אכל\u0004 הכהן \u0003דבילה קעילית ושתה דבש וחלב\u0004 והשתכר על ידיהם \u0003ונכנס למקדש\u0004 לעבוד —"],["\u0003חייב\u0004 משום \"ושכר אל תשת\" (ויקרא י, ט). ואם כן אפשר לפרש שכר שבכתוב זה בדבילה.","\u0003אלא\u0004 יש לדחות ולומר כך: \u0003יליף\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 בגזירה שוה \u0003\"שכר\" \"שכר\" מנזיר, מה להלן\u0004 בנזיר \"שכר\" פירושו — \u0003יין\u0004 ממש, \u0003אף כאן — יין\u0004 ממש ולא דבילה.","בתוך הדיון נתפרש שהתירוש הוא יין, ושואלים: וכי \u0003תירוש חמרא\u0004 \u0005[יין]\u0006 \u0003הוא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנודר\u0004 ואוסר עצמו \u0003מן התירוש — אסור בכל מיני מתיקה,\u0004 כגון: פירות מתוקים \u0003ומותר ביין,\u0004 הרי שתירוש אינו יין! ודוחים: אי אפשר לומר כך, \u0003ולאו חמרא הוא\u0004 \u0005[וכי אין\u0006 התירוש \u0005יין]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ותירוש ינובב בתלות\"\u0004 (זכריה ט, יז), לומר: שהתירוש מפתה את לבו ופיו (ינובב — מלשון ניב) של השותה, אפילו בתולות שהן צנועות ומסוגרות, משמע שתירוש יין הוא! ומשיבים: אין זו ראיה, אפשר לפרש: \u0003דבר הבא מן התירוש,\u0004 כלומר: היין — \u0003ינובב בתולות,\u0004 שתירוש עצמו הוא ענבים מתוקים, והיין נקרא בהשאלה תירוש משום שהוא נעשה מתירוש.","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ותירוש יקביך יפרצו\"\u0004 (משלי ג, י), משמע שמן היקבים מוציאים תירוש! ומשיבים: אף כאן אין הוכחה, שאפשר לומר \u0003דבר הבא מן התירוש — יקביך יפרוצו.\u0004","ומקשים עוד: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"זנות ויין ותירוש יקח לב\"\u0004 (הושע ד, יא), הרי ברור מכאן שתירוש יין הוא, שמפתה את הלב! \u0003אלא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003תירוש\u0004 הכתוב במקרא \u0003חמרא\u0004 \u0005[יין]\u0006 \u0003הוא, ובנדרים הלך אחר לשון בני אדם,\u0004 ובלשון בני אדם בתקופת המשנה פירוש תירוש הוא מיני מתיקה, ובכללם ענבים, ולא יין. ולענין נדר צריך לדון לפי כוונתו של הנודר, אבל כשהוזכר תירוש במקראות, הכוונה ליין.","ושואלים: אם כן \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 במקרא גם \u0003יין, ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 גם \u0003תירוש?\u0004 ומסבירים: \u0003יין\u0004 רומז — \u0003שמביא יללה לעולם,\u0004 שהשכרות גורמת לרוב חטאים. \u0003תירוש\u0004 — לומר \u0003שכל המתגרה בו\u0004 ועוסק בו \u0003נעשה רש\u0004 (עני).","\u0003רב כהנא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 לכאורה; \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"תירש\" וקרינן\u0004 \u0005[וקוראים אנו]\u0006 לפי הכתיב המלא \u0003\"תירוש\",\u0004 ויש להבינו כך: \u0003זכה\u0004 ושתה כראוי — \u0003נעשה ראש, לא זכה — נעשה רש\u0004 כפי הכתיב. ומעירים: \u0003והיינו\u0004 \u0005[וזו]\u0006 כעין דבריו של \u0003רבא.\u0004 ש\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה כעין סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ישמח\"\u0004 ב\"ש\" \u0003וקרינן\u0004 \u0005[וקוראים אנו]\u0006 \u0003ישמח\u0004 ב\"ש\". לומר: \u0003זכה — משמחו\u0004 היין, \u0003לא זכה —\u0004 היין \u0003משממו\u0004 (משגע אותו). \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבא: חמרא וריחני\u0004 \u0005[יין וריח טוב] —\u0006 \u0003פקחין\u0004 \u0005[עשו אותי פיקח],\u0006 הרי שהיין מביא תועלת לאיש שזכה לכך.","ושואלים: מניעת \u0003רחיצה וסיכה, מנא לן דאיקרי\u0004 \u0005[מנין לנו שנקרא]\u0006 \u0003עינוי.\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדניאל: \u0003\"לחם חמדות לא אכלתי ובשר ויין לא בא אל פי וסוך לא סכתי\"\u0004 (דניאל י, ג). ותחילה מבארים את לשון הכתוב: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לחם חמדות לא אכלתי\"? אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת: אפילו נהמא דחיטי דכייתא\u0004 \u0005[לחם של חטים נקיות,\u0006 מבוררות\u0005],\u0006 \u0003לא אכל,\u0004 אלא לחם מחיטים מעורבות בסובין.","ומשיבים: \u0003ומנא לן דחשיב\u0004 \u0005[ומניין לנו שנחשב]\u0006 לדניאל כל זה וגם העדר הסיכה \u0003כעינוי — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר אלי אל תירא דניאל כי מן היום הראשון אשר נתת את לבך להבין ולהתענות לפני אלהיך נשמעו דבריך ואני באתי בדבריך\"\u0004 (דניאל י, יב). \u0003\"כי חמודות אתה\"\u0004 (דניאל ט, כג)","\u0003אשכחן\u0004 \u0005[\u0006למדנו, \u0005מצאנו]\u0006 איפוא ראיה כי \u0003סיכה\u0004 קרויה עינוי, \u0003רחיצה מנא לן\u0004 \u0005[מניין לנו]\u0006 שיש עינוי במניעתה? \u0003אמר רב זוטרא בר' טוביה: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ותבא כמים בקרבו וכשמן בעצמותיו\"\u0004 (תהלים קט, יח), לומר: שמים ושמן שאדם סך ורוחץ בהם הרי הם כנכנסים לקרבו. ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\"מים בקרבו\" משמעו \u0003כשתיה\u0004 ולא כסיכה! ודוחים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שמן, מה שמן\u0004 הכוונה היא שסך אותו \u0003מאבראי\u0004 \u0005[מבחוץ],\u0006 שהרי אין שותים שמן, \u0003אף מים מאבראי\u0004 \u0005[מבחוץ].\u0006","ומקשים: \u0003והא תנא איפכא קא נסיב לה\u0004 \u0005[והרי התנא להיפך הוא לוקח,\u0006 מקבל ומבין את הדבר\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מנין לסיכה שהיא כשתיה ביום הכפורים? אף על פי שאין ראיה לדבר\u0004 במפורש מן הכתובים, מכל מקום \u0003זכר\u0004 ורמז יש \u0003לדבר\u0004 מן הכתוב, \u0003שנאמר: \"ותבא כמים בקרבו וכשמן בעצמותיו\"\u0004 (תהלים קט, יח), ששמן על גופו הריהו כמים בקרבו, משמע שהוא מבין \"כמים בקרבו\" במובן של שתיה! \u0003אלא אמר רב אשי: רחיצה מגופיה דקרא שמיע ליה\u0004 \u0005[מגופו של\u0006 אותו \u0005מקרא לומדים הוא אותה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וסוך לא סכתי\"\u0004 (דניאל י, ג), לומר שכל סיכה לא עשה, ובכלל זה גם רחיצה, ושניהם נאסרו מאותו מקור.","כיון שהוזכר המקרא בדניאל, שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הדבר שאמר המלאך לדניאל: \u0003\"ואני באתי בדבריך\"\u0004 (דניאל י, יב), שנראה שקודם לא יכול המלאך לבוא לפנים מן הפרגוד, אם לא בגלל דניאל. ומשיבים: \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"ושבעים איש מזקני בית ישראל ויאזניהו בן שפן עמד בתוכם עמדים לפניהם ואיש מקטרתו בידו ועתר ענן הקטרת עלה\"\u0004 (יחזקאל ח, יא), שראה יחזקאל כיצד זקני ישראל עובדים עבודה זרה. \u0003\"וישלח תבנית יד ויקחני בציצת ראשי ותשא אתי רוח בין הארץ ובין השמים ותבא אתי ירושלימה במראות אלהים אל פתח שער הפנימית הפונה צפונה אשר\u0004"],["\u0003שם מושב סמל הקנאה המקנה\"\u0004 (יחזקאל ח, ג), \u0003\"ויבא אתי אל חצר בית ה' הפנימית והנה פתח היכל ה' בין האולם ובין המזבח כעשרים וחמשה איש אחריהם אל היכל ה' ופניהם קדמה והמה משתחוים קדמה לשמש\"\u0004 (יחזקאל ח, טז) ואומרים: \u0003ממשמע שנאמר \"ופניהם קדמה\" איני יודע שאחוריהם אל היכל ה'\u0004 שהוא במערב? \u0003אלא מה תלמוד לומר \"אחריהם אל היכל ה'\"\u0004 — הרי זה \u0003מלמד\u0004 ברמז \u0003שהיו פורעין\u0004 (מגלין) עצמם \u0003והיו מתריזין\u0004 (מוציאין רעי) \u0003כלפי מטה,\u0004 כלומר: כלפי שכינה (ושינה בלשונו כדי שלא לאמר לשון מגונה).","\u0003אמר לו הקדוש ברוך הוא למיכאל\u0004 שהוא שר ישראל (ראה דניאל י, כא): \u0003מיכאל! סרחה\u0004 (חטאה) \u0003אומתך. אמר לפניו: רבונו של עולם דיו לטובים שבהם,\u0004 שהרי יש בהם גם אנשים טובים ויתקיים העולם באלה! \u0003אמר לו: אני שורף אותם ולטובים שבהם\u0004 שאינם מוחים ברשעים (תו\"י) \u0003מיד: \"ויאמר אל האיש לבש הבדים ויאמר בא אל בינות לגלגל אל תחת לכרוב ומלא חפניך גחלי אש מבינות לכרבים וזרק על העיר ויבא לעיני\"\u0004 (יחזקאל י, ב). \u0003מיד: \"וישלח הכרוב את ידו מבינות לכרובים אל האש אשר בינות הכרבים וישא ויתן אל חפני לבש הבדים ויקח ויצא\"\u0004 (יחזקאל י, ז).","\u0003אמר רב חנא בר ביזנא אמר ר' שמעון חסידא: אילמלא לא נצטננו גחלים מידו של כרוב לידו של גבריאל\u0004 והיה גבריאל נוטל את הגחלים בעצמו \u0003לא נשתיירו משונאיהן של ישראל שריד ופליט\u0004 ועל ידי צינון זה קטנה הפורענות.","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והנה האיש לבוש הבדים אשר הקסת במתניו משיב דבר לאמר עשיתי כאשר צויתני\"\u0004 (יחזקאל ט, יא). \u0003אמר ר' יוחנן: באותה שעה הוציאו לגבריאל מאחורי הפרגוד\u0004 (המסך) שמעבר לו נמצאים המלאכים הפנימיים, \u0003ומחיוהו שיתין פולסי דנורא\u0004 \u0005[והכוהו בשישים שבטים של אש]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא עבדת\u0004 \u0005[עשית] —\u0006 \u0003לא עבדת\u0004 \u0005[עשית]\u0006 \u0003אי עבדת אמאי לא עבדת כדפקדוך\u0004 \u0005[ואם עשית מדוע לא עשית כמו שציווך],\u0006 אלא שינית? \u0003ועוד: דעבדת, לית לך\u0004 \u0005[ואחרי\u0006 שכבר \u0005עשית וכי אין לך],\u0006 אינך יודע את הכלל: \u0003אין משיבין על הקלקלה,\u0004 כלומר: אין מוסרין דין וחשבון שנתבצעה שליחות של פורענות וקלקלה, אלא אומרים אותו ברמז בלבד.","ואז \u0003אייתוה\u0004 \u0005[הביאו]\u0006 את \u0003דוביאל שרא דפרסאי\u0004 \u0005[שר הפרסיים]\u0006 \u0003ואוקמיה בחריקיה\u0004 \u0005[והעמידו אותו במקומו\u0006 של גבריאל\u0005]\u0006 \u0003ושמש עשרים ואחד יום. היינו דכתיב\u0004 \u0005[הוא שנאמר]:\u0006 \u0003\"ושר מלכות פרס עמד לנגדי עשרים ואחד יום והנה מיכאל אחד השרים הראשנים בא לעזרני ואני נותרתי שם אצל מלכי פרס\"\u0004 (דניאל י, יג) וכנגד אותו עשרים ואחד יום \u0003יהבו ליה\u0004 \u0005[נתנו לו]\u0006 לשר הפרסיים \u0003עשרין וחד מלכי\u0004 \u0005[עשרים ואחד מלכים]\u0006 שימלכו להם \u0003ופרוותא\u0004 \u0005[ונמלי הים]\u0006 של \u0003משהיג.\u0004","\u0003אמר\u0004 שר הפרסיים: \u0003כתיבו לי לישראל באכרגא\u0004 \u0005[כתבו עבורי כי יהודים\u0006 יהיו צריכים לשלם \u0005את המיסים].\u0006 ואכן \u0003כתבו ליה\u0004 \u0005[כתבו לו]\u0006 כבקשתו. אמר: \u0003כתיבו לי רבנן באכרגא\u0004 \u0005[תכתבו לי\u0006 כי \u0005גם החכמים\u0006 יהיו צריכים לשלם \u0005את המיסים]\u0006 ו\u0003כתבו ליה\u0004 \u0005[כתבו לו].\u0006 \u0003בעידנא דבעו למיחתם\u0004 \u0005[בזמן שרצו לחתום]\u0006 את הדבר, \u0003עמד גבריאל מאחורי הפרגוד ואמר\u0004 כלשון הכתוב: \u0003\"שוא לכם משכימי קום מאחרי שבת אכלי לחם העצבים כן יתן לידידו שנא\"\u0004 (תהלים קכז, ב), \u0003מאי\u0004 \u0005[מה\u0006 הפירוש\u0005]\u0006 \u0003\"כן יתן לידידו שנא\" אמר ר' יצחק: אלו נשותיהן של תלמידי חכמים שמנדדות שינה בעולם הזה\u0004 מעיניהן ומחכות לבעליהן שהם משכימי קום ומאחרי שבת לעסוק בתורה \u0003וזוכות לעולם הבא,\u0004 וזה יהיה שכרם שיגבו מהם עוד מיסים? \u0003ולא השגיחו עליו,\u0004 על גבריאל ומאמרו.","\u0003אמר לפניו: רבונו של עולם! אם יהיו כל חכמי אומות העולם בכף מאזנים ודניאל איש חמודות בכף שניה לא נמצא מכריע את כולם?! אמר הקדוש ברוך הוא: מי הוא זה שמלמד זכות על בני? אמרו לפניו: רבונו של עולם, גבריאל\u0004 הוא. \u0003אמר להם: יבא\u0004 ויכנס שוב לפנים מן המחיצה. וזהו \u0003שנאמר: \"ואני באתי בדבריך\"\u0004 (דניאל י, יב), כלומר: בגללך, בגלל שהזכרתיך זכיתי לבוא פנימה. \u0003אמר להו\u0004 \u0005[אמר להם]\u0006 הקדוש ברוך הוא: \u0003ליעול\u0004 \u0005[שיכנס].\u0006 \u0003אעיילוהו\u0004 \u0005[הכניסוהו].\u0006","\u0003אתא אשכחיה\u0004 \u0005[בא ומצא]\u0006 את \u0003דוביאל\u0004 שר הפרסיים \u0003דנקט ליה לאיגרתיה בידיה\u0004 \u0005[שהוא מחזיק את כתבו בידו],\u0006 \u0003בעא למרמא מיניה\u0004 \u0005[רצה לתלוש ממנו]\u0006 את הכתב, \u0003בלעה\u0004 \u0005[בלע אותו]\u0006 דוביאל. \u0003איכא דאמרי מיכתב הוה כתיבא מיחתם לא הוי חתמא\u0004 \u0005[יש אומרים שהכתב כתוב היה ולא היה חתום],\u0006 \u0003איכא דאמרי אף מיחתם נמי הוה חתמא\u0004 \u0005[יש אומרים גם כן חתום היה],\u0006 אולם \u0003כדבלעיה מחיק לה מיניה\u0004 \u0005[כשנבלע נמחק ממנו].\u0006 ומעירים: \u0003היינו דבמלכותא דפרס\u0004 \u0005[וזהו שבמלכות פרס],\u0006 \u0003איכא דיהיב כרגא ואיכא דלא יהיב כרגא\u0004 \u0005[יש מי שנותן,\u0006 משלם \u0005מיסים ויש מי שאינו נותן,\u0006 משלם \u0005מיסים],\u0006 שהגזירה לא נגמרה בשלימות. ועוד נאמר שם: \u0003\"ואני יוצא והנה שר יון בא\"\u0004 (דניאל י, כ) \u0003עוי עוי\u0004 \u0005[צווח וצווח]\u0006 גבריאל שלא ישלטו מלכי יוון על ישראל \u0003וליכא דאשגח ביה\u0004 \u0005[ולא היה מי שישגיח בו].\u0006","ומכאן חוזרים אנו שוב לפירוש ענין ראשון, שמניעת רחיצה קרויה עינוי. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003רחיצה דאיקרי ענוי מנא לן\u0004 \u0005[שקרויה עינוי מנין לנו]\u0006 — מכאן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולאביתר הכהן אמר המלך ענתת לך על שדיך כי איש מות אתה וביום הזה לא אמיתך כי נשאת את ארון ה' אלהים לפני דוד אבי וכי התענית בכל אשר התענה אבי\"\u0004 (מלכים א' ב, כו). \u0003וכתיב ביה\u0004 \u0005[ונאמר בו]\u0006 \u0003בדוד: \"כי אמרו העם רעב ועיף וצמא במדבר\"\u0004 (שמואל ב' יז, כט). והנה \u0003רעב\u0004 פירושו מחוסר אכילת \u0003לחם, וצמא — ממים, עיף ממאי\u0004 \u0005[ממה]\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003מרחיצה?\u0004 שהרי מהשוואת הכתובים נראה שהוא עינוי! ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 הכוונה היא עייף — \u0003מנעילת הסנדל?\u0004","\u0003אלא\u0004 יש למצוא מקור אחר. \u0003אמר ר' יצחק: מהכא\u0004 \u0005[מכאן]\u0006 נלמד \u0003\"מים קרים על נפש עיפה\"\u0004 (משלי כה, כה) משמע שעייף פירושו זה שלא רחץ. ושואלים: \u0003ודילמא\u0004 \u0005[ושמא\u0006 הכוונה היא לעינוי\u0005]\u0006 \u0003משתיה?\u0004 ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]:\u0006 \u0003\"מים קרים בנפש עיפה\"\u0004, שמשמעותו שבא לתוכו, כשתיה? הרי \u0003\"על נפש עיפה כתיב\"\u0004 \u0005[נאמר],\u0006 משמע שהוא לשון רחיצה.","ומבררים עוד: \u0003ונעילת הסנדל מנא לן\u0004 \u0005[מניין לנו]\u0006 שמניעתה קרויה עינוי? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ודוד עלה במעלה הזיתים עלה ובוכה וראש לו חפוי והוא הלך יחף\"\u0004 (שמואל ב' טו, ל), \u0003יחף ממאי\u0004 \u0005[ממה],\u0006 כלומר: מה הפירוש \"יחף\", \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003מנעילת הסנדל?\u0004 והרי אמרנו שכל אלה נקראו עינוי. ודוחים: לא, \u0003ודילמא\u0004 \u0005[ושמא]\u0006 הכוונה לכך שהוא יחף \u0003מסוסיא ומרטקא\u0004 \u0005[מסוס ושוט],\u0006 שאף שאכן הוא נעול מנעלים, אולם מאחר ואין לו סוס ושוט, לגבי מלך נחשב הדבר כאילו הוא הולך יחף.","\u0003אלא אמר רב נחמן בר יצחק: מהכא\u0004 \u0005[מכאן]\u0006 נלמד הדבר, שנאמר: \u0003\"לך ופתחת השק מעל מתניך ונעלך תחלץ מעל רגלך\"\u0004 (ישעיה כ, ב) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויעש כן הלך ערום ויחף\"\u0004 (ישעיה כ, ב). \u0003יחף ממאי\u0004 \u0005[ממה]\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003מנעילת הסנדל?\u0004 ומשיבים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\"יחף\" פירושו שהלך \u0003במנעלים המטולאים\u0004 בטלאים? \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שאין להבין את הדברים כמשמען ממש, אם כן \"ערום\" שנאמר שם, וכי כונתו \u0003ערום ממש? אלא\u0004 ודאי הכוונה שהלך \u0003בבגדים בלויים, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה שהלך \u0003במנעלים המטולאים.\u0004","\u0003אלא\u0004 חייבים למצוא מקור אחר. \u0003אמר רב נחמן בר יצחק: מהכא\u0004 \u0005[מכאן],\u0006 נאמר: \u0003\"מנעי רגלך מיחף וגרונך מצמאה\"\u0004 (ירמיה ב, כה) ופירשוהו: \u0003מנעי עצמך מן החטא כדי שלא יבא רגלך לידי יחוף, מנעי לשונך מדברים בטלים — כדי שלא יבא גרונך לידי צמאה,\u0004 ואם כן למדנו שההולך יחף קרוי מתענה.","ועוד לבירור הלכה. מניעת \u0003תשמיש המטה דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003ענוי מנא לן\u0004 \u0005[מניין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם תענה את בנתי ואם תקח נשים\u0004 על בנותי\u0003\"\u0004 (בראשית לא, נ)."],["\u0003\"אם תענה\" — מתשמיש,\u0004 כלומר: שתמנע מהן עונתן, \u0003\"ואם תקח\" — מצרות,\u0004 שלא ישא עליהן נשים אחרות. ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003מצרות,\u0004 שהזהירו שלא יקח עליהן נשים אחרות? ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"אם תקח\"?\u0004 הלא \u0003\"ואם תקח\" כתיב\u0004 \u0005[נאמר],\u0006 משמע ששני דברים נפרדים הם.","ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003מצרות, חד\u0004 \u0005[אחד]\u0006 הכוונה \u0003לצרות דידיה\u0004 \u0005[משלו],\u0006 כלומר: שלא יעלה את שתי השפחות בלהה וזלפה למדריגת גבירות, שתהיינה צרות לבנותיו, ועל זה אמר \"אם תענה\", \u0003וחד\u0004 \u0005[ואחד]\u0006 אמר לגבי \u0003צרות דאתיין ליה מעלמא\u0004 \u0005[\u0006שיכולות \u0005לבוא מן העולם],\u0006 שלא ישא נשים אחרות נוספות, \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"אם תקח\"!\u0004 ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"אם תקח ואם תענה\"?\u0004 שכן מן הדרך להזהיר בתחילה מפני הדבר הקשה יותר ורק אחריו על הדבר הקל, ולפי סדר הכתוב הזהירו קודם מפני הדבר הקל שהוא מן הצרות שלו ורק אחר כך מפני לקיחת צרות מן העולם, שכן \u0003\"אם תענה ואם תקח\" כתיב\u0004 \u0005[נאמר].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: הא\u0004 \u0005[הרי]\u0006 \u0003תשמיש גופה איקרי\u0004 \u0005[נקרא]\u0006 \u0003ענוי, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישכב אתה ויענה\"\u0004 (בראשית לד, ב), ואם כן כיצד יכול אתה לומר שהעינוי הוא דווקא במניעתו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003שעינה מביאות אחרות\u0004 כלומר: שבא עליה שלא כדרכה, וביאה כזו ודאי קרויה עינוי.","ומעתה באים לבאר מקצת מן הדברים האסורים ביום הכיפורים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אסור לרחוץ מקצת גופו\u0004 כשם שאסור לרחוץ את \u0003כל גופו, ואם היה מלוכלך בטיט\u0004 או \u0003בצואה — רוחץ כדרכו ואינו חושש,\u0004 לפי שאינו מתכוון להנאה. וכן \u0003אסור לסוך מקצת גופו ככל גופו, ואם היה חולה\u0004 וצריך לסוך לרפואה, \u0003או שהיו לו חטטין בראשו\u0004 ומכאיבים לו אם לא יסוך — \u0003סך כדרכו ואינו חושש.\u0004","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה: רבן שמעון בן גמליאל אומר: מדיחה\u0004 (רוחצת) \u0003אשה ידה אחת במים,\u0004 כדי שלא יגעו ידיה במזון לפני נטילת ידים שחרית, \u0003ונותנת פת לתינוק, ואינה חוששת\u0004 משום איסור רחיצה ביום הכיפורים.","\u0003אמרו עליו על שמאי הזקן שלא רצה להאכיל בידו אחת\u0004 שלא יצטרך לרחוץ אותה, ובשל כך מנע את התינוקות ממזון בכל יום הכיפורים, ומפני בריאות וצער התינוקות \u0003גזרו עליו להאכיל בשתי ידים,\u0004 ונאלץ בשל כך ליטול את שתי ידיו. ושאלו: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אמרו שיש לרחוץ את הידים? \u0003אמר אביי: משום שיבתא\u0004 \u0005[רוח רעה]\u0006 השורה על ידים שלא נרחצו שחרית.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ההלך להקביל\u0004 (לפגוש) \u0003פני אביו או פני רבו, או פני מי שגדול ממנו\u0004 בחכמה, וצריך לעבור נהר בדרכו — \u0003עובר עד צוארו במים ואינו חושש\u0004 משום איסור רחיצה ביום הכיפורים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003הרב אצל תלמיד מאי\u0004 \u0005[מה\u0006 דינו\u0005],\u0006 המותר לו לעבור במים כדי ללמד את תלמידו? ומנסים להביא ראיה, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ש\u0003אמר רב יצחק בר בר חנה: אנא חזיתיה\u0004 \u0005[אני ראיתי]\u0006 את \u0003זעירי דאזל לגבי\u0004 \u0005[שהלך\u0006 ועבר נהר בדרכו \u0005אל]\u0006 \u0003רב חייא בר אשי תלמידיה\u0004 \u0005[תלמידו].\u0006 \u0003רב אשי אמר:\u0004 לא כך היה המעשה, אלא המעשה \u0003ההוא\u0004 היה דווקא שהתלמיד \u0003רב חייא בר אשי הוא דאזל לגביה\u0004 \u0005[שהלך אל]\u0006 \u0003זעירי רביה\u0004 \u0005[רבו],\u0006 ואם כן אין לפתור מכאן את שאלתנו.","מסופר, כי \u0003רבא שרא לבני עבר ימינא למעבר במיא לנטורי פירי\u0004 \u0005[התיר לבני עבר הימין\u0006 של הפרת \u0005לעבור במים כדי לשמור את הפירות]\u0006 שבשדותיהם ביום הכיפורים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: תניא דמסייע\u0004 \u0005[יש ברייתא המסייעת]\u0006 \u0003לך.\u0004 ששנו בה: \u0003שומרי פירות — עוברין עד צוארן במים ואין חוששין\u0004 משום איסור יום הכיפורים.","מסופר עוד: \u0003רב יוסף שרא להו\u0004 \u0005[התיר להם]\u0006 \u0003לבני\u0004 הכפר \u0003בי תרבו למיעבר במיא למיתי לפירקא\u0004 \u0005[לעבור במים כדי לבוא ל\u0006מקום \u0005הדרשה]\u0006 הנאמרת ביום הכיפורים, אולם \u0003למיזל\u0004 \u0005[ללכת]\u0006 חזרה במים \u0003לא שרא להו\u0004 \u0005[התיר להם],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אם כן אתה מכשילן לעתיד לבא,\u0004 ששוב לא יבואו לשמוע את הדרשה, אם יודעים הם שאסורים לחזור למקומם. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שהמעשה היה בנוסח אחר: רב יוסף \u0003שרא להו למיתי ושרא להו למיזל\u0004 \u0005[התיר להם לבוא והתיר להם לחזור\u0006 בתוך המים\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: בשלמא\u0004 \u0005[נניח]\u0006 שאתה מתיר להם \u0003למיתי\u0004 \u0005[לבוא] —\u0006 \u0003לחיי\u0004 \u0005[יפה],\u0006 \u0003אלא למיזל מאי טעמא\u0004 \u0005[לחזור מה טעם]\u0006 התרת להם? אמר לו: \u0003כדי שלא תהא מכשילן לעתיד לבא.\u0004","מסופר: \u0003רב יהודה ורב שמואל בר יהודה הוו קיימי אגודא\u0004 \u0005[היו עומדים על שפת]\u0006 \u0003נהר פפא אמברא\u0004 \u0005[ליד המעבורת]\u0006 במקום של \u0003חצדד והוה קאי\u0004 \u0005[והיה עומד]\u0006 \u0003רמי בר פפא מהך גיסא\u0004 \u0005[מצדו האחר\u0006 של הנהר\u0005]\u0006 \u0003רמא להו קלא\u0004 \u0005[הרים להם קולו]\u0006 ושאל: \u0003מהו,\u0004 האם מותר, \u0003למיעבר למיתי לגבייכו למשאל שמעתא\u0004 \u0005[לעבור ולבוא אליכם לשאול הלכה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה: רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 \u0003עובר\u0004 במים, \u0003ובלבד שלא יוציא ידו מתחת חפת\u0004 (שולי) \u0003חלוקו,\u0004 כלומר: שלא ירים את שולי חלוקו על כתיפו כדי שלא ירטבו, שזאת אחת מצורות הטלטול שמתחייב עליהם חטאת, אלא ימשיך וילך כדרכו וירטבו בגדיו במים. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 לא כך היה, אלא \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמואל בר רב יהודה: תנינא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עובר, ובלבד שלא יוציא ידו מתחת חפת חלוקו.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף:\u0004 וביום \u0003חול כי האי גונא מי שרי\u0004 \u0005[בכעין זה האם מותר]\u0006 ללכת במים עמוקים כל כך? והרי יש בכך סכנת טביעה! \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בענין הנחל העתיד לצאת מבית קודש הקדשים: \u0003\"וימד אלף באמה ויעברני במים מי אפסים\"\u0004 (יחזקאל מז, ג), ולמדו מכאן בדרך אגב — \u0003מכאן שמותר לעבור עד אפסיים\u0004 (קרסוליים).","\u0003\"וימד אלף ויעברני במים מים ברכים\"\u0004 (יחזקאל מז, ד) — \u0003מכאן שמותר לעבור\u0004 במים שמגיעים \u0003עד\u0004 ל\u0003ברכים. \"וימד אלף ויעברני מי מתנים\"\u0004 (יחזקאל מז, ד) — \u0003מכאן שמותר לעבור עד מתנים. מכאן ואילך — \"וימד אלף נחל אשר לא אוכל לעבר\"\u0004 (יחזקאל מז, ה), הרי שבמים המגיעים למעלה מן המתנים אין לעבור אף בימות החול, מפני הסכנה!","\u0003אמר אביי:\u0004 משם אין ראיה, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003נחל דרדיפי מיא\u0004 \u0005[שהמים בו זורמים]\u0006 במהירות, ומשום כך יש לחשוש שבמים עמוקים ממתניו יפילוהו המים, אבל במים שקטים מותר לעבור אפילו היו עמוקים יותר.","כיון שהבאנו את הדברים שנאמרו בנחל העתיד לצאת לעתיד לבוא, מסבירים את המשך הכתובים שם ביחזקאל. \u0003יכול יעבירנו בסיחוי\u0004 (בשחייה) — \u0003תלמוד לומר: \"כי גאו המים מי שחו\"\u0004 (יחזקאל מז, ה) \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מי שחו\" — שיוטא\u0004 (שייט, שחיה), \u0003שכן קורין לשייטא\u0004 \u0005[לשייט]\u0006 \u0003סייחא\u0004 \u0005[שחייה].\u0006 \u0003יכול יעבירנו בבורני\u0004 (ספינה) \u0003קטנה — תלמוד לומר: \"בל תלך בו אני שיט\"\u0004 (ישעיה לג, כא). \u0003יכול יעבירנו בבורני גדולה — תלמוד לומר: \"וצי אדיר לא יעברנו\"\u0004 (ישעיה לג, כא). ושואלים: \u0003מאי משמע\u0004 \u0005[מה משמע]\u0006 כיצד לומד אתה מלשון \"צי אדיר\"? ומסבירים: כמו שהיה \u0003מתרגם רב יוסף\u0004 פסוק זה: \u0003לא תזיל ביה\u0004 \u0005[תלך בו]\u0006 \u0003בספינת ציידין ובורני רבתי\u0004 \u0005[ואניה גדולה]\u0006 \u0003לא תגוזינה\u0004 \u0005[תעבור בו].\u0006","\u0003אמר ר' יהודה בן פזי: אף מלאך המות אין לו רשות לעבור בתוכו\u0004 מעבר לתחום נהר זה, וראיה לדבר \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"בל תלך בו אני שיט\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \"ויען השטן את ה' ויאמר \u0003משוט בארץ\u0004 ומהתהלך בה\" (איוב א, ז), שאף זה השטן בארץ לא יעבור נהר זה.","ועוד במדרשי חכמים בענין נחל זה היוצא מקודש הקדשים: \u0003אמר ר' פנחס משום רב הונא צפוראה\u0004 \u0005[מציפורי]:\u0006 \u0003מעין היוצא מבית קדשי הקדשים בתחילה\u0004 כשיוצא צר הוא מאוד \u0003ודומה לקרני חגבים, כיון שהגיע לפתח היכל — נעשה\u0004 עבה \u0003כחוט של שתי, כיון שהגיע לאולם נעשה כחוט של ערב\u0004 שהוא עבה יותר משל שתי, \u0003כיון שהגיע אל פתח עזרה — נעשה כפי פך קטן, והיינו דתנן\u0004 \u0005[וזהו ששנינו\u0006 במשנה \u0005:]\u0006 \u0003ר' אליעזר בן יעקב אומר: מים\u0004"],["\u0003מפכין\u0004 (כמו מפי הפך) \u0003עתידין להיות יוצאין מתחת מפתן הבית. מכאן ואילך היה\u0004 המעין \u0003מתגבר ועולה עד שמגיע לפתח בית דוד, כיון שמגיע לפתח בית דוד נעשה כנחל שוטף שבו רוחצין\u0004 לטהרתם \u0003זבין וזבות נדות ויולדות, שנאמר: \"ביום ההוא יהיה מקור נפתח לבית דויד ולישבי ירושלם לחטאת ולנדה\"\u0004 (זכריה יג, א).","\u0003אמר רב יוסף: מכאן רמז לנדה שצריכה לישב עד צוארה במים\u0004 שזהו העומק הראוי למי מקוה המטהרים. ומעירים: \u0003ולית הילכתא כוותיה\u0004 \u0005[ואין הלכה כמוהו]\u0006 אלא יכולה לטבול במים שבכל עומק שהוא, וכל שהמים מכסים את כולה הרי זה מקוה טהרה ראוי.","לדין המעבר במים לצורך מצוה שואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 ב\u0003יום הכפורים דליכא\u0004 \u0005[שאין\u0006 בו\u0005]\u0006 נעילת \u0003מנעל\u0004 ולכשיעברו בנחל בלא נעליהם — אין בעיה בדבר, אבל ב\u0003שבת דאיכא\u0004 \u0005[שיש]\u0006 בו נעילת \u0003מנעל, מאי\u0004 \u0005[מה]\u0006 יהיה הדין, המותר לעבור נחל בנעלים? שהרי יש לחשוש שמא ישמט המנעל מרגליו ויטלנו בידו ויכול בכך לעבור על איסור הוצאה בשבת! \u0003אמר נחמיה חתניה דבי נשיאה\u0004 \u0005[חתנו של בית הנשיא]:\u0006 \u0003אנא חזיתיה\u0004 \u0005[אני ראיתי]\u0006 את \u0003ר' אמי ור' אסי דמטו עורקומא דמיא\u0004 \u0005[שהגיעו לשלולית של מים]\u0006 והיו צריכים לעברה בשבת \u0003ועברוה\u0004 כשנעליהם על רגליהם \u0003דרך מלבוש\u0004 ולא חלצו אותם טרם המעבר.","ושואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 ב\u0003מנעל\u0004 שאפשר לקשור אותו יפה, אולם ב\u0003סנדל מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 כיון שאינו מהודק כל כך ברגל יש לחשוש שהמים ישטפו אותו. \u0003אמר רב ריחומי: אנא חזיתיה\u0004 \u0005[אני ראיתי]\u0006 את \u0003רבינא\u0004 ש\u0003עבר\u0004 נחל כשהיו על רגליו סנדלים \u0003דרך מלבוש. רב אשי אמר:\u0004 אם נעול הוא ב\u0003סנדל — לכתחלה לא\u0004 יעבור בו בתוך המים, שמא ישמט הסנדל מעל רגלו ויבוא להרימו ולשאתו בידו, ויעבור על איסור שבת.","אגב כך מסופר: \u0003ריש גלותא איקלע\u0004 \u0005[ראש הגולה הזדמן]\u0006 \u0003להגרוניא לבי\u0004 \u0005[לבית]\u0006 \u0003רב נתן, רפרם וכולהו רבנן\u0004 \u0005[וכל החכמים]\u0006 \u0003אתו לפירקא\u0004 \u0005[באו לדרשה],\u0006 \u0003רבינא לא אתא\u0004 \u0005[בא].\u0006 \u0003למחר\u0004 כשבא, \u0003בעי\u0004 \u0005[רצה]\u0006 \u0003רפרם לאפוקי\u0004 \u0005[להוציא]\u0006 את \u0003רבינא מדעתיה\u0004 \u0005[מדעתו,\u0006 מכעסו\u0005]\u0006 של \u0003ריש גלותא\u0004 \u0005[ראש הגולה],\u0006 שלא יקפיד על רבינא שנעדר מן הדרשה, ולכן שאל אותו: \u0003מאי טעמא לא אתא מר לפירקא\u0004 \u0005[מה טעם לא בא אדוני לדרשת הרגל]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הוה כאיב לי כרעאי\u0004 \u0005[כאבה לי רגלי].\u0006 אמר לו: \u0003איבעי לך למיסם מסאני\u0004 \u0005[היית צריך לנעול נעלים].\u0006 ענה לו: \u0003גבא דכרעא הוה\u0004 \u0005[גב הרגל היה זה]\u0006 ונעילת הנעל קשה לו.","אמר לו: \u0003איבעי לך למרמא סנדלא\u0004 \u0005[היית צריך לנעול סנדל],\u0006 שגב הרגל גלוי בו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עורקמא דמיא הוה באורחא\u0004 \u0005[שלולית\u0006 נחל \u0005מים היתה בדרך]\u0006 וצריך היה לעוברה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איבעי לך למעבריה\u0004 \u0005[היית צריך לעוברו]\u0006 כשאתה נעול סנדלים \u0003דרך מלבוש אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא סבר ליה מר להא\u0004 \u0005[וכי אין אדוני סבור\u0006 כהלכה \u0005זו]\u0006 ש\u0003אמר רב אשי: סנדל לכתחלה לא\u0004 ינעל בעוברו בשבת בנחל\u0005.\u0006 ומתוך הדברים למד ראש הגולה שלא נמנע רבינא לבוא מחמת זלזול בכבודו.","ועוד בדיני יום הכיפורים. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003יהודה בר גרוגרות: אסור לישב על גבי טינא\u0004 \u0005[אדמה לחה]\u0006 \u0003ביום הכפורים. אמר ר' יהושע בן לוי:\u0004 איסור זה הוא דווקא \u0003בטינא מטפחת,\u0004 כלומר שהלחות בה מורגשת במגע. \u0003אמר אביי:\u0004 אין בכך די אלא דווקא \u0003בטופח על מנת להטפיח,\u0004 כלומר שהרטיבות גדולה כל כך שכל מה שנוגע בדדבר שנגע בה אף הוא נרטב. \u0003אמר רב יהודה: מותר להצטנן בפירות\u0004 ביום הכיפורים ואין בכך משום חשש רחיצה. וכן \u0003רב יהודה\u0004 כשהיה סובל מן החום ביום הכיפורים, היה \u0003מצטנן\u0004 על ידי שהיה מניח על עצמו \u0003קרא\u0004 \u0005[דלעת].\u0006","\u0003רבה\u0004 היה \u0003מצטנן בינוקא\u0004 \u0005[בילד],\u0006 שהיה מבקש שיניחו סמוך לו ילד שגופו קריר, \u0003רבא\u0004 היה \u0003מצטנן בכסא דכספא\u0004 \u0005[בכוס של כסף].\u0006 \u0003אמר רב פפא: כסא דכספא\u0004 \u0005[כוס כסף]\u0006 להצטנן בו אם הוא \u0003מלא\u0004 מים \u0003— אסור,\u0004 אבל אם אינו מלא אלא \u0003חסר — שרי\u0004 \u0005[מותר].\u0006 אולם להצטנן בכוס \u0003דפחרא\u0004 \u0005[של חרס] —\u0006 \u0003אידי ואידי\u0004 \u0005[בזה ובזה]\u0006 \u0003אסור,\u0004 גם כשאינה מליאה, \u0003משום דמישחל שחיל\u0004 \u0005[\u0006שהמים \u0005מבצבצין\u0006 מתוך הכלי\u0005]\u0006 ויש בו משום רחיצה. \u0003רב פפא אמר: כסא דכספא\u0004 \u0005[כוס כסף]\u0006 כשהוא \u0003חסר, נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור\u0004 להצטנן בו, \u0003משום דמזדריב\u0004 \u0005[\u0006שעלול \u0005להחליק\u0006 מידו\u0005]\u0006 ועשוי להשפך.","מסופר: \u0003זעירא בר חמא אושפיזכנין\u0004 \u0005[בעל אכסנייתו]\u0006 של \u0003ר' אמי ור' אסי ור' יהושע בן לוי ודכולהו רבנן דקיסרי הוה\u0004 \u0005[ושל כל חכמי קיסריה היה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לרב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע בן לוי: בר אריא\u0004 \u0005[בן אריה]!\u0006 \u0003תא אימא לך מילתא מעליתא דהוה עביד אבוך\u0004 \u0005[בוא ואספר לך דבר מעולה שהיה עושה אביך]:\u0006 \u0003מטפחת היתה לו\u0004 שהיה מכין \u0003בערב יום הכפורים, ושורה אותה במים ועושה אותה כמין כלים נגובין\u0004 שתתייבש למדי, \u0003ולמחר מקנח בה פניו ידיו ורגליו. ערב תשעה באב,\u0004 שאיסורו אינו מדברי תורה אלא מדברי סופרים בלבד, היה \u0003שורה אותה במים ולמחר מעבירה על גבי עיניו.\u0004","\u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבה בר מרי\u0004 מארץ ישראל \u0003אמר: בערב תשעה באב\u0004 היו \u0003מביאין לו מטפחת ושורה אותה במים ומניחה תחת מראשותיו, ולמחר\u0004 כשנשאר בה רק מקצת לחלוחית, היה \u0003מקנח\u0004 בה \u0003פניו ידיו ורגליו. בערב יום הכפורים מביאין לו מטפחת ושורה אותה במים, ועושה אותה כמין כלים נגובין, ולמחר מעבירה על גבי עיניו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב לר' ירמיה בר תחליפא: איפכא אמרת לן\u0004 \u0005[\u0006אתה \u0005אמרת לנו להיפך]\u0006 מה שסיפר הוא לגבי יום הכיפורים אמרת לגבי תשעה באב, \u0003ואותיבנך סחיטה\u0004 \u0005[והקשינו עליך מאיסור סחיטה]\u0006 שהרי ביום הכיפורים דינו כשבת ואסור לסחוט בו דבר.","מסופר: \u0003אמר רב מנשיא בר תחליפא אמר רב עמרם אמר רבה בר בר חנה: שאלו את ר' אלעזר\u0004 בן פדת: מי שהוא \u0003זקן\u0004 (חכם) \u0003ויושב בישיבה,\u0004 שכבר מלמד חכמים אחרים, האם \u0003צריך ליטול רשות\u0004 מהנשיא \u0003להתיר בכורות\u0004 ביחיד, כשאר חכמים החייבים לקבל רשות מן הנשיא כדי להתיר בכורות ביחיד \u0003או אינו צריך?\u0004","ושואלים: \u0003מאי קא מיבעי להו\u0004 \u0005[מה נשאלה להם],\u0006 כלומר: מה בסיס השאלה? ומסבירים: \u0003הכי קא מיבעי להו\u0004 \u0005[כך נשאל להם]\u0006 \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר רב אידי בר אבין: דבר זה,\u0004 כלומר: ענין זה שצריך ליטול רשות מהנשיא \u0003הניחו להם לבי נשיאה\u0004 \u0005[לבית הנשיא]\u0006 \u0003כדי להתגדר בו\u0004 שיהא לגדולתם, ולכן \u0003צריך ליטול רשות,\u0004 כיון שיש בדבר זה משום כבוד הנשיא, \u0003או דילמא\u0004 \u0005[שמא],\u0006 \u0003כיון\u0004 ש\u0003זקן ויושב בישיבה\u0004 הוא, \u0003אין צריך. עמד ר' צדוק בן חלוקה על רגליו, ואמר: אני ראיתי את ר' יוסי בן זימרא שזקן ויושב בישיבה היה ועמד במעלה מזקנו של זה,\u0004 כלומר: עמד לפני זקנו של הנשיא הזה שבדורנו, \u0003ונטל\u0004 ממנו \u0003רשות להתיר בכורות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא: לא כך היה מעשה\u0004 כמו שאתה מתאר, \u0003אלא כך היה מעשה: ר' יוסי בן זימרא כהן היה, והכי קא מיבעיא ליה\u0004 \u0005[וכך נשאלה לו\u0006 השאלה\u0005]\u0006 האם \u0003הלכה כר' מאיר\u0004 ש\u0003אמר: החשוד בדבר לא דנו\u0004 (אינו רשאי לדון באותו דבר), \u0003ולא מעידו\u0004 (אסור לו להעיד אודותיו). וכיון שאנו יודעים שכהנים חשודים להטיל מום בבכורות, שהרי בזמן הזה אסורים הבכורות אף לכהנים אלא אם כן יש בהם מום, ראוי לשאול האם חשד זה קיים אף במי שהוא חכם ויושב בישיבה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003הלכה כרבן שמעון בן גמליאל\u0004 ש\u0003אמר:\u0004 אף החשוד \u0003נאמן הוא על של חבירו ואינו נאמן על של עצמו. ופשט ליה\u0004 \u0005[ואז ענה לו]\u0006 הנשיא כי \u0003הלכה כרבן שמעון בן גמליאל.\u0004 ולא היתה כאן קבלת רשות מן הנשיא, אלא שאלה בהלכה.","\u0003ותו קא מבעיא להו\u0004 \u0005[ועוד נשאלה להם],\u0006 כלומר: לאותם חכמים שישבו לפני ר' אלעזר ודנו בהלכות שונות, שכבר הזכרנו מקצת דיוניהם: \u0003מהו לצאת בסנדל של\u0004"],["\u0003שעם ביום הכפורים,\u0004 האם נחשב הוא כמנעל ואסור ללובשו ביום הכיפורים, או לא? \u0003עמד ר' יצחק בן נחמני על רגליו\u0004 להעיד, \u0003ואמר: אני ראיתי את ר' יהושע בן לוי שיצא בסנדל של שעם ביום הכפורים. ואמינא ליה\u0004 \u0005[ואמרתי לו]:\u0006 \u0003בתענית צבור\u0004 הנגזרת בשל מיעוט גשמים, שאף בה אסורה נעילת הסנדל, \u0003מאי\u0004 \u0005[מה\u0006 הוא הדין\u0005],\u0006 האם בסנדל של שעם מותר? \u0003אמר לי: לא שנא\u0004 \u0005[אינו שונה]\u0006 וגם אז מותר. \u0003אמר רבה בר בר חנה: אני ראיתי את ר' אלעזר דמן ננוה, שיצא בסנדל של שעם בתענית צבור ואמינא ליה\u0004 \u0005[ואמרתי לו]:\u0006 \u0003ביום הכפורים מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003אמר לי: לא שנא\u0004 \u0005[אינו שונה]\u0006 ומותר. ומסופר: \u0003רב יהודה נפק בדהיטני\u0004 \u0005[היה יוצא\u0006 ביום הכיפורים \u0005בסנדל של שעם].\u0006 \u0003אביי נפק בדהוצי\u0004 \u0005[היה יוצא\u0006 בסנדל \u0005של סיבי דקל].\u0006 \u0003רבא נפק בדיבלי\u0004 \u0005[\u0006בסנדל הקלוע \u0005מעשבים].\u0006 שכל אלו אינם נחשבים כמנעלים. \u0003רבה בר רב הונא כריך סודרא אכרעיה ונפיק\u0004 \u0005[היה כורך סודר על רגליו ויוצא].\u0006","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רמי בר חמא:\u0004 שנינו כי \u0003הקיטע יוצא בקב\u0004 (רגל מלאכותית) \u0003שלו\u0004 בשבת, משום שהוא כמנעל, \u0003דברי ר' מאיר. ור' יוסי אוסר. ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה],\u0006 כתוספת למשנה זו: \u0003ושוין\u0004 (ומסכימים) שניהם \u0003שאסור לצאת בו ביום הכפורים.\u0004 משמע, שאפילו במנעל של עץ אסור! \u0003אמר אביי: התם דאית ביה כתיתין\u0004 \u0005[שם\u0006 מדובר \u0005שיש בו סמרטוטים]\u0006 בתוך הקב, והאיסור איננו משום נעל אלא \u0003משום תענוג\u0004 שאסור ביום הכיפורים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 ראשית, \u0003ואי לאו מנא הוא\u0004 \u0005[אם\u0006 הקב \u0005איננו כלי]\u0006 וכי ה\u0003כתיתין משוי ליה מנא\u0004 \u0005[\u0006הם ש\u0005עושים אותו\u0006 ל\u0005כלי]?\u0006 \u0003ועוד: כל תענוג דלאו\u0004 \u0005[שאין]\u0006 \u0003מנעל הוא,\u0004 אלא תענוג הבא על ידי דבר אחר, \u0003מי\u0004 \u0005[האם]\u0006 \u0003אסור ביום הכפורים?\u0004 שהרי אין איסור על כל סוגי התענוג ביום הכיפורים אלא בעינויים המפורשים. ועוד: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר רב הונא הוה כריך סודרא אכרעיה ונפיק\u0004 \u0005[היה כורך סודר על רגליו ויוצא],\u0006 משמע שאין בכך איסור! \u0003ועוד\u0004 יש להקשות על דבריך: \u0003מדקתני סיפא\u0004 \u0005[ממה שנשנה בסוף\u0006 הלכה זו\u0005]:\u0006 \u0003אם יש לו\u0004 לקב \u0003בית קבול\u0004 מיוחד ל\u0003כתיתין —\u0004 הריהו \u0003טמא,\u0004 כדין שאר כלי עץ שיש להם בית קיבול. \u0003מכלל\u0004 הדברים שמע \u0003דרישא\u0004 \u0005[שבתחילת\u0006 ההלכה\u0005]\u0006 \u0003לאו בדאית ליה\u0004 \u0005[שאין לו\u0006 לקב\u0005]\u0006 \u0003כתיתין עסקינן\u0004 \u0005[עוסקים אנו],\u0006 אלא ודאי יש לדחות את דברי אביי.","\u0003אמר רבא: לעולם\u0004 תאמר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 קב זה \u0003כמנעל הוא, ובשבת בהא פליגי\u0004 \u0005[\u0006בענין \u0005זה נחלקו];\u0006 \u0003מר\u0004 \u0005[\u0006חכם \u0005זה\u0006 ר' יוסי\u0005]\u0006 \u0003סבר\u0004 כי \u0003גזרינן דילמא משתמיט ואתי לאתויי\u0004 \u0005[גוזרים אנו\u0006 לאסור בו \u0005שמא ישמט מרגלו ויבוא לטלטלו]\u0006 \u0003ארבע אמות\u0004 ברשות הרבים. \u0003ומר\u0004 \u0005[\u0006וחכם \u0005זה\u0006 ר' מאיר\u0005]\u0006 \u0003סבר\u0004 כי \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תינוקות מותרין בכולן,\u0004 כלומר: בכל הדברים האסורים למבוגרים משום עינוי. \u0003חוץ מנעילת הסנדל,\u0004 שאף לקטנים נאסרה. ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003נעילת הסנדל — דאמרי: אינשי עבדו ליה\u0004 \u0005[שאומרים\u0006 הרואים: \u0005אנשים\u0006 מבוגרים \u0005עשו לו זאת],\u0006 כיון שהוא עצמו אינו יכול לנעול, ודבר שהוא אסור לגדול, אסור לו לעשותו לאחר אף שעבורו דבר זה מותר. אולם אם מטעם זה \u0003הנך נמי אמרי: אינשי עבדו ליה\u0004 \u0005[אלה,\u0006 שאר האיסורים, \u0005גם כן אומרים: אנשים הם שעשו לו]\u0006 \u0003רחיצה וסיכה,\u0004 ויהיה אסור אף בהם! ומסבירים: ברחיצה וסיכה \u0003אימר מאתמול עבדי ליה\u0004 \u0005[אמור שמאתמול עשו להם]\u0006 ולא היום רחצום, שאין הדבר ניכר.","ומקשים: אם כן \u0003סנדל נמי אימר\u0004 \u0005[גם כן אמור]\u0006 שכבר \u0003מאתמול עבדי ליה\u0004 \u0005[עשו לו]!\u0006 ומשיבים: \u0003סנדל לא אפשר\u0004 לומר שכבר \u0003מאתמול עבדי ליה\u0004 \u0005[עשו לו],\u0006 כי בודאי חלצו את הסנדל בלילה. שהרי \u0003אמר שמואל: האי מאן דבעי למיטעם טעמא דמיתותא ליסים מסאני וליגני\u0004 \u0005[מי שרוצה לטעום טעם מיתה שינעל נעליים ויישן]\u0006 ובודאי אין אדם עושה זאת מרצונו.","ומקשים: \u0003והא מותרין לכתחלה קתני\u0004 \u0005[הרי מותרין לכתחילה שנינו],\u0006 ואם כן אף אם יעשה לו היום אין בכך כל משמעות, שהרי הדבר מותר מלכתחילה. \u0003אלא\u0004 כך יש לפרש: \u0003הנך\u0004 \u0005[אלה]\u0006 אותם דברים \u0003דלאו רביתיהו\u0004 \u0005[שאינם לצורך גידולם],\u0006 שהתינוק יכול להסתפק בלעדיהם \u0005—\u0006 \u0003גזרו בהו רבנן\u0004 \u0005[גזרו בהם חכמים\u0006 לאוסרם\u0005],\u0006 אבל \u0003הנך\u0004 \u0005[אלה]\u0006 אותם דברים \u0003דרביתייהו\u0004 \u0005[שהם לצורך גידולם] —\u0006 \u0003לא גזרו בהו רבנן\u0004 \u0005[גזרו בהם חכמים].\u0006 ש\u0003אמר אביי: אמרה לי אם\u0004 \u0005[אמרה לי אומנתי]:\u0006 \u0003רביתיה דינוקא\u0004 \u0005[גידולו של התינוק]\u0006 כשהוא קטן — זהו \u0003מיא חמימי ומשחא\u0004 \u0005[מים חמים ושמן]\u0006 למשוח אותו. \u0003גדל פורתא\u0004 \u0005[מעט]\u0006 — יעשו לו לאכול \u0003ביעתא בכותחא\u0004 \u0005[ביצה יחד עם כותח]\u0006 שהוא תבלין חמוץ מעורב בחלב. \u0003גדל פורתא\u0004 \u0005[קצת] —\u0006 יעשו לגידולו שיהיה לו \u0003תבורי מאני\u0004 \u0005[כלים לשבור],\u0006 שהוא נהנה מן השבירה. \u0003כי הא דרבה זבין להו מאני גזיזי דפחרא לבניה ומתברי להו\u0004 \u0005[כמו\u0006 שידענו \u0005שרבה היה קונה כלי חרס שבורים לבניו ושוברים אותם]\u0006 ונהנים מכך.","שנינו במשנה כי לדעת ר' אליעזר \u0003המלך והכלה ירחצו את פניהם\u0004 ביום הכיפורים. ושואלים: \u0003מתניתין מני\u0004 \u0005[משנתנו כשיטת מי היא]?\u0006 ומשיבים: כשיטת \u0003ר' חנניא בן תרדיון היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המלך והכלה לא ירחצו\u0004 ביום הכיפורים \u0003את פניהם. ר' חנניא בן תרדיון אומר משום ר' אליעזר: המלך והכלה ירחצו את פניהם.\u0004 ועוד אמרו: \u0003החיה\u0004 (היולדת) \u0003לא תנעול את הסנדל\u0004 ביום הכיפורים \u0003ר' חנניא בן תרדיון אומר משום ר' אליעזר: החיה תנעול את הסנדל.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של ר' אליעזר? ומסבירים: \u0003מלך, משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מלך ביפיו תחזינה עיניך\"\u0004 (ישעיה לג, יז), שראוי למלך להיות נאה תמיד. \u0003כלה מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003כדי שלא תתגנה על בעלה\u0004 שהוא צופה ומביט בה ביותר, ואם אינה רחוצה שמא תתגנה עליו בתחילת תקופת נשואיהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לר' חייא: כלה עד כמה\u0004 זמן לאחר נישואיה היא קרויה כן? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003אין מונעין תכשיטין מן הכלה\u0004 מחמת אבל שאירע לה \u0003כל שלשים יום\u0004 לנישואיה. משמע, שעיקר חיבתה של כלה הוא בשלושים ימים הראשונים.","\u0003החיה תנעול את הסנדל\u0004 מה הטעם — \u0003משום צינה,\u0004 שכיון שהיא חלשה מן הלידה יש לחשוש שמא תצטנן.","\u0003אמר שמואל: אם\u0004 חושש אדם ללכת יחף ביום הכיפורים \u0003מחמת סכנת עקרב\u0004 — \u0003מותר\u0004 לו לנעול נעליים, שאין צריך להסתכן מפני כך.","שנינו במשנה בשיעורי איסורי יום הכיפורים כי החיוב בשל איסור אכילה, חל על מי ש\u0003אוכל\u0004 כשיעור \u0003כותבת הגסה\u0004 (פרי תמר גדול). \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004"],["\u0003ככותבת שאמרו\u0004 לשיעור אכילה ביום הכיפורים, האם נפח זה נמדד \u0003בגרעינתה,\u0004 כלומר: עם הגרעין \u0003או בלא גרעינתה?\u0004 כיוצא בו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 השיעור שאנחנו קובעים לענין דיני טומאת המת \u0003כשעורה,\u0004 האם מדובר בנפח השעורה כשהיא \u0003בקליפתה או בלא קליפתה,\u0004 וכן האם מדובר בשיעורה כשהיא \u0003לחה או ביבשה?\u0004 ומעירים: \u0003רב אשי לא מבעיא ליה\u0004 \u0005[נשאלה לו],\u0006 לא נסתפקה לו \u0003הא\u0004 \u0005[\u0006שאלה \u0005זו]\u0006 של \u0003רב פפא.\u0004 ומדוע — \u0003\"גסה\" איתמר\u0004 \u0005[נאמר],\u0006 משמע: \u0003כל כמה\u0004 שהיא יותר \u0003גסה,\u0004 ולכן ודאי שהכוונה היא עם גרעינה. ולהיפך, \u0003רב פפא לא מבעיא ליה\u0004 \u0005[נשאלה לו],\u0006 לא נסתפקה לו שאלתו של \u0003רב אשי,\u0004 כי שעורה \u0003לחה — שבולת מיקרי\u0004 \u0005[נקראת]\u0006 ולא שעורה, ואילו \u0003שלא בקליפתה\u0004 כבר איננה נקראת שעורה אלא \u0003אושלא מיקרי\u0004 \u0005[נקראת].\u0006 אלא ודאי הכוונה לשעורה יבישה כשהיא עדיין בקליפתה.","\u0003אמר רבה אמר רב יהודה: כותבת הגסה שאמרו,\u0004 שיעורה \u0003יתירה\u0004 משיעור \u0003כביצה. וקים להו לרבנן\u0004 \u0005[ומוחזק להם לחכמים]\u0006 \u0003דבהכי מיתבא דעתיה\u0004 \u0005[שבכך,\u0006 בשיעור זה, \u0005מתיישבת דעתו]\u0006 של האוכל, ושוב אין כאן עינוי. \u0003בציר מהכי לא מיתבא דעתיה\u0004 \u0005[\u0006ב\u0005פחות מכאן אין מתיישבת דעתו].\u0006 \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003מעשה\u0004 היה בחג הסוכות \u0003והביאו לרבן יוחנן בן זכאי לטעום את התבשיל, ולרבן גמליאל שתי כותבות ודלי\u0004 (ספל) \u0003של מים. ואמרו\u0004 להם ר' יוחנן ורבן גמליאל: \u0003העלום לסוכה\u0004 ושם נאכל. \u0003ותני עלה\u0004 \u0005[ושנינו על כך\u0006 בברייתא\u0005]:\u0006 \u0003לא מפני שהלכה כך,\u0004 שאסור לטעום או לאכול דברים אלה חוץ לסוכה, \u0003אלא שרצו להחמיר על עצמן\u0004 שלא לאכול דבר מחוץ לסוכה.","וכנגד זה סיפרו \u0003וכשנתנו לו לר' צדוק אוכל פחות מכביצה — נטלו במפה\u0004 ולא נטל ידיו \u0003ואכלו חוץ לסוכה, ולא בירך אחריו\u0004 ברכת המזון."],["\u0003הא\u0004 \u0005[הרי]\u0006 ששיעור בגודל של \u0003כביצה בעי\u0004 \u0005[צריך\u0006 לאכול\u0005]\u0006 ב\u0003סוכה ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי שיעור \u0003כותבת הגסה שאמרו יתירה\u0004 על שיעור \u0003כביצה,\u0004 הרי אתה מגיע לסתירה, כי \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי מהשוואת המעשים הללו יוצא כי \u0003שתי כותבות בלא גרעינן לא הוו\u0004 \u0005[אינן]\u0006 מגיעות לשיעור \u0003כביצה,\u0004 אם כן, \u0003כותבת הגסה וגרעינתה\u0004 יחד \u0003מי הוי\u0004 \u0005[האם\u0006 יכול \u0005להיות]\u0006 שיעורה \u0003יתירה מכביצה?! אמר ר' ירמיה: אין\u0004 \u0005[כן],\u0006 ואין לתמוה על כך, כי אכן \u0003שתי כותבות בלא גרעינתן לא הוו\u0004 \u0005[אינן]\u0006 \u0003כביצה,\u0004 אבל \u0003כותבת הגסה וגרעינתה הוי\u0004 \u0005[הרי היא]\u0006 \u0003יתירה מכביצה,\u0004 לפי שגרעיני התמרה גדולים מאוד בשיעורם. \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים בני אדם]\u0006 בפתגם מקובל: \u0003תרי קבי דתמרי — חד קבא דקשיתא וסריח\u0004 \u0005[בשני קבים של תמרים\u0006 יש \u0005קב אחד של גרעינים ועוד],\u0006 משמע שבכל תמרה נפח הגרעין גדול מנפח הפרי.","\u0003רבא אמר:\u0004 קושיא זו כולה אין לה בסיס: \u0003התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 \u0003משום דהוו ליה פירי\u0004 \u0005[\u0006שהכותבות \u0005הן פירות]\u0006 \u0003ופירי לא בעו\u0004 \u0005[ופירות אינם צריכים]\u0006 \u0003סוכה,\u0004 שמותר לאכלם בכל שיעור מחוץ לסוכה. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על סברה זו\u0005]\u0006 ממה ש\u0003אמר רבי: כשהיינו לומדים תורה אצל ר' אלעזר בן שמוע הביאו לפנינו תאנים וענבים ואכלנום אכילת ארעי חוץ לסוכה.\u0004 ומדבריו נדייק: \u0003אכילת ארעי — אין\u0004 \u0005[כן]\u0006 מותר לאכול חוץ לסוכה, אולם \u0003אכילת קבע — לא,\u0004 שאם קבע סעודתו על פירות, אסור לאוכלם חוץ לסוכה! ודוחים: לא, אל תדייק כך אלא \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003אכלנום כאכילת עראי חוץ לסוכה,\u0004 לומר: אכילת פירות נחשבת תמיד כאכילת ארעי.","\u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שכך יש להבין: \u0003אכלנום\u0004 לפירות אלה \u0003אכילת קבע, ואכלנו פת אכילת עראי בהדייהו\u0004 \u0005[עמהם],\u0006 כדי לבטל קצת את מתיקותם היתירה \u0003חוץ לסוכה.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר שנוכל לסייע לו]\u0006 לרבא ממה ששנינו: \u0003לפיכך, אם השלים\u0004 שיעור אכילה בסוכה \u0003במיני תרגימא\u0004 \u0005[ממתקים] —\u0006 \u0003יצא\u0004 ידי חובת ישיבה בסוכה. \u0003ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003פירי בעו\u0004 \u0005[פירות צריכים]\u0006 \u0003סוכה\u0004 לאכילתן, אם כן שלא יאמר מיני תרגימא אלא \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003פירות!\u0004 ודוחים: אין מכאן ראיה, כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מיני תרגימא — פירות. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שזהו דווקא \u0003באתרא דלא שכיחי פירי\u0004 \u0005[במקום שאין מצויים פירות]\u0006 טריים ולכן אוכלים מיני ממתקים אחרים, אבל בודאי יכול להשלים בפירות, ואם כן אין להביא מכאן ראיה גמורה.","עד כאן דנו לפי ההנחה שיעור כותבת הגסה יתר על שיעור כביצה. \u0003רב זביד אמר:\u0004 אינו כן, אלא \u0003כותבת הגסה שאמרו — חסרה מכביצה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בית שמאי אומרים: שאור\u0004 שהוא הבצק החמוץ ביותר שמשתמשים בו כדי להחמיץ את העיסה שיעורו לאיסור בפסח — \u0003בכזית, חמץ\u0004 סתם שיעורו \u0003— בככותבת.\u0004","\u0003והוינן בה\u0004 \u0005[והיינו מתקשים בה]:\u0006 \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי?\u0004 וצריכים לומר שזה טעמם: \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"חמץ\", ולא בעי\u0004 \u0005[ולא יהיה צורך]\u0006 לכתוב \u0003\"שאור\", ואנא אמינא\u0004 \u0005[ואני אומר]\u0006 מן הסברה: \u0003ומה חמץ שאין חמוצו קשה\u0004 (חזק) כל כך — \u0003אסור בכזית, שאור שחמוצו קשה\u0004 שהרי הוא מחמיץ את העיסה \u0003לא כל שכן?\u0004 ולכן \u0003מדפלגינהו רחמנא\u0004 \u0005[מכיון שחילקה אותם התורה]\u0006 ואמרה \"שאור\" וכן \"חמץ\", בכך \u0003לימדה לך\u0004 ש\u0003שיעורו של זה לא כשיעורו של זה. שאור\u0004 שיעורו כרוב שיעורי תורה \u0003בכזית, חמץ\u0004 שאין חימוצו קשה כל כך — \u0003בככותבת.\u0004","ונברר, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003כותבת הגסה שאמרו יתירה מכביצה, מכדי\u0004 \u0005[הרי]\u0006 \u0003בית שמאי אשיעורא דנפיש\u0004 \u0005[על שיעור הגדול]\u0006 \u0003מכזית קא מהדרי\u0004 \u0005[הם מחפשים],\u0006 שהרי הוכיחו שחמץ צריך להיות בשיעור הגדול משיעור זית, ואם השיעור הקבוע הגדול מכזית הוא שיעור כביצה, אם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003כביצה\u0004 ולא ככותבת. \u0003ואי נמי כי הדדי נינהו\u0004 \u0005[ואם גם כן תאמר שזה כמו זה\u0006 בדיוק \u0005הם]\u0006 ושיעור הכותבת כשיעור הביצה, בכל זאת \u0003ניתני\u0004 \u0005[שישנה]\u0006 \u0003כביצה\u0004 שהוא השיעור הידוע והמקובל יותר! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003כותבת פחותה\u0004 בשיעורה \u0003מכביצה\u0004 ולכן תפסו לומר את השיעור הראשון הגדול מכזית.","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוכיח אתה דברים אלה? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא לך\u0004 \u0005[\u0006יכול \u0005אני לומר לך]\u0006 כי שיעור \u0003כותבת הגסה שאמרו — יתירה מכביצה, הא סתמא\u0004 \u0005[אולם\u0006 כותבת \u0005סתם]\u0006 שיעורה \u0003כביצה\u0004 ואין מכאן איפוא כל הוכחה לענייננו. \u0003ואי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר \u0003כי הדדי נינהו, וחדא מינייהו נקט\u0004 \u0005[שאפשר לומר שהם שוים זה לזה ואחד מהם לקח]\u0006 ואכן אין הבדל בין שיעור כותבת לשיעור ביצה כלל.","\u0003אלא,\u0004 מכאן אין להוכיח, ואם רצוננו בהוכחה הרי היא \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003עד כמה מזמנין — עד כזית,\u0004 שזהו השיעור הקטן ביותר שמברכים עליו ברכת המזון ומזמנים עליו, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: עד כביצה.\u0004 ומעתה נבאר: \u0003במאי קא מיפלגי\u0004 \u0005[במה\u0006 באיזה עיקרון \u0005נחלקו]?\u0006 \u0003ר' מאיר סבר\u0004 שאת הכתוב \"ואכלת ושבעת וברכת את ה' אלוהיך\" (דברים ח, י) יש להבין כך: \u0003\"ואכלת\" — זו אכילה, \"ושבעת\",\u0004 שמשמעה: תוספת הנאה באכילה — \u0003זו שתיה,\u0004 ושיעור \u0003אכילה\u0004 האמור בתורה בכל מקום הוא \u0003בכזית.\u0004 ואילו \u0003ר' יהודה סבר: \"ואכלת ושבעת\"\u0004 משמעו — \u0003אכילה שיש בה שביעה, ואי זה זה\u0004 — זה שיעור \u0003כביצה,\u0004 שרק בכמות זו יש כדי שביעה.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003כותבת הגסה שאמרו יתירה מכביצה,\u0004 אם כן יש לתמוה: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי ששיעור \u0003כביצה שבועי משבעא\u0004 \u0005[משביע הוא],\u0006 האם אפשר לומר כי \u0003דעתא לא מיתבא\u0004 \u0005[את הדעת אינה מיישבת]?!\u0006 והרי אמרנו שלענין יום הכיפורים אין צורך לאכול כדי שביעה, ואם אוכל כדי שדעתו של אדם מתיישבת בו ואינו מתענה עוד — הריהו אסור. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003כותבת הגסה שאמרו — פחות מכביצה.\u0004 ואכילת שיעור \u0003כביצה משבעא\u0004 \u0005[משביעה]\u0006 את האדם, אבל אכילת שיעור \u0003ככותבת\u0004 אינה אלא \u0003מיתבא דעתיה\u0004 \u0005[מיישבת דעתו].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבי אומר:\u0004"],["\u0003כל השיעורין כולן\u0004 האמורים בענין אכילה בתורה כולן \u0003בכזית, חוץ מטומאת אוכלין\u0004 (שיעור המאכל המטמא אחרים) \u0003ששינה הכתוב במשמען,\u0004 כלומר: באופן שבו ביטא איסור זה \u0003ושינו חכמים בשיעורן. וראיה לדבר\u0004 זה שמשום ששינה הכתוב במשמען שינו אף חכמים את שיעורן — מ\u0003יום הכפורים,\u0004 שאף בו כיון ששינה הכתוב בביטוי הדברים, שינו חכמים אף בשיעורו. ושואלים: \u0003מאי\u0004 \u0005[במה]\u0006 \u0003שינה הכתוב במשמעו — מ\"\u0004 כי כל הנפש אשר \u0003לא תענה\"\u0004 (ויקרא כג, כט), שלא נאמר \"כי כל הנפש אשר תאכל\", אלא \"אשר לא תעונה\". \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003שינו חכמים בשיעוריה\u0004 \u0005[בשיעורו] —\u0006 שאינו עובר אלא \u0003בככותבת\u0004 ולא כרגיל בכזית.","ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 צורך יש ב\u0003ראיה לדבר\u0004 ממה שיש שינוי ב\u0003יום הכפרים,\u0004 הרי בטומאה עצמה שינה הכתוב מן הלשון המקובל ובגלל זה שינו חכמים את שיעורו? ומשיבים: \u0003דאי מהתם\u0004 \u0005[שאם משם],\u0006 מהפסוק המדבר בדיני טומאה בלבד היינו למדים, \u0003הוה אמינא אורחא דקרא\u0004 \u0005[היינו אומרים כי דרך הכתוב]\u0006 \u0003הוא\u0004 ואין ללמוד הלכה למעשה משינוי זה, על כן בא המקרא ביום הכיפורים ומלמדנו שבכל מקום שיש שינוי בלשון הכתובים יש שינוי גם הלכה למעשה.","ושואלים לגופו של הענין: \u0003טומאת אוכלין\u0004 ששיעורה ב\u0003כביצה, מנא לן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר ר' אבהו אמר ר' אלעזר:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מכל האכל אשר יאכל\u0004 אשר יבוא עליו מים יטמא\u0003\"\u0004 (ויקרא יא, לד), ללמדנו שטומאת אוכלין חלה אף על \u0003אוכל הבא מחמת אוכל,\u0004 כלומר: על דבר מאכל הבא מתוך דבר אחר הנאכל גם הוא, \u0003ואיזה זה — ביצת תרנגולת.\u0004 ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שזה \u0003גדי,\u0004 שאף הוא אוכל הבא מתוך אוכל! ומשיבים: \u0003מחוסר שחיטה,\u0004 הגדי עדיין איננו נחשב כאוכל, שהרי צריך עוד לשוחטו, ורק לאחר שחיטה, כשיהיה בשר, יחשב כאוכל. ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שמדובר פה ב\u0003בן פקועה\u0004 (בולד הנולד מבהמה לאחר שנשחטה) ששחיטת אימו מכשירתו באכילה ואינו טעון שחיטה! ומשיבים: אף על פי כן \u0003טעון\u0004 הוא עדיין \u0003קריעה,\u0004 שהרי ודאי אין אוכלין אותו חי.","ושואלים: גם אם מפרשים ששיעור טומאת אוכלין הוא בכביצה, אם כן, \u0003ואימא\u0004 \u0005[ואמור]\u0006 שמדובר ב\u0003ביצת\u0004 העוף הענק \u0003בר יוכני!\u0004 ומשיבים: \u0003תפסת מרובה לא תפסת,\u0004 שאם אתה מניח שיעור מרובה, אינך יכול להוכיח זאת, ואפשר עדיין לומר כי השיעור מועט מזה, אולם \u0003תפסת מועט תפסת.\u0004 על כך מקשים: ואם כן \u0003אימא ביעתא דציפורתא דזוטר טובא\u0004 \u0005[אמור\u0006 שמדובר \u0005בביצת ציפור שהיא קטנה הרבה]!\u0006 ואם כן, אין הוכחה גמורה מלשון כתוב זה.","\u0003ר' אבהו דידיה\u0004 \u0005[משלו],\u0006 שלא משם רבותיו \u0003אמר:\u0004 מן הכתוב \u0003\"מכל האכל אשר יאכל\"\u0004 למדים: \u0003אוכל שאתה\u0004 יכול \u0003לאוכלו בבת אחת. ושיערו חכמים: אין בית הבליעה מחזיק יותר\u0004 מכדי שיעור \u0003ביצת תרנגולת,\u0004 וזהו איפוא שיעור טומאת אוכלין.","אגב הדיון בשיעורי תורה, \u0003אמר ר' אלעזר: האוכל חלב\u0004 בשגגה \u0003בזמן הזה צריך שיכתוב לו\u0004 מהו ה\u0003שיעור\u0004 המדוייק שאכל, \u0003שמא יבא בית דין אחר\u0004 לעתיד \u0003וירבה בשיעורין.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ירבה בשיעורין? אי נימא\u0004 \u0005[אם נאמר]\u0006 שבית הדין לעתיד \u0003דמחייבי\u0004 \u0005[יחייב]\u0006 \u0003קרבן\u0004 אפילו על שיעור \u0003כזית קטן,\u0004 פחות ממה שבזמננו נחשב לשיעור כזית, אולם במקרה זה לא יהא מקום להקריב קרבן חטאת, \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005הרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בפרשת חטאות: \u0003\"\u0004ואם נפש אחת תחטא בשגגה מעם הארץ בעשותה אחת ממצוות ה' \u0003אשר לא תעשינה בשגגה ואשם\"\u0004 (ויקרא ד, כז. וראה גם כב), ללמד: \u0003השב מידיעתו,\u0004 כלומר: אדם העושה תשובה כאשר נודע לו שחטא — הוא ה\u0003מביא קרבן על שגגתו.\u0004","אבל אם \u0003לא שב מידיעתו\u0004 חטאו, אלא מפני סיבה אחרת — \u0003אין מביא קרבן על שגגתו.\u0004 ואף כאן, מי שאכל פחות מכזית לפי השיעורים של עכשיו, אם בעתיד ישתנו השיעורים ויהיה באכילתו כשיעור כזית של אז — אינו מחויב קרבן, לפי שאדם זה יבוא להביא קרבן לא מפני שנודע לו מה שעשה, אלא שנודע לו ששינו את שיעורי התורה!","\u0003אלא,\u0004 כך יש לפרש: שיתכן ובעתיד \u0003לא מחייבי\u0004 \u0005[יחייבו]\u0006 בית הדין של אז \u0003קרבן עד דאיכא\u0004 \u0005[שיש]\u0006 באכילתו שיעור \u0003כזית גדול,\u0004 יותר מהשיעור של ימינו ולכן צריך לרשום כמה אכל, שמא כשיבוא בעתיד לבית הדין, יחליטו הם שהשיעור שאכל היה פחות מכזית ואינו חייב קרבן.","וחוזרים לענין הראשון: \u0003ולמאי דסליק אדעתיה מעיקרא\u0004 \u0005[ולמה שעלה על דעתו מתחילה]\u0006 לפרש שיתכן שבעתיד יהיו בתי הדין \u0003מחייבים קרבן\u0004 על שיעור \u0003כזית קטן,\u0004 הלא אין הלשון מדוייקת כלל כי \u0003מאי\u0004 \u0005[מה]\u0006 הלשון \u0003\"ירבה בשיעורין\"?\u0004 שהרי צריך היה לומר \"ימעט בשיעורים\"! ומתרצים: אפשר היה לפרשה: \u0003שמא ירבה בקרבנות מחמת\u0004 הקטנת ה\u0003שיעורין,\u0004 ש\"ירבה\" איננו מתייחס לשיעורין עצמם אלא לקרבנות הבאים מחמתם.","באותו נושא \u0003אמר ר' יוחנן: שעורין ועונשין הלכה למשה מסיני\u0004 הם. ותוהים: \u0003עונשין\u0004 של כל העבירות הלא \u0003מכתב כתיבי\u0004 \u0005[כתובים\u0006 בתורה במפורש\u0005]!\u0006 \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אמר ר' יוחנן: שיעורים של עונשין,\u0004 כלומר: מהו שיעור העונש לגבי כל עבירה — זו היא \u0003הלכה למשה מסיני.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שיעורין של עונשין — הלכה למשה מסיני. אחרים אומרים:\u0004 שיעורים אלה \u0003בית דינו של יעבץ\u0004 (עתניאל בן קנז) \u0003תיקנום.\u0004 ומקשים: כיצד אפשר לומר כן? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אלה המצות\"\u0004 (ויקרא כז, לד), ללמד: \u0003שאין נביא רשאי לחדש דבר מעתה,\u0004 אלא: אלה המצות, לא פחות ולא יותר! \u0003אלא,\u0004 יש לומר, כי לשיטה זו \u0003שכחום\u0004 במשך הדורות, \u0003וחזרו ויסדום\u0004 והודיעום לרבים בבית דינו של יעבץ.","במשנה שנינו כי \u0003השותה ביום ה\u0004כיפורים \u0003מלא לוגמיו —\u0004 חייב. \u0003אמר רב יהודה אמר שמואל: לא מלא לוגמיו ממש\u0004 שימלא במשקה את שתי לחייו, \u0003אלא\u0004 שיעור \u0003כל שאילו יסלקנו\u0004 את המשקה \u0003לצד אחד\u0004 בפיו \u0003ויראה\u0004 שם \u0003כמלא לוגמיו\u0004 — הרי הוא חייב עליו. ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנחנו שנינו\u0006 במשנה\u0005]\u0006 \u0003\"מלא לוגמיו\"\u0004 בלשון רבים, משמע: שנים! ומשיבים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003כמלא לוגמיו,\u0004 כלומר כשיעור הנראה מלוא לוגמיו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך מברייתא: \u0003כמה ישתה\u0004 אדם ביום הכיפורים \u0003ויהא חייב? בית שמאי אומרים: רביעית, ובית הלל אומרים: מלא לוגמיו. ר' יהודה אומר משום ר' אליעזר: כמלא לוגמיו. ר' יהודה בן בתירה אומר: כדי גמיעה.\u0004 והרי בברייתא זו אומרים בית הלל (שבודאי משנתנו כשיטתם, שהרי הלכה כמותם) ששיעור שתיה ביום הכיפורים הוא מלוא לוגמיו דווקא!","על כך תוהים: \u0003מי עדיפא ממתניתין דאוקימנא\u0004 \u0005[האם עדיפה\u0006 הברייתא בגירסתה \u0005ממשנתנו,\u0006 שהרי כבר \u0005העמדנוה]\u0006 \u0003\"כדי שיראה\"\u0004 כמלוא לוגמיו, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נפרש את דברי הברייתא כי לא מלוא לוגמיו ממש אלא \u0003כדי שיראה\u0004 כמלוא לוגמיו! ומסבירים: אין הקושי מלשון הברייתא, אלא \u0003אי הכי\u0004 \u0005[אם כך]\u0006 נפרש \u0003היינו\u0004 \u0005[הרי זה]\u0006 כשיטת \u0003ר' אליעזר\u0004 האומר \"כמלוא לוגמיו\"! ומתרצים: אפשר לומר כי \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 ב\u0003מלא לוגמיו דחוק,\u0004 שאינו ממש כשיעור זה, אלא פחות קצת. שלבית הלל צריך שיהיה כמלוא לוגמיו בריוח, ולר' אליעזר אפילו אם הוא כמלוא לוגמיו בדוחק — הרי זה חייב.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על הבנתנו זו \u0003רב הושעיא: אם כן\u0004 שאתה מפרש שאין הכוונה כמלוא לוגמיו אלא לוגם אחד, \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 לפיכך \u0003מקולי בית שמאי ומחומרי בית הלל\u0004 שהרי שיעור רביעית גדול ממלוא לוגמו, ואם כן מדוע אין מחלוקת זו מנויה בין שאר ההלכות שמנו במסכת עדיות שהם מקולי בית שמאי וחומרי בית הלל! \u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003כי אתשיל\u0004 \u0005[כאשר נשאלה]\u0006 שאלה זו לא נשאלה דווקא באדם רגיל, ששיעור אחד מלוגמיו הוא קטן מרביעית, אלא אף \u0003בעוג מלך הבשן אתשיל\u0004 \u0005[נשאלה]\u0006 שאלה זו, \u0003דהוו ליה בית שמאי לחומרא\u0004 \u0005[\u0006שדברי \u0005בית שמאי\u0006 שם \u0005הם להחמיר]\u0006 שלוגם אחד של עוג מלך הבשן בודאי גדול הרבה משיעור רביעית.","לגופה של ההלכה לענין שיעור שתיה \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003אכילה\u0004 ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 יש לו שיעור שוה \u0005—\u0006 \u0003בככותבת ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003שתיה,\u0004 ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מתחייב \u0003בדידיה\u0004 \u0005[ב\u0006שיעור \u0005שלו],\u0006 כלומר: בשיעור המיוחד לו, שהרי לכל אדם שיעור אחר למלוא לוגמיו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: קים להו לרבנן\u0004 \u0005[מוחזק להם לחכמים]\u0006 בשיעור \u0003ככותבת, דבהכי\u0004 \u0005[שבכך] —\u0006 \u0003מיתבא דעתיה\u0004 \u0005[מתיישבת דעתו],\u0006 \u0003בציר מהכי לא מיתבא\u0004 \u0005[\u0006ב\u0005פחות מכן אין מתיישבת\u0006 דעתו\u0005].\u0006 אולם \u0003בשתיה, בדידיה\u0004 \u0005[\u0006בשיעור מלוא לוגם \u0005שלו] —\u0006 \u0003מיתבא דעתיה\u0004 \u0005[מתיישבת דעתו],\u0006 אבל \u0003בדחבריה לא מיתבא דעתיה\u0004 \u0005[בשל חבירו\u0006 הקטן ממנו \u0005אין מתיישבת דעתו].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003ר' זירא\u0004 באופן אחר: \u0003וכל העולם כולו\u0004 מתיישבת דעתו \u0003בככותבת\u0004 וגם \u0003עוג מלך הבשן בככותבת?\u0004 ואם כן צריך להיות הבדל גם בשיעור אכילה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: קים להו לרבנן דבהכי מיתבא דעתיה, בציר מהכי לא מיתבא דעתיה\u0004 \u0005[מוחזק להם לחכמים שבכך מתיישבת דעתו בפחות מכך לא מתיישבת דעתו],\u0006 \u0003מיהו, כולי עלמא\u0004 \u0005[לכל העולם],\u0006 הרי זה ישוב דעת \u0003טובא\u0004 \u0005[רב],\u0006 ואילו ל\u0003עוג מלך הבשן\u0004 ברי זה ישוב הדעת \u0003פורתא\u0004 \u0005[מעט],\u0006 אבל מכל מקום יש בשיעור זה כדי ליישב את דעת כל אדם ולהפיג בכך את העינוי.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא\u0004 עוד: אם משום ישוב הדעת, אם אכל \u0003בשר שמן —\u0004 דעתו מתיישבת עליו \u0003בככותבת,\u0004 ואם אכל \u0003לולבי גפנים\u0004 (ענפים צעירים של גפנים) שראויים לאכילה, גם בהם מתיישבת דעתו \u0003בככותבת?\u0004 והרי ודאי שאינם משביעים באותה מידה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: קים להו לרבנן\u0004 \u0005[מוחזק להם לחכמים]\u0006 \u0003דבהכי\u0004 \u0005[שבכך] —\u0006 \u0003מיתבא דעתיה\u0004 \u0005[מתיישבת דעתו],\u0006 אבל \u0003בציר מהכי\u0004 \u0005[\u0006ב\u0005פחות מכך] —\u0006 \u0003לא מיתבא דעתיה\u0004 \u0005[מתיישבת דעתו].\u0006 \u0003מיהו\u0004 \u0005[אולם]\u0006 ב\u0003בשר שמן\u0004 יש בו ישוב הדעת — \u0003טובא\u0004 \u0005[רב],\u0006 ואילו ב\u0003לולבי גפנים\u0004 ישוב הדעת באכילתם — הוא \u0003פורתא\u0004 \u0005[מעט].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: כזית בכדי אכילת פרס\u0004 בשאר איסורי אכילה, שאם הוא אוכל שיעור כזית מדבר אסור בתוך כדי הזמן שאפשר לאכול בו חצי ככר לחם (\"פרס\"), הרי כל מה שאכל מצטרף ליחידה אחת ואם אכלו ביותר משיעור זמן זה, אינו מצטרך ופטור, ואילו ביום הכיפורים חייב האוכל \u0003כותבת\u0004 שמרובה הרבה מכזית וגם היא \u0003בכדי אכילת פרס?!\u0004 והרי יש בכך קולא, שהרי מאחר וזו כמות גדולה, יש סבירות שלא יוכל לסיים את אכילתו בכדי שיעור של אכילת פרס ויוצא איפוא שאין אכילתו מצטרפת וצריך הוא להיות פטור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: קים להו לרבנן דבהכי\u0004 \u0005[מוחזק להם לחכמים שבכך]\u0006 באוכל תוך שהות זמן זו \u0005—\u0006 \u0003מיתבא דעתיה\u0004 \u0005[מתיישבת דעתו],\u0006 אבל \u0003בטפי מהכי\u0004 \u0005[\u0006באוכל ושוהה \u0005יותר מזמן זה]\u0006 \u0003— לא מיתבא דעתיה\u0004 \u0005[אין דעתו מתיישבת\u0006 בכך\u0005]\u0006 ונשאר מעונה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא:\u0004 מצד אחד אומר אתה \u0003בכותבת בכדי אכילת פרס\u0004 נחשב שיעור אכילה, ולענין אכילת אוכל טמא, שגופו נטמא על ידי אכילה זו ששיעורה הוא \u0003חצי פרס\u0004 שהוא כמות של שני כביצים, שהיא כמות גדולה יחסית, גם כן צריך לאכול \u0003בכדי אכילת פרס?! אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא:\u0004 מכאן אין להקשות, \u0003הנח לטומאת גוויה\u0004 (לטומאת הגוף מחמת אוכל טמא) \u0003דלאו דאורייתא היא\u0004 \u0005[שאינה מן התורה]\u0006 אלא מדברי סופרים, והם הקלו בה, שאם אינו אוכל הרבה כל כך בתוך זמן כזה — אינה נחשבת לאכילה הגורמת לטומאה.","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב פפא הכי\u0004 \u0005[כך],\u0006 שטומאת גוויה מדברי סופרים? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"\u0004אל תשקצו את נפשותיכם בכל שרץ השורץ \u0003ולא תטמאו בהם ונטמתם בם\"\u0004 (ויקרא יא, מג) \u0003ואמר רב פפא: מכאן\u0004 ממה שנאמרה טומאה לגבי איסור אכילה למדנו \u0003שטומאת גוויה מדאורייתא\u0004 \u0005[מן התורה]!\u0006 היא. ומשיבים: לא היתה כוונת רב פפא שהדין הוא באמת מדין התורה, אלא דין זה אכן הוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003וקרא\u0004 \u0005[והכתוב]\u0006 שהביא רק לראיה \u0005—\u0006 \u0003אסמכתא בעלמא\u0004 \u0005[לסמך בלבד]\u0006 הוא.","שנינו במשנה ש\u0003כל\u0004 סוגי \u0003האוכלין\u0004 שאדם אוכל, מצטרפין זה לזה לשיעור לענין אכילה ביום הכיפורים. \u0003אמר רב פפא: אכל אומצא ומילחא\u0004 \u0005[בשר ומלח]\u0006 שעליו — הרי זה \u0003מצטרף\u0004 לשיעור ככותבת. \u0003ואף על גב דלאו אכילה היא\u0004 \u0005[ואף על פי\u0006 שאכילת מלח לעצמה \u0005אינה אכילה],\u0006 \u0003כיון דאכלי אינשי\u0004 \u0005[כיון שאוכלים בני אדם]\u0006 בשר ומלח יחד \u0005—\u0006 הרי הם \u0003מצטרפין\u0004 לכשיעור. וכן \u0003אמר ריש לקיש: ציר שעל גבי ירק מצטרף\u0004 לירק, לשיעור \u0003ככותבת ביום הכפורים.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן הוא\u0005]\u0006 ומדוע לא יצטרף, שהרי דבר אוכל הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 \u0003משקה הוא\u0004 ציר זה, ואין אוכל ומשקה מצטרפין, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]:\u0006 \u0003כל אכשורי אוכלא\u0004 \u0005[כל\u0006 דבר \u0005הבא להכשיר את האוכל]\u0006 לאכילה \u0005—\u0006 \u0003אוכלא אוכלא\u0004 \u0005[\u0006כ\u0005אוכל]\u0006 \u0003הוא\u0004 נחשב.","\u0003אמר ריש לקיש: האוכל אכילה גסה,\u0004 שהיא אכילה שאדם אוכל כשהוא שבע מאוד ונפשו קצה במאכל וכופה עצמו ואוכל עוד, \u0003ביום הכפורים\u0004 וכגון שאכל כדי שובעו ויותר בערב יום הכיפורים, ומיד שהתחיל הצום אכל דבר באכילה גסה — הריהו \u0003פטור\u0004 על אכילה זו. \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 משום שלא נאמר ביום הכיפורים איסור אכילה, אלא \u0003\"אשר לא תענה\"\u0004 (ויקרא כג, כט) \u0003כתיב\u0004 \u0005[נאמר],\u0006 משמע: \u0003פרט למזיק\u0004 את עצמו, שאיננו נהנה כלל מאכילתו.","וכגון זה \u0003אמר ר' ירמיה אמר ריש לקיש: זר שאכל תרומה אכילה גסה — משלם את הקרן,\u0004 כלומר מה שהזיק \u0003ואינו משלם את החומש\u0004 הנוסף שכל האוכל תרומה נותן כקנס לכהן. משום שנאמר באוכל תרומה: \"ואיש \u0003כי יאכל\u0004 קודש בשגגה ויסף חמישיתו עליו ונתן לכהן את הקודש\" (ויקרא כב, יד), \"יאכל\" — \u0003פרט\u0004 למי שאין זה נחשב לאוכל אלא ל\u0003מזיק\u0004 את עצמו, והוא משלם אומנם קרן משום שהזיק ממונו של הכהן, אולם קנס החומש שייך רק באוכל, ואכילה גסה אינה קרויה אכילה. ובדומה לזה \u0003אמר ר' ירמיה אמר ר' יוחנן: זר\u0004"],["\u0003שכוסס\u0004 (מכרסם) \u0003שעורים של תרומה\u0004 שלא נטחנו ולא נאפו — \u0003משלם את הקרן, ואינו משלם את החומש,\u0004 וטעמו: שנאמר: \u0003\"כי יאכל\"\u0004 (ויקרא כב, יד), \u0003פרט למזיק\u0004 ואכילת שעורים אינה נחשבת כאכילה.","\u0003אמר רב שיזבי אמר ר' יוחנן: זר שבלע שזפין של תרומה והקיאן ואכלן אחר\u0004 אחר כך, \u0003ראשון\u0004 שאכלן — \u0003משלם קרן וחומש\u0004 שהרי נהנה משזיפי התרומה, ומשעה שנהנה נתחייב בדמיהם והרי הם שלו, ולכן ה\u0003שני\u0004 שאכלם לאחר מכן, חייב לשלם לו תמורתם. ומכיון שלאחר שהקיאם הראשון שוב אינם ראויים אלא להסקה ואין השני אלא כאוכל עצים בלבד, לכן כשמשלם תמורתם \u0003— אין משלם אלא דמי עצים לראשון בלבד.\u0004","במשנה שנינו כי \u0003האוכל והשותה אין מצטרפין.\u0004 ושואלים: \u0003מאן תנא\u0004 \u0005[מיהו התנא]\u0006 הסבור כן? \u0003אמר רב חסדא: במחלוקת שנויה\u0004 הלכה זו, ושיטת \u0003ר' יהושע היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כלל אמר ר' יהושע: כל\u0004 שסוג \u0003טומאתו\u0004 (כגון טומאת ערב) \u0003ושיעורו\u0004 לענין טומאה (כגון בכזית) \u0003שוה\u0004 (כגון: שני חצאי זיתים משני מתים, או משתי נבילות, או שני חצאי עדשה משני שרצים) \u0003— מצטרף\u0004 ונעשים שניהם כשיעור אחד לטמא, אולם אם היתה","\u0003טומאתו\u0004 שוה \u0003ולא שיעורו\u0004 (כגון: חצי זית מן השרץ וחצי זית מן הנבילה), או \u0003שיעורו ולא טומאתו\u0004 (כגון: חצי זית מן המת וחצי זית מן הנבילה), וכל שכן כש\u0003לא טומאתו ולא שיעורו\u0004 שוים — \u0003אין מצטרפין.\u0004 ואף כאן, אף שגם אכילה וגם שתיה אסורים כל אחד כשלעצמו, כיון שאין שיעורן שוה — אין מצטרפין.","\u0003רב נחמן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כאן כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שם, \u0003עד כאן לא\u0004 שמענו כי \u0003קא אמרי רבנן התם\u0004 \u0005[שאמרו חכמים שם]\u0006 שדברים בשיעורים שונים מצטרפים, \u0003אלא לענין טומאה,\u0004 כיון ש\u0003שם,\u0004 מושג, ה\u0003טומאה חד היא\u0004 \u0005[אחד הוא]\u0006 ולכן על ידו מצטרפים סוגים שונים. \u0003אבל הכא\u0004 \u0005[אבל כאן]\u0006 \u0003— משום יתובי דעתא\u0004 \u0005[ישוב הדעת]\u0006 \u0003הוא, והאי לא מיתבא דעתיה\u0004 \u0005[וזה,\u0006 אכילה ושתיה יחד \u0005אינו מיישב את דעתו].\u0006","\u0003וכן אמר ריש לקיש:\u0004 שאלה זו, אם אכילה ושתיה כאחת מצטרפים לכדי שיעור לחייב ביום הכיפורים, \u0003במחלוקת\u0004 היא \u0003שנויה,\u0004 והשיטה שהובאה במשנה כי אינם מצטרפים, שיטת \u0003ר' יהושע היא, דתנן כלל אמר רבי יהושע כו'\u0004 וכפי שאמר רב חסדא. \u0003ור' יוחנן אמר\u0004 כדברי רב נחמן: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהיא כשיטת \u0005חכמים],\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[שאמרו חכמים שם]\u0006 \u0003אלא לענין טומאה, אבל הכא\u0004 \u0005[כאן],\u0006 \u0003משום יתובי דעתא\u0004 \u0005[ישוב הדעת]\u0006 \u0003הוא, והאי לא קא מיתבא דעתיה\u0004 \u0005[וזה אינו מיישב דעתו].\u0006","\u0003אכל ושתה בהעלם אחד\u0004 (בשגגה אחת), כגון ששכח שיום הכיפורים היום — \u0003אינו חייב\u0004 להביא \u0003אלא\u0004 קרבן \u0003חטאת אחת.\u0004 אולם אם \u0003אכל ועשה מלאכה\u0004 בשגגה, שמקור איסורם בשני מצוות לא תעשה אחרות — \u0003חייב שני חטאות,\u0004 לפי שהם שני גופי עבירה נבדלים. \u0003אכל אוכלין שאינן ראוין לאכילה\u0004 או \u0003שתה משקין שאינן ראוין לשתיה,\u0004 או ש\u0003שתה ציר\u0004 היוצא מן הדגים \u0003או מורייס\u0004 (ציר מלוח שכובשים בו דגים) — \u0003פטור,\u0004 לפי שאין זו דרך שתיה.","\u0003אמר ריש לקיש: מפני מה לא נאמרה אזהרה בעינוי?\u0004 כלומר: מדוע לא אמרה התורה בצורה מפורשת איסור זה של אכילה ושתיה ביום הכיפורים — \u0003משום דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר,\u0004 היה לכתוב אלא בצורה זו. ומסביר: \u0003היכי\u0004 \u0005[כיצד]\u0006 \u0003נכתוב? נכתוב רחמנא\u0004 \u0005[\u0006אם \u0005תכתוב התורה]:\u0006 \u0003\"לא יאכל\u0004 ביום הכיפורים\u0003\"\u0004— אולם לשון \u0003אכילה\u0004 בדרך כלל מורה על איסור אכילה \u0003בכזית\u0004 ואילו ביום הכיפורים השיעור הוא בככותבת! \u0003נכתוב רחמנא\u0004 \u0005[\u0006ואם \u0005תכתוב התורה]:\u0006 \u0003\"לא תענה\",\u0004 אולם לשון \"לא תעונה\" הרי מורה על שלילת העינוי, ו\u0003קום ואכול משמע.\u0004 ולכן נכתב: \"הנפש אשר לא תעונה\".","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הושעיא: נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 באופן זה: \u0003\"השמר פן לא תענה\"!\u0004 ומשיבים: \u0003אם כן נפישי להו לאוי\u0004 \u0005[מרובים יהיו בהם הלאוים],\u0006 שהרי גם לשון \"השמר\", \"פן\", וגם \"לא\" — הם ביטויים של איסור לא תעשה, והיינו אומרים איפוא שיש שלושה איסורים באכילה זו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ביבי בר אביי: נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]:\u0006 \u0003\"השמר במצות ענוי\"!\u0004 ודוחים: \u0003אם כן\u0004 נאמר כי לשון \u0003\"השמר\"\u0004 הכתובה לפני איסור \u0003לאו\u0004 — כ\u0003לאו\u0004 היא נחשבת, אולם לשון \u0003\"השמר\"\u0004 הכתובה לפני \u0003עשה\u0004 — הריהי נחשבת כמצות \u0003עשה,\u0004 ונבין מלשון הכתוב כאן שאכן יש מצות עשה בעינוי, אבל אין בכך משום איסור לא תעשה! \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: נכתוב\u0004 \u0005[שתכתוב\u0006 התורה\u0005]:\u0006 \u0003\"אל תסור מן העינוי\",\u0004 שמשמעותה איסור לא תעשה! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה],\u0006 שאכן יכול היה לכתוב בלשון כגון זו, שיש במשמעותה שלילה מפורשת.","על גוף איסורי האכילה והמלאכה אומרים: \u0003ותנא מייתי לה מהכא\u0004 \u0005[והתנא מביא,\u0006 לומד אזהרה \u0005זו\u0006 לעינוי ביום הכיפורים \u0005מכאן]:\u0006 נאמר: \u0003\"ועניתם את נפשתיכם כל מלאכה לא תעשו\"\u0004 (במדבר כט, ז). ודנים: \u0003יכול יהא ענוש על תוספת מלאכה\u0004 שיתחייב על מלאכה שעשה בזמן שמוסיפים מן החול על הקודש בערב יום הכיפורים — \u0003תלמוד לומר: \"וכל הנפש אשר תעשה כל מלאכה בעצם היום הזה\"\u0004 (ויקרא כג, ל), ללמדנו: \u0003על\u0004 עשיית מלאכה ב\u0003עיצומו של יום,\u0004 על היום עצמו, הריהו \u0003ענוש כרת,\u0004 אבל \u0003אינו ענוש כרת על תוספת מלאכה.\u0004","\u0003יכול לא יהא ענוש כרת על תוספת מלאכה, אבל יהא ענוש כרת על תוספת עינוי,\u0004 שאם אכל בתוספת יום הכיפורים יהא חייב — \u0003תלמוד לומר: \"כי כל הנפש אשר לא תענה בעצם היום הזה ונכרתה\"\u0004 (ויקרא כג, כט) לומר: \u0003על\u0004 אכילה ב\u0003עיצומו של יום ענוש כרת,\u0004 אבל \u0003אינו ענוש כרת על תוספת עינוי.\u0004","\u0003יכול לא יהא\u0004 העושה מלאכה בזמן הנוסף \u0003בכלל עונש\u0004 כרת \u0003אבל יהא מוזהר\u0004 במצוות לא תעשה \u0003על תוספת מלאכה — תלמוד לומר: \"וכל מלאכה לא תעשו בעצם היום הזה\"\u0004 (ויקרא כג, כח), לומר: \u0003על עיצומו של יום הוא מוזהר\u0004 שלא לעשות בו מלאכה, אבל \u0003אינו מוזהר על תוספת מלאכה.\u0004","\u0003יכול לא יהא מוזהר על תוספת מלאכה, אבל יהא מוזהר על תוספת עינוי,\u0004 שאם לא נתענה בתוספת יום הכיפורים יעבור על מצות לא תעשה — אין לומר כן, שהרי \u0003דין\u0004 (סברה) \u0003הוא\u0004 שאינו כן, \u0003ומה מלאכה שנוהגת\u0004 איסורה גם \u0003בשבתות וימים טובים — אינו מוזהר עליה\u0004 על תוספת קדושת היום, \u0003עינוי, שאינו נוהג בשבתות ויום טוב — אינו דין שלא יהא מוזהר עליו\u0004 על תוספת זו?! עד כאן לגבולות האיסור.","ומעירים: \u0003אבל אזהרה לעינוי של יום עצמו לא למדנו מניין.\u0004 ומעתה נלמד: \u0003לא יאמר\u0004 ויפרש בתורה \u0003עונש\u0004 כרת בעושה \u0003מלאכה, דגמר\u0004 \u0005[שנלמד\u0006 הדבר\u0005]\u0006 בהיקש \u0003מעינוי;\u0004 ונאמר כך: \u0003ומה\u0004 מצות \u0003עינוי שאינו נוהג בשבתות וימים טובים — ענוש כרת\u0004 אם לא התענה. איסור \u0003מלאכה שנוהגת\u0004 בכל \u0003שבתות וימים טובים — לא כל שכן\u0004 שנוהג אף ביום הכיפורים? אם כן \u0003למה נאמר\u0004 במפורש עונש למלאכה — \u0003מופנה\u0004 (נשאר פנוי) \u0003להקיש ולדון ממנו גזרה שוה: נאמר עונש בעינוי ונאמר עונש במלאכה, מה מלאכה — לא ענש אלא אם כן הזהיר\u0004 תחילה בלאו, \u0003אף עינוי לא ענש אלא אם כן הזהיר.\u0004","ודוחים: \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 להקשות\u0005]\u0006 את ההשוואה הזאת, כיצד: \u0003מה לעינוי שלא הותר מכללו\u0004 שמצות העינוי חלה על כל ישראל, \u0003תאמר במלאכה שהותרה מכללה\u0004 שהרי מותר לעשות את עבודות הקודש במקדש ביום הכיפורים! וכיון שכך אין הוכחה שמצות עינוי קלה ממצות מלאכה!","\u0003אלא\u0004 כך יש לומר: \u0003לא יאמר עונש בעינוי, דגמר\u0004 \u0005[שהוא לומד]\u0006 בקל וחומר \u0003ממלאכה.\u0004 כיצד? \u0003מה מלאכה שהותרה מכללה\u0004 בעבודת המקדש ביום הכיפורים בכל זאת — \u0003ענוש כרת\u0004 עליה, \u0003עינוי שלא הותר מכללו — לא כל שכן\u0004 שהעובר ואינו מתענה שחייב כרת. אם כן \u0003למה\u0004 בכל זאת \u0003נאמר\u0004 — הרי זה \u0003מופנה\u0004 ללא צורך, אלא \u0003להקיש ולדון ממנה גזירה שוה: נאמר עונש בעינוי ונאמר עונש במלאכה, מה מלאכה ענש והזהיר — אף עינוי ענש והזהיר.\u0004","ודוחים: \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך,\u0006 להקשות\u0005]\u0006 ולומר להיפך: \u0003מה למלאכה — שכן\u0004 איסורה \u0003נוהגת בשבתות וימים טובים. תאמר בעינוי שאינו נוהג בשבתות וימים טובים!\u0004","\u0003אמר רבינא:\u0004 לא הבנו כראוי את הלימוד בברייתא זו, כי \u0003האי תנא\u0004 \u0005[שנה זה]\u0006 מן המילים: \u0003\"עצם\u0004 היום הזה\u0003\" \"עצם\u0004 היום הזה\u0003\" גמר\u0004 \u0005[למד]\u0006 בגזירה שוה, להשוות עינוי למלאכה. ומעירים: וצריכים לומר ש\u0003מופנה\u0004 הוא, כלומר: שבשני המקומות המילה \"עצם\" איננה נחוצה לעניינה אלא רק ללמד גזירה שוה, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא מופנה\u0004 היא — \u0003איכא למיפרך כדפרכינן\u0004 \u0005[יש להקשות כמו שהקשינו]!\u0006","\u0003לאי, אפנויי\u0004 \u0005[על כן ודאי]\u0006 \u0003מופנה\u0004 הוא ויש ללמוד ממנו. שהרי \u0003חמשה קראי כתיבי\u0004 \u0005[כתובים נאמרו]\u0006 באיסור \u0003מלאכה\u0004 ביום הכיפורים, \u0003חד\u0004 \u0005[אחד]\u0006 ללמד \u0003אזהרה\u0004 לאיסור מלאכה \u0003דיממא\u0004 \u0005[של יום\u0006 הכיפורים\u0005],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003לאזהרה דליליא\u0004 \u0005[של ליל\u0006 יום הכיפורים\u0005],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003לעונש\u0004 כרת \u0003דיממא\u0004 \u0005[של\u0006 מלאכה \u0005ביום],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003לעונש דליליא\u0004 \u0005[של לילה],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003לאפנויי\u0004 \u0005[מופנה]\u0006 כדי \u0003למגמר\u0004 \u0005[ללמוד]\u0006 \u0003עינוי ממלאכה, בין דיממא\u0004 \u0005[של היום]\u0006 \u0003בין דליליא\u0004 \u0005[של הלילה],\u0006 שאף שלא נאמר הדבר במפורש — נלמד הוא בגזירה שוה.","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי ישמעאל תנא\u0004 \u0005[שנה]\u0006 כך: \u0003נאמר כאן \"עינוי\"\u0004 ביום הכיפורים, \u0003ונאמר להלן,\u0004 בדין האונס אשה \u0003\"עינוי\"\u0004 (\"על דבר אשר עינה את אשת רעהו\" — דברים כב, כד). \u0003מה להלן\u0004 בדין אונס \u0003לא ענש אלא אם כן הזהיר, אף כאן\u0004 ביום הכיפורים — \u0003לא ענש אלא אם כן הזהיר. רב אחא בר יעקב אמר\u0004 יש הוכחה אחרת: \u0003יליף\u0004 \u0005[לומד]\u0006 בגזירה שוה מן המילים \u0003\"שבת שבתון\"\u0004 הכתובות ביום הכיפורים \u0003משבת בראשית,\u0004 כלומר: משבת שהיא מימות בראשית, שגם בה נאמר \"שבת שבתון\", \u0003מה להלן\u0004 בשבת \u0003לא ענש אלא אם כן הזהיר, אף כאן — לא ענש אלא אם כן הזהיר.\u0004","\u0003רב פפא אמר:\u0004"],["\u0003הוא גופיה\u0004 \u0005[\u0006יום הכיפורים \u0005עצמו]\u0006 \u0003\"שבת\" איקרי\u0004 \u0005[נקרא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004מערב עד ערב \u0003תשבתו שבתכם\"\u0004 (ויקרא כג, לב). ומעתה משוים את הדעות השונות. \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003רב פפא לא אמר כרב אחא בר יעקב\u0004 — יש לו טעם, כיון \u0003דקרא דכתיב בגופיה\u0004 \u0005[מקרא הכתוב בגופו]\u0006 של הענין \u0003עדיף\u0004 על גזירה שוה. \u0003אלא רב אחא בר יעקב, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב פפא\u0004 ולמד ממקור אחר?","ומשיבים: פסוק זה \"תשבתו שבתכם\" \u0003מיבעי ליה\u0004 \u0005[דרוש הוא לו]\u0006 ללמוד ממנו \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"ועניתם את נפשתיכם בתשעה לחדש\u0004 בערב מערב עד ערב תשבתו שבתכם\u0003\"\u0004 (ויקרא כג, לב), \u0003יכול יתחיל ויתענה בתשעה\u0004 בתשרי — \u0003תלמוד לומר: \"בערב\", אי\u0004 \u0005[אם]\u0006 \u0003בערב — יכול\u0004 יתחיל התענית רק \u0003משתחשך — תלמוד לומר: \"בתשעה\"\u0004 משמע שמתחיל להתענות ביום תשעה בתשרי. \u0003הא כיצד\u0004 מיישבים את הכתובים? \u0003מתחיל\u0004 הוא \u0003ומתענה\u0004 תענית זו \u0003מבעוד יום,\u0004 ו\u0003מכאן\u0004 יש ללמוד \u0003שמוסיפין מחול על הקודש.\u0004","\u0003ואין לי אלא\u0004 שמוסיפין \u0003בכניסתו\u0004 כפי שמובן מן הכתובים, \u0003ביציאתו מנין\u0004 שמוסיפין? \u0003תלמוד לומר: \"מערב עד ערב\"\u0004 (ויקרא כג, לב) משמע שצריך להוסיף גם ביציאתו כבכניסתו. \u0003ואין לי אלא\u0004 מצות תוספת \u0003ביום הכפורים,\u0004 שצריך להוסיף מן החול על הקודש אף ב\u0003ימים טובים מניין? תלמוד לומר: \"תשבתו\"\u0004 (ויקרא כג, לב), לומר שאף ביום טוב שייך דין זה. \u0003אין לי אלא\u0004 שמוסיפים ב\u0003ימים טובים,\u0004 שיש להוסיף אף ב\u0003שבתות מנין — תלמוד לומר: \"שבתכם\"\u0004 (ויקרא כג, לב) \u0003הא כיצד? כל מקום שנאמר\u0004 לשון \u0003\"שבות\"\u0004 המורה כי הוא יום שביתה לישראל (\"שבתכם\") — \u0003מוסיפין מחול על הקודש.\u0004","ושואלים: \u0003ותנא\u0004 זה הלומד בגזירה שוה מן המילים \u0003\"עצם\" \"עצם\", האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"בתשעה לחדש\" מאי עביד ליה\u0004 \u0005[מה עושה הוא בו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתני\u0004 \u0005[צריך הוא לו לכפי ששנה]\u0006 \u0003רב חייא בר רב מדיפתי:\u0004 נאמר: \u0003\"ועניתם את נפשתיכם בתשעה\u0004 לחודש\u0003\"\u0004 (ויקרא כג, לב), \u0003וכי בתשעה\u0004 בתשרי \u0003מתענין? והלא בעשור\u0004 בו \u0003מתענין! אלא לומר לך: כל האוכל ושותה בתשיעי\u0004 ומכין עצמו לתענית \u0003מעלה עליו\u0004 (מחשיב אותו) \u0003הכתוב כאילו התענה תשיעי ועשירי,\u0004 ועל זה רמז הכתוב באומרו שהתענית היא בתשיעי.","שנינו במשנה שאם \u0003אכל אוכלין\u0004 שאינן \u0003ראויין לאכילה\u0004 \u0005—\u0006 פטור. \u0003אמר רבא: כס פלפלי ביומא דכפורי\u0004 \u0005[הכוסס פלפלים\u0006 חיים \u0005ביום ה\u0006כיפורים\u0005] —\u0006 \u0003פטור,\u0004 שאין זו אכילה. וכן \u0003כס זנגבילא ביומא דכפורי\u0004 \u0005[הכוסס זנגביל ביום ה\u0006כיפורים\u0005] —\u0006 \u0003פטור.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ש\u0003היה ר' מאיר אומר\u0004 על הכתוב: \"וכי תבואו אל הארץ ונטעתם כל עץ מאכל וערלתם ערלתו את פריו שלוש שנים\" (ויקרא יט, כג), \u0003ממשמע שנאמר: \"וערלתם ערלתו את פריו\"\u0004 (ויקרא יט, כג) \u0003איני יודע שעץ מאכל הוא,\u0004 שהרי נאמר \"פריו\"! \u0003אלא מה\u0004 בכל זאת \u0003תלמוד לומר\u0004 שם \u0003\"עץ מאכל\"?\u0004 — הרי זה בא לרבות \u0003עץ שטעם עצו ופריו שוה.\u0004 כלומר: עץ שאף הוא עצמו נאכל ולא פריו בלבד — \u0003הוי אומר זה פלפלין\u0004 (מזן הגדל על עץ), \u0003ללמדך\u0004 שאף \u0003הפלפלין חייבין בערלה.\u0004 וללמדך בדרך אגב אף \u0003שאין ארץ ישראל חסרה כלום,\u0004 שאף פלפלין יכולים לצמוח בה, \u0003שנאמר\u0004 במנין מעלותיה של ארץ ישראל כי בין שאר הדברים גם \u0003\"לא תחסר כל בה\"\u0004 (דברים ח, ט). על כל פנים למדנו מכאן שהפלפלים קרויים מאכל. ושלא כדברי רבא!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003ברטיבתא\u0004 \u0005[בפלפל רטוב],\u0006 שהוא ראוי למאכל, \u0003והא\u0004 \u0005[וזה] —\u0006 \u0003ביבשתא\u0004 \u0005[\u0006בפלפל \u0005יבש],\u0006 שאינו קרוי מאכל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר: והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: האי הימלתא\u0004 \u0005[זנגביל\u0006 מבושל \u0005זה]\u0006 \u0003דאתי מבי הנדואי\u0004 \u0005[שבא מהודו]\u0006 \u0003שריא\u0004 \u0005[מותר]\u0006 באכילה ואין לחשוש לאיסור מפני שבישלוהו הגוים, \u0003ומברכינן עליה\u0004 \u0005[ומברכים עליו]:\u0006 \u0003\"בורא פרי האדמה\".\u0004 הרי שהזנגביל הוא אוכל ראוי! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 \u0003ברטיבתא\u0004 \u0005[ב\u0006זנגביל \u0005רטוב]\u0006 שהוא נחשב לאוכל, \u0003והא\u0004 \u0005[וזה]\u0006 שאמרנו שאינו מאכל \u0003ביבישתא\u0004 \u0005[ביבש].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אכל\u0004 ביום הכיפורים \u0003עלי קנים — פטור. לולבי גפנים\u0004 (ענפים רכים של גפנים) — \u0003חייב.\u0004 ומבררים: \u0003אלו הן לולבי גפנים? אמר ר' יצחק מגדלאה\u0004 \u0005[מהעיר מגדל]:\u0006 \u0003כל שלבלבו מראש השנה ועד יום הכפורים\u0004 ועדיין הם רכים ביותר, הרי הם נחשבים לאוכל. \u0003ורב כהנא אמר: כל שלשים יום\u0004 ליום הכיפורים הרי הם נחשבים כאוכל. ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמותו,\u0006 כשיטתו\u0005]\u0006 של \u0003ר' יצחק מגדלאה: אכל עלי קנים — פטור, ולולבי גפנים — חייב. אלו הן לולבי גפנים — כל שלבלבו מראש השנה ועד יום הכפורים.\u0004","שנינו במשנה שאם \u0003שתה\u0004 ביום הכיפורים \u0003ציר או מורייס — פטור.\u0004 ומעירים: מלשון המשנה אפשר לדקדק וללמוד: \u0003הא\u0004 \u0005[הרי]\u0006 ששתה \u0003חומץ — חייב.\u0004 ויש לשאול: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003רבי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבי אומר: חומץ משיב את הנפש\u0004 ולכן דינו כמשקה.","מסופר: \u0003דרש רב גידל בר מנשה\u0004 מהעיר \u0003בירי דנרש: אין הלכה כרבי\u0004 ואין החומץ נחשב למשקה. \u0003לשנה\u0004 הבאה \u0003נפקי כולי עלמא מזגו ושתו חלא\u0004 \u0005[יצאו הכל מזגו\u0006 חומץ במים \u0005ושתו חומץ]\u0006 ביום הכיפורים, \u0003שמע רב גידל ואיקפד\u0004 \u0005[והקפיד\u0006 עליהם\u0005]\u0006 שהסתמכו כביכול על דבריו. \u0003אמר: אימר דאמרי אנא\u0004 \u0005[אמור שאמרתי אני]\u0006 שאם שתה זאת אינו מתחייב, דין זה הוא רק \u0003דיעבד\u0004 ולאחר מעשה, אולם לשתות \u0003לכתחלה מי אמרי\u0004 \u0005[האם אמרתי]\u0006 שמותר? ועוד: \u0003אימר דאמרי אנא פורתא, טובא מי אמרי\u0004 \u0005[אמור שאמרתי אני\u0006 בשותה \u0005מעט\u0006 אולם בשותה \u0005הרבה האם אמרתי]?\u0006 וכן: \u0003אימר דאמרי אנא\u0004 \u0005[אמור שאמרתי אני]\u0006 בחומץ \u0003חי\u0004 שהוא חריף מאוד, אולם ב\u0003מזוג מי אמרי\u0004 \u0005[האם אמרתי]\u0006 ובזה בודאי אסור."],["\u0003התינוקות אין מענין אותן\u0004 למנוע מהם אוכל \u0003ביום הכפורים, אבל מחנכין אותן\u0004 סמוך לבגרותם \u0003לפני שנה ולפני שנתים\u0004 בתענית חלקית לשעות, \u0003בשביל שיהיו רגילין במצות. \u0004","על לשון המשנה שואלים:\u0003השתא בפני שתים מחנכין להו\u0004 \u0005[אותם]\u0006 \u0003בפני שנה מבעיא\u0004 \u0005[הוצרכה]\u0006 לומר? ואם כן מיותר לכאורה ביטוי זה במשנה! \u0003אמר רב חסדא: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שנאמר כי יש לחנכו שנה טרם בגרותו — המדובר הוא בילד \u0003חולה, הא\u0004 \u0005[זה]\u0006 שאמרנו כי יש לחנכו שנתיים טרם בגרותו — המדובר הוא בילד \u0003בריא.\u0004","\u0003אמר רב הונא:\u0004 ילד בריא \u0003בן שמונה ובן תשע\u0004 שנים — \u0003מחנכין אותו לשעות,\u0004 שיתענה שעות אחדות. \u0003בן עשר ובן אחת עשרה — משלימין\u0004 את הצום \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003בן שתים עשרה — משלימין\u0004 את הצום \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003בתינוקת,\u0004 כלומר: כשמדובר פה בילדה, שהיא מגיעה לבגרות ומחוייבת בכל המצוות בהיותה בת שתים עשרה. \u0003ורב נחמן אמר:\u0004 לענין ילד, כשהוא \u0003בן תשע\u0004 ו\u0003בן עשר — מחנכין אותן לשעות, בן אחת עשרה\u0004 ו\u0003בן שתים עשרה — משלימין מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003בן שלש עשרה — משלימין מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003בתינוק,\u0004 כלומר, כשמדובר בילד זכר. \u0003ור' יוחנן אמר: השלמה דרבנן ליכא\u0004 \u0005[מדברי סופרים אין],\u0006 שאין משלימים להתענות מדברי חכמים, אלא: \u0003בן עשר ובן אחת עשרה — מחנכין אותו לשעות,\u0004 ו\u0003בן שתים עשרה — משלימין\u0004 תעניתם \u0003מדאורייתא\u0004 \u0005[מן התורה].\u0006","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003התינוקות אין מענין אותן ביום הכפורים אבל מחנכין אותן לפני שנה ולפני שתים,\u0004 כלומר: שנה או שנתיים לפני הסנה הסמוכה לבגרותם. \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003רב הונא ורב נחמן\u0004 הסוברים כי מגיל שלוש עשרה בילד יש דין השלמה לדברי תורה, ושנה קודם לכן, מגיל אחת עשרה, יש דין השלמה לדברי סופרים — הרי יש לפרש את דברי המשנה כך: שכולה מדברת בענין ילד חולה ו\u0003לפני שנה ולפני שתים,\u0004 הכוונה: \u0003לפני שנה\u0004 הסמוכה לאותה שנה בה הוא חייב להשלים כבר \u0003לדבריהן\u0004 של תורה, כלומר: מגיל אחת עשרה, ו\u0003לפני שתים\u0004 לאותה שנה, כלומר: מגיל עשר, חייב הוא להשלים \u0003לדבריהן\u0004 של סופרים.","\u0003אלא לר' יוחנן\u0004 הסובר כי אין דין השלמה מדברי סופרים, \u0003קשיא\u0004 \u0005[קשה]\u0006 מה החלוקה לפני שנה לפני שתים? \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' יוחנן: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שנה או שתים\u0004 — הכוונה: לא בשנה לפני השנה הסמוכה לבגרותם או בשנתיים הסמוכות לה, אלא הכוונה ממש \u0003סמוך לפירקן\u0004 (לבגרותם), כלומר: מגיל אחת עשרה או שתים עשרה וההבדל בין אלו הצריכים שנה לאלו הצריכים שתיים, הוא במצב בריאותו של הילד, שהבריא צריך שתים והחולה די לו באחד.","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה ששנה \u0003רבה בר שמואל\u0004 בברייתא: \u0003תינוקות אין מענין אותן ביום הכפורים, אבל מחנכין אותן שנה\u0004 (בחולה) \u0003או שתים\u0004 (בבריא) \u0003סמוך לפירקן. בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' יוחנן — ניחא\u0004 \u0005[נוח]\u0006 הדבר \u0003אלא לרב הונא ולרב נחמן\u0004 שלשיטתם יש צורך בשנה נוספת להשלמה שמדברי סופרים, \u0003קשיא\u0004 \u0005[קשה]!\u0006 \u0003אמרי לך רבנן\u0004 \u0005[\u0006היו יכולים \u0005לומר לך חכמים\u0006 אלה\u0005]:\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003חינוך\u0004 זה \u0003נמי דקתני\u0004 \u0005[ששנינו גם כן\u0006 שם\u0005]\u0006 — כוונתו \u0003השלמה\u0004 שמדברי סופרים ואנו סבורים כי אף לדבריהם, זמן ההשלמה בבריא הוא שנתיים.","ושואלים: \u0003ומי קרי\u0004 \u0005[האם קורים]\u0006 \u0003לחינוך השלמה,\u0004 שהרי חינוך פירושו לכאורה שעושה רק מקצת המצוה, \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא מפורשת\u0005]:\u0006 \u0003אי זה חינוך? היה רגיל\u0004 הילד \u0003לאכול\u0004 בכל יום \u0003בשתי שעות\u0004 לתחילת היום — \u0003מאכילין אותו לשלש,\u0004 כדי שידע מקצת ענין עינוי. ואם רגיל \u0003בשלש\u0004 שעות — \u0003מאכילין אותו בארבע. אמר רבא בר עולא:\u0004 אין זו קושיה, כי \u0003תרי חנוכי הוו\u0004 \u0005[שני חינוכים הם],\u0006 יש חינוך שמחנכים התינוקות הקטנים לאחר קצת את זמן האכילה, ויש חינוך שמרגילין את הילדים הגדולים יותר לצום יום שלם.","\u0003עוברה\u0004 (אשה בהריון) \u0003שהריחה\u0004 דבר מאכל ואחזתה תאוה לאוכלו — \u0003מאכילין אותה עד שתשיב נפשה,\u0004 שאם לא כן, הריהי מסתכנת בנפשה. \u0003חולה\u0004 הזקוק לאכול מפני הסכנה — \u0003מאכילין אותו על פי בקיאין,\u0004 כלומר: שני מומחים ברפואה האומרים שהוא זקוק לכך. \u0003ואם אין שם בקיאין — מאכילין אותו על פי עצמו עד שיאמר די,\u0004 כלומר: עד שיאמר שאיננו זקוק לכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003עוברה שהריחה בשר קודש או בשר חזיר\u0004 ונתאוותה דווקא לו — \u0003תוחבין לה כוש\u0004 (פלך, מקל דק) \u0003ברוטב\u0004 של אותו דבר \u0003ומניחין לה על פיה, אם נתיישבה דעתה\u0004 בכך — \u0003מוטב, ואם לאו,\u0004 שלא נתיישבה בכך דעתה — \u0003מאכילין אותה\u0004 אותו \u0003רוטב\u0004 (מרק) \u0003עצמה\u0004 של אותו מאכל אסור. \u0003אם נתיישבה דעתה\u0004 בכך — \u0003מוטב, ואם לאו מאכילין אותה שומן עצמו\u0004 של האיסור. \u0003שאין לך דבר שעומד בפני פקוח נפש, חוץ\u0004 מאיסורים הללו: \u0003עבודה זרה וגילוי עריות ושפיכות דמים.\u0004","ומבררים: \u0003עבודה זרה מנלן\u0004 \u0005[מניין לנו]\u0006 שחייב למסור נפשו על כך — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר:\u0004 נאמר: \"ואהבת את ה' אלהיך בכל לבבך ובכל נפשך ובכל מאודך\" (דברים ו, ה) \u0003אם נאמר \"\u0004ו\u0003בכל נפשך\" למה נאמר \"\u0004ו\u0003בכל מאדך\"\u0004 (דברים ו, ה)? \u0003ואם נאמר \"\u0004ו\u0003בכל מאדך\" למה נאמר \"בכל נפשך\"!\u0004","אלא: \u0003אם יש לך אדם שגופו חביב עליו מממונו, לכך נאמר: \"\u0004ו\u0003בכל נפשך\"\u0004 — שחייב למסור את נפשו, \u0003ואם יש לך אדם שממונו חביב עליו מגופו, לכך נאמר: \"ובכל מאדך\".\u0004 הרי שלענין עיקר האמונה שבה מתבטאת אהבת ה', כגון הימנעות מעבודה זרה — חייב אדם למסור את נפשו עליה.","\u0003גילוי עריות ושפיכת דמים מנא לן\u0004 \u0005[מניין לנו]\u0006 שמוסר נפשו עליהם — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003רבי אומר:\u0004 נאמר באונס נערה המאורסה: \u0003\"כי כאשר יקום איש על רעהו ורצחו נפש כן הדבר הזה\"\u0004 (דברים כב, כו), ויש לתהות: \u0003וכי מה ענין למדנו מרוצח לנערה המאורסה?\u0004 שהרי דין הנערה המאורסה מפורש, ומה חידוש למדים אנו מהשוואתו לדין הרוצח?","\u0003אלא: הרי זה\u0004 דין הרוצח \u0003בא\u0004 לכאורה \u0003ללמד\u0004 על נערה המאורסה, \u0003ונמצא למד\u0004 ממנה. וכך הלימוד: \u0003מה נערה המאורסה ניתן להצילה בנפשו,\u0004 שמותר להציל את הנערה אפילו אם יחייב הדבר להרוג לצורך זה את הרודף אחריה — \u0003אף רוצח ניתן להצילו בנפשו,\u0004 כלומר: להציל את הנרדף על ידי הריגת הרודף. ויש גם לימוד לצד שני: \u0003מה רוצח\u0004 יש בו משום \u0003יהרג ואל יעבור,\u0004 שחייב אדם אף להיהרג ובלבד שלא יהרוג את הנפש \u0003— אף נערה המאורסה\u0004 הרי זו מצוות \u0003יהרג ואל יעבור,\u0004 שחייב אדם למסור עצמו למיתה ובלבד שלא יבוא על הערוה."],["ושואלים: \u0003ורוצח גופיה\u0004 \u0005[עצמו]\u0006 \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 שיהרג ואל יעבור? ומשיבים: דבר זה \u0003סברא היא,\u0004 שכך צריך להיות. כפי שמסופר: \u0003דההוא דאתא לקמיה\u0004 \u0005[אחד שבא לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 לרבא: \u0003אמר לי מרי דוראי\u0004 \u0005[אדון הכפר]\u0006 שאני גר בו: \u0003קטליה לפלניא\u0004 \u0005[הרוג את פלוני],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תעשה כן — \u0003קטילנא לך\"\u0004 \u0005[הורג אני אותך],\u0006 איך צריך אני לנהוג בכגון זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נקטלך\u0004 \u0005[שיהרוג אותך]\u0006 \u0003ולא תקטול\u0004 \u0005[תהרוג].\u0006 וטעמו: \u0003מאי חזית דדמא דידך סומק טפי\u0004 \u0005[מה ראית שדמך אדום\u0006 וחשוב \u0005יותר]?\u0006 \u0003דילמא דמא דההוא גברא סומק טפי\u0004 \u0005[שמא דמו של אותו אדם אדום יותר]\u0006 והוא חשוב יותר, ואם כן סברה היא שלא יהרוג אחר כדי להנצל בעצמו.","ולענין המעוברת שהריחה מסופר: \u0003ההיא עוברה דארחא\u0004 \u0005[מעוברת אחת שהריחה]\u0006 דבר מאכל ונתאוותה לאוכלו, \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבי, אמר להו\u0004 \u0005[להם]\u0006 לשואלים: \u0003זילו לחושו\u0004 \u0005[לכו ולחשו]\u0006 \u0003לה\u0004 באזנה \u0003דיומא דכיפורי\u0004 \u0005[שיום הכיפורים]\u0006 \u0003הוא. לחושו לה\u0004 \u0005[לחשו]\u0006 \u0003ואילחישא\u0004 \u0005[\u0006והועילה לה \u0005הלחישה]\u0006 ופסקה מלהתאוות. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 רבי על התינוק לו היתה מעוברת: \u0003\"בטרם אצרך בבטן ידעתיך\u0004 ובטרם תצא מרחם הקדשתיך\u0003\"\u0004 (ירמיה א, ה), ואכן אותו תינוק ש\u0003נפק מינה\u0004 \u0005[יצא ממנה]\u0006 מאותה אשה, היה \u0003ר' יוחנן.\u0004","וסיפור אחר: \u0003ההיא עוברה דארחא,\u0004 \u0005[מעוברת אחת שהריחה]\u0006 ונתאוותה ביום הכיפורים לאכילה, \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' חנינא\u0004 בשאלה מה לעשות עימה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לחושו\u0004 \u0005[לחשו]\u0006 \u0003לה\u0004 שיום הכיפורים היום, ואף שאכן לחשו לה כדבריו בכל זאת \u0003לא אילחישא\u0004 \u0005[נלחשה],\u0006 שהמשיכה להתאוות לאכילה. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 ר' חנינא על תינוק זה:"],["\u0003\"זרו רשעים מרחם\"\u0004 (תהלים נח, ד), כלומר: מבטן אמם התברר שהם זרים. ואכן \u0003נפק מינה\u0004 \u0005[יצא ממנה]\u0006 \u0003שבתאי אצר פירי\u0004 \u0005[אוצר הפירות],\u0006 שהיה אוצר הפירות בשנות רעבון כדי להפקיע מחירם ולהרוויח כסף מן העניים.","שנינו במשנה: \u0003חולה מאכילין אותו על פי בקיאין. אמר ר' ינאי: חולה אומר\u0004 שהוא \u0003צריך\u0004 לאכול, \u0003ורופא אומר\u0004 כי \u0003אינו צריך — שומעין לחולה\u0004 בזה, \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 משום שנאמר: \u0003\"לב יודע מרת נפשו\"\u0004 (משלי יד, י), כלומר: החולה יודע את עוצם הכאב וחולשת הגוף שיש לו ואין הרופא יכול לומר שאינו כפי דבריו. ומקשים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שהרי אדם יודע על עצמו יותר מאחר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 כי ה\u0003רופא קים ליה טפי\u0004 \u0005[ברור לו יותר],\u0006 אם הצורך הוא ממשי או אינו ממשי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת החולה עצמו יודע בסבלו יותר מכל אחר ולו המומחה ביותר.","ולהיפך: \u0003רופא אומר\u0004 ש\u0003צריך\u0004 החולה לאכול, \u0003והחולה\u0004 עצמו \u0003אומר אינו צריך — שומעין לרופא. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003תונבא הוא דנקיט ליה\u0004 \u0005[טשטוש הדעת הוא שתפס אותו],\u0006 שמחמת המחלה נטשטשה הכרתו, ואין הוא עצמו יודע עד כמה זקוק הוא לאוכל.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003חולה מאכילין אותו על פי בקיאין.\u0004 ונדייק מכאן: כי \u0003על פי בקיאין — אין\u0004 \u0005[כן],\u0006 אולם \u0003על פי עצמו — לא,\u0004 ושלא כדברי ר' ינאי! ועוד יש לדייק: \u0003על פי בקיאין — אין\u0004 \u0005[כן],\u0006 \u0003על פי בקי אחד — לא,\u0004 ונאמר שצריכים שני רופאים דווקא, וגם זה שלא כדברי רב ינאי, שלדעתו במקרה שאין דעת החולה עצמו מכריעה, די בדעת בקי אחד!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה מיוחד, שהחולה \u0003אמר לא צריכנא\u0004 \u0005[אינני צריך]\u0006 ולכן יש צורך לדעת הבקיאין, ושואלים: \u0003וליספו ליה\u0004 \u0005[ושיאכילו אותו]\u0006 \u0003על פי בקי\u0004 אחד, שהרי אמר ר' ינאי שבכגון זה שומעים לרופא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דאיכא אחרינא בהדיה דאמר\u0004 \u0005[שיש\u0006 רופא \u0005אחר אתו האומר]\u0006 כי \u0003לא צריך\u0004 אדם זה לכך ואז \u0003מאכילין אותו על פי בקיאין\u0004 — על פי שני רופאים האומרים צריך.","ושואלים: אם כן הרי זה \u0003פשיטא\u0004 \u0005[פשוט],\u0006 הלא \u0003ספק נפשות הוא,\u0004 אם צריך או אינו צריך, \u0003וספק נפשות להקל!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דאיכא תרי אחריני בהדיה דאמרי\u0004 \u0005[שיש שני\u0006 רופאים \u0005אחרים אתו\u0006 עם החולה \u0005שאומרים]\u0006 שהוא \u0003לא צריך. ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003אמר רב ספרא: תרי\u0004 \u0005[שני]\u0006 עדים דינם \u0003כמאה ומאה\u0004 דינם \u0003כתרי\u0004 \u0005[כשנים],\u0006 ששני עדים או יותר הם עדות שלימה, ואין הבדל בין עדות שנים לעדות מספר גדול של אנשים, \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003לענין עדות, אבל לענין אומדנא\u0004 \u0005[ההערכה]\u0006 של דברים — \u0003בתר\u0004 \u0005[אחר]\u0006 מספר ה\u0003דעות אזלינן\u0004 \u0005[אנו הולכים],\u0006 ואם מרובים האומדים את הדבר בדרך אחת — נוהגים אנו כדעתם.","אולם, \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא \u0003לענין אומדנא דממונא\u0004 \u0005[הערכה של ממון],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003ספק נפשות הוא,\u0004 וכיון שיש שני רופאים האומרים כן — צריך שיאכל.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסופה\u0006 של המשנה\u0005]\u0006 שאם \u0003אין שם בקיאין מאכילין אותו על פי עצמו, מכלל\u0004 הדברים שומע אתה \u0003דרישא\u0004 \u0005[שבראשה\u0006 של המשנה\u0005]\u0006 הכוונה שהחולה \u0003אמר\u0004 שהוא \u0003צריך,\u0004 ועל כך אמרה המשנה כי על פי בקיאים, הריהו הוא אוכל אבל לא על פי עצמו! ומתרצים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך יש לשנותה]:\u0006 \u0003במה דברים אמורים\u0004 שאינו אוכל אלא על פי בקיאים — כש\u0003אמר לא צריך אני, אבל\u0004 אם \u0003אמר צריך אני,\u0004 ו\u0003אין שם בקיאין תרי\u0004 \u0005[שנים]\u0006 \u0003אלא\u0004 רק \u0003חד\u0004 ש\u0003אמר\u0004 כי הוא \u0003לא צריך — מאכילין אותו על פי עצמו.\u0004","\u0003מר בר רב אשי אמר: כל היכא\u0004 \u0005[היכן]\u0006 \u0003דאמר\u0004 \u0005[שאומר]\u0006 האיש החולה \u0003צריך אני, אפילו איכא מאה\u0004 בקיאים \u0003דאמרי\u0004 \u0005[האומרים]\u0006 כי הוא \u0003לא צריך — לדידיה שמעינן\u0004 \u0005[לו\u0006 אנו \u0005שומעין],\u0006 ומדוע? — \u0003שנאמר: \"לב יודע מרת נפשו\"\u0004 (משלי יד, י).","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם\u0004 החולה עצמו אומר כי הוא צריך לאכול ו\u0003אין שם בקיאין — מאכילין אותו על פי עצמו.\u0004 ולכאורה אפשר להבין מכאן: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003בקיאין, הא איכא\u0004 \u0005[הרי אם יש]\u0006 \u0003בקיאין — לא\u0004 ושומעין לבקיאים ולא לו! ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שנוהגים על פי בקיאים — כש\u0003אמר \"לא צריך אני\". אבל אמר \"צריך אני\", אין שם בקיאין כלל — מאכילין אותו על פי עצמו, שנאמר: \"לב יודע מרת נפשו\",\u0004 שכל הבקיאים אינם נחשבים לעומת הרגשתו של החולה.","\u0003מי שאחזו בולמוס\u0004 (חולי הגורם לתאוות רעב שאי אפשר לעמוד בפניה והלוקה בו ראייתו נחלשת ומסתכן בנפשו) — \u0003מאכילין אותו\u0004 בכל יום, אף ביום הכיפורים \u0003אפילו דברים טמאים — עד שיאורו עיניו\u0004 והוא סימן שהתאושש. \u0003מי שנשכו כלב שוטה אין מאכילין אותו מחצר כבד שלו\u0004 (של הכלב) שהיה נחשב לסגולה למחלה זו, כי לדעת חכמים אין הדבר מועיל כלל. \u0003ור' מתיא בן חרש מתיר\u0004 להאכילו, שלדעתו הדבר מועיל.","\u0003ועוד אמר ר' מתיא בן חרש: החושש\u0004 (הסובל מכאב) \u0003בגרונו מטילין לו סם בתוך פיו בשבת,\u0004 אף על פי שאסור להתרפא בשבת, \u0003מפני שהוא ספק נפשות,\u0004 שכל כאב פנימי קשה לעמוד על טיבו ומידת סכנתו, \u0003וכל ספק נפשות דוחה את השבת.\u0004","כיוצא בו: \u0003מי שנפלה עליו מפולת, ספק הוא שם\u0004 תחת המפולת \u0003ספק אינו שם, ספק חי\u0004 עדיין \u0003ספק מת, ספק\u0004 אם האיש תחת המפולת הוא \u0003גוי, ספק ישראל — מפקחין\u0004 (מפנים) \u0003עליו את הגל.\u0004 כלומר: עושים כל מלאכה להוריד את גל האבנים מעליו. \u0003מצאוהו\u0004 שם לאחר פינוי חלקי של המפולת, אם נמצא שעדיין הוא \u0003חי — מפקחין\u0004 הלאה עד שיוציאוהו, \u0003ואם\u0004 נמצא \u0003מת — יניחוהו,\u0004 שאין מחללים את השבת משום כבוד המת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מניין היו יודעין שהאירו עיניו — משיבחין בין\u0004 אוכל \u0003טוב לרע,\u0004 שבתוך הבולמוס כל דבר שנותנים לו הוא אוכל, ואינו מבחין. \u0003אמר אביי: ובטעמא\u0004 \u0005[ושיבחין בטעמם\u0006 של הדברים\u0005]\u0006 ולא בראיה בלבד, שאפילו כשהוא בבולמוס יודע הוא להכיר במראה, אבל אינו מבחין בהבדלי טעם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מי שאחזו בולמוס\u0004 וחייבים להאכילו עד שיאורו עיניו — \u0003מאכילין אותו הקל הקל,\u0004 שאם היו צריכים להאכילו דברים אסורים, מקדימים להאכילו מאלה שאיסורם קל יותר, כגון היו להם \u0003טבל\u0004 (תבואה שלא הופרש ממנה מעשר) ו\u0003נבילה — מאכילין אותו נבילה,\u0004 שאיסור טבל יש בו מיתה בידי שמים ונבילה בלא תעשה בלבד. \u0003טבל ושביעית\u0004 — מאכילין אותו \u0003שביעית,\u0004 שהטבל הוא במיתה בידי שמים ואילו השביעית אינה אלא במצות עשה.","\u0003טבל ותרומה — תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 מה מהם יאכל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מאכילין אותו טבל ואין מאכילין אותו תרומה. בן תימא אומר:\u0004 מוטב שיאכילוהו \u0003תרומה ולא\u0004 יאכילוהו \u0003טבל. אמר רבה: היכא\u0004 \u0005[היכן]\u0006 ש\u0003אפשר\u0004 להאכיל אותו \u0003חולין,\u0004 שיש שם טבל אבל אפשר להפריש ממנו ולתקנו, \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003לא פליגי דמתקנינן ליה ומספינן ליה\u0004 \u0005[לא חלוקים שמתקנים לו\u0006 את הטבל על ידי שמפרישים ממנו מעשרות \u0005ומאכילים אותו]\u0006 ואפילו בשבת שאסורה בה הפרשת תרומות.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 \u0003בדלא\u0004 \u0005[כשאי]\u0006 \u0003אפשר בחולין\u0004 שאין אפשרות להפריש, \u0003מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 כי איסור \u0003טבל חמור, ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 כי \u0003תרומה חמורה\u0004 יותר. וטעמם; \u0003מר סבר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 כי \u0003טבל חמור,\u0004 ומדוע? לפי שאסורים הכל לאוכלו, \u0003אבל תרומה — חזיא\u0004 \u0005[ראויה היא]\u0006 \u0003לכהן\u0004 ולכן יש לומר שאיסורה קל יותר. \u0003ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 כי \u0003תרומה חמורה\u0004 יותר, שהרי אין לה כל היתר לישראל \u0003אבל טבל — אפשר לתקוניה\u0004 \u0005[לתקנו]\u0006 ולכן אף בעודו טבל אין חומרת האיסור שבו גדולה כל כך."],["\u0003אפשר\u0004 לתקן את הטבל ולהאכילו \u0003בחולין\u0004 — מאכילים אותו. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו שאם אפשר לתקן ולעשות בהיתר יעשו כן, ולשם מה נאמר הדבר? ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא שהיה הדבר \u0003בשבת\u0004 שאז אסור להפריש תרומות ומעשרות ובכל זאת אמרו שמוטב שיפרישו תרומות ומעשרות ובלבד שלא יאכילוהו טבל.","ומקשים: \u0003בשבת נמי\u0004 \u0005[גם כן]\u0006 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 וברור הוא, שהרי האיסור להפריש תרומות ומעשרות הוא רק איסור \u0003טלטול,\u0004 שאסור \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003הוא,\u0004 וודאי חמור פחות מאיסול טבל! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 בפירות שגדלו \u0003בעציץ שאינו נקוב,\u0004 שאז אין בהם חיוב תרומה מן התורה אלא מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד, והשמיע לנו שעדיף שיעבור על איסור שמדברי סופרים ויתקנו את הפירות ובלבד שלא יאכילו את החולה בטבל, אף על פי שאף הטבל במקרה זה אינו אלא מדברי סופרים.","ושואלים: שאלה זו בטבל שמדברי סופרים וחובת הפרשת תרומה ממנו בשבת אף שגם הוא איסור שמדברי סופרים, ש\u0003מר\u0004 \u0005[חכם\u0006 זה, רבה\u0005]\u0006 \u0003סבר\u0004 כי \u0003טבל חמור\u0004 וצריך לתקן את הפירות אפילו שהפרשת תרומה אסורה \u0003ומר\u0004 \u0005[וחכם\u0006 זה, החולקים עליו\u0005]\u0006 \u0003סבר תרומה חמורה,\u0004","\u0003לימא תנאי\u0004 \u0005[האם נאמר שמחלוקת תנאים]\u0006 \u0003היא,\u0004 בשאלה זו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שנשכו נחש\u0004 והוא מסוכן — \u0003קורין לו רופא ממקום למקום\u0004 אפילו בשבת, \u0003ומקרעין לו את התרנגולת\u0004 אם זקוקין לבשרה לרפואה, \u0003וגוזזין לו\u0004 מן הקרקע \u0003את הכרישין\u0004 (מין בצל) לרפואה, \u0003ומאכילין אותו, ואין צריך לעשר דברי רבי. ר' אלעזר בר' שמעון אומר: לא יאכל עד שיעשר.\u0004","אם כן \u0003נימא\u0004 \u0005[נאמר]\u0006 שמה שאמר רבה כי יש צורך לתקן את הפירות לחולה ולהפריש מהם תרומה בשבת אפילו בטבל שמדברי סופרים, \u0003היא\u0004 שיטת \u0003ר' אלעזר בר' שמעון היא,\u0004 האומר כי יש לתקן את הכרישין לחולה אפילו בשבת, אף שהכרישין, כדין שאר ירקות, אינם נחשבים כטבל אלא מדברי סופרים, \u0003ולא רבי!\u0004","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ששיטת רבה כשיטת \u0003רבי\u0004 היא, \u0003עד כאן לא\u0004 שמענו ש\u0003אמר רבי התם\u0004 \u0005[שם]\u0006 שאין לעשר — \u0003אלא לענין מעשר ירק\u0004 (כגון כרישין) שמעיקרו הוא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ולא יבוא להחליפו בטבל שמן התורה, \u0003אבל במעשר דגן\u0004 שבדרך כלל \u0003טבל דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003הוא,\u0004 ואף על פי שבמקרה מסויים זה אינו אלא מדברי סופרים, שהרי גדל בעציץ שאינו נקוב, מכל מקום \u0003אפילו רבי מודה\u0004 שיש לתקן את הפירות, כיון \u0003דאי שרית ליה\u0004 \u0005[שאם תתיר לו]\u0006 לאכול בלא הפרשה \u0003בעציץ שאינו נקוב —\u0004 עשוי הוא לטעות ו\u0003אתי למיכל\u0004 \u0005[יבוא לאכול]\u0006 מדגן שגדל \u0003בעציץ שהוא נקוב\u0004 שטבול הוא מן התורה. ואפשר לפרש איפוא אפילו כשיטת רבי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003בברייתא: מי שאחזו בולמוס מאכילין אותו דבש וכל מיני מתיקה, שהדבש וכל מיני מתיקה מאירין מאור עיניו של אדם. ואף על פי שאין ראיה\u0004 ברורה \u0003לדבר, זכר לדבר\u0004 שאמר יהונתן: \u0003\"ראו נא כי ארו עיני כי טעמתי מעט דבש הזה\"\u0004 (שמואל א' יד, כט).","ושואלים: \u0003ומאי\u0004 \u0005[ומה\u0006 טעם\u0005]\u0006 אמר: \u0003\"\u0004ו\u0003אף על פי שאין ראיה לדבר\",\u0004 הרי לכאורה ראיה גדולה היא! ומשיבים: \u0003דהתם לאו\u0004 \u0005[ששם לא]\u0006 \u0003בולמוס אחזיה\u0004 \u0005[אחזו],\u0006 אלא היה רעב בלבד, ואין מכאן ראיה גמורה לענין בולמוס.","\u0003אמר אביי: לא שנו\u0004 שהדבש מאיר את עיני האדם, \u0003אלא לאחר אכילה, אבל קודם אכילה — מגרר גריר\u0004 \u0005[גורר,\u0006 מביא תיאבון\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וימצאו איש מצרי בשדה ויקחו אתו אל דוד ויתנו לו לחם ויאכל וישקהו מים. ויתנו לו פלח דבלה ושני צמקים ויאכל ותשב רוחו אליו כי לא אכל לחם ולא שתה מים שלשה ימים ושלשה לילות\"\u0004 (שמואל א' ל, יא-יב), משמע שמיני מתיקה ניתנים לאחר עיקר האכילה ולא לפניה.","\u0003אמר רב נחמן אמר שמואל: מי שאחזו בולמוס — מאכילין אותו אליה בדבש,\u0004 שהתערובת של הבשר השמן והדבש מועילה ביותר לכך. \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: אף סולת נקיה בדבש\u0004 מועילה לזה. \u0003רב פפא אמר: אפילו קמחי דשערי בדיבשא\u0004 \u0005[קמח שעורים בדבש]\u0006 יפה לכך. \u0003אמר ר' יוחנן: פעם אחת אחזני בולמוס ורצתי למזרחה של תאנה\u0004 ומצאתי שם תאנים בשלות ואכלתי, כי אין התאנים מבשילות כולן בבת אחת, ובצד שזורחת בו השמש תחילה שם הן מבשילות תחילה, ולכן רץ למזרחה של תאנה ששם התאנים הבשלות, \u0003וקיימתי בעצמי\u0004 את הכתוב: \u0003\"החכמה תחיה בעליה\"\u0004 (קהלת ז, יב). \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003רב יוסף: הרוצה לטעום טעם תאנה יפנה למזרחה, שנאמר: \"וממגד תבואת שמש\"\u0004 (דברים לג, יד), שהשמש מבשלת את הפירות וממתקתם.","מסופר: \u0003ר' יהודה ור' יוסי הוו קא אזלי באורחא\u0004 \u0005[היו מהלכים בדרך]\u0006 \u0003אחזיה\u0004 \u0005[אחזו]\u0006 \u0003בולמוס\u0004 את \u0003ר' יהודה, קפחיה לרועה אכליה לריפתא\u0004 \u0005[כפה רועה אחד ואכל את הלחם\u0006 שהיה בידו\u0005],\u0006 שכן מסוכן הוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוסי:\u0004 ראה, \u0003קפחת את הרועה. כי מטו למתא\u0004 \u0005[כאשר הגיעו לעיר]\u0006 \u0003אחזיה\u0004 \u0005[אחזו]\u0006 \u0003בולמוס\u0004 את \u0003ר' יוסי, אהדרוהו בלגי וצעי\u0004 \u0005[הקיפו אותו\u0006 כל בני העיר \u0005בכוסות וצלחות]\u0006 של מיני מתיקה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה\u0004 בצחוק: \u0003אני קפחתי את הרועה, ואתה קפחת את העיר כולה.\u0004","\u0003ותו\u0004 \u0005[ועוד]\u0006 מסופר: \u0003ר' מאיר ור' יהודה ור' יוסי הוו קא אזלי באורחא\u0004 \u0005[היו הולכים בדרך\u0006 יחד\u0005],\u0006 \u0003ר' מאיר הוה דייק בשמא\u0004 \u0005[היה מדייק בשמות]\u0006 ולומד משמו של אדם על טבעו, \u0003ר' יהודה ור' יוסי לא הוו דייקו בשמא\u0004 \u0005[היו מדייקים בשמות].\u0006 \u0003כי מטו לההוא דוכתא בעו אושפיזא יהבו להו\u0004 \u0005[כשבאו למקום אחד ביקשו מקום ללון ונתנו להם]\u0006 \u0003אמרו לו\u0004 לבעל האכסניה: \u0003מה שמך? אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"כידור\"\u0004 שמי. \u0003אמר\u0004 ר' מאיר בלבו: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003אדם רשע הוא, שנאמר: \"כי דור תהפכת המה\"\u0004 (דברים לב, כ). כיון שהיה זה בערב שבת, \u0003ר' יהודה ור' יוסי אשלימו ליה כיסייהו\u0004 \u0005[הפקידו בידו את כיסיהם,\u0006 שבהם מונח כספם\u0005].\u0006 \u0003ר' מאיר לא אשלים ליה כיסיה\u0004 \u0005[נתן לו את כיס\u0006 הכסף \u0005שלו],\u0006 אלא \u0003אזל אותביה בי קיבריה דאבוה\u0004 \u0005[הלך והניח אותו ליד קברו של אביו]\u0006 של בעל האכסניה.","\u0003אתחזי ליה בחלמיה\u0004 \u0005[נראה לו\u0006 אביו של בעל האכסניה \u0005בחלומו]\u0006 ואמר לו: \u0003תא שקיל כיסא דמנח ארישא דההוא גברא\u0004 \u0005[בוא וקח כיס\u0006 כסף \u0005שמונח על ראשו של אותו אדם].\u0006 \u0003למחר אמר להו\u0004 \u0005[להם\u0006 לחכמים\u0005]:\u0006 \u0003הכי אתחזי לי בחלמאי\u0004 \u0005[כן נראה לי בחלומי].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003חלמא דבי שמשי לית בהו ממשא\u0004 \u0005[חלומות של ליל שבת אין בהם ממש]\u0006 ואין לסמוך עליהם, ומכל מקום \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' מאיר ונטריה כולי יומא ואייתיה\u0004 \u0005[ושמר\u0006 את כספו \u0005כל יום\u0006 השבת \u0005והביאו].\u0006","\u0003למחר אמרו לו\u0004 חכמים לבעל הבית: \u0003הב לן כיסן\u0004 \u0005[תן לנו את כיסנו]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003לא היו דברים מעולם\u0004 ולא הפקדתם בידי דבר. \u0003אמר להו\u0004 \u0005[אמר להם]\u0006 \u0003ר' מאיר: אמאי לא דייקיתו בשמא\u0004 \u0005[מדוע לא דייקתם בשם]\u0006 ללמוד שאדם רשע הוא? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי לא אמרת לן מר\u0004 \u0005[מדוע לא אמרת לנו]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אימר דאמרי אנא חששא, אחזוקי מי אמרי\u0004 \u0005[אמור שאומר אני שיש לחשוש לכך, אולם להחזיקו\u0006 כרשע \u0005האם אמרתי]?\u0006 כלומר: וכי יכולתי לומר לכם בודאות שהוא אדם רשע?","מה עשו — \u0003משכוהו ועיילוהו לחנותא\u0004 \u0005[והכניסוהו לחנות],\u0006 \u0003חזו טלפחי אשפמיה\u0004 \u0005[ראו עדשים על שפמו]\u0006 שאכל עדשים באותו יום, \u0003אזלו ויהבו סימנא לדביתהו ושקלוהו לכיסייהו\u0004 \u0005[הלכו ונתנו סימן זה לאשתו]\u0006 שצוה שיחזירו להם את כספם בסימן שאכל עדשים בסעודתו \u0005[ולקחו את כיסיהם]\u0006 \u0003ואייתו\u0004 \u0005[ובאו].\u0006 \u0003אזל איהו וקטליה לאיתתיה\u0004 \u0005[הלך הוא והרג את אשתו]\u0006 מרוב כעס על שעשתה כן.","\u0003היינו דתניא\u0004 \u0005[זהו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מים ראשונים האכילו בשר חזיר,\u0004 שהיה פונדקי שהיה נוהג להאכיל לגויים בשר חזיר ולישראל בשר כשר, והיה מבחין בין ישראל לגוי כשהיה מתבונן אם נוטלים ידיהם לפני האוכל. פעם בא יהודי ואכל ולא נטל ידיו לפני הסעודה ונתן לו לאכול בשר חזיר, \u0003מים אחרונים\u0004 שרוחצים בהם את הידים ואת הפה לאחר האוכל גרמו ש\u0003הרגו את הנפש\u0004 כמעשה זה, שאם היה רוחץ פיו לא היו יודעים שאכל עדשים.","\u0003ולבסוף הוו דייקי בשמא\u0004 \u0005[היו\u0006 אף הם \u0005מדייקים בשם]\u0006 \u0003כי מטו לההוא ביתא דשמיה\u0004 \u0005[ששמו]\u0006 של בעל הבית היה \u0003\"בלה\", לא עיילו לגביה\u0004 \u0005[נכנסו אליו].\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכן]\u0006 כי בודאי \u0003רשע הוא. דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואמר לבלה נאופים\"\u0004 (יחזקאל כג, מג), \u0003כמו\u0004 שנאמר: \u0003\"אחרי בלתי היתה לי עדנה\"\u0004 (בראשית יח, יב) \u0003כלומר:\u0004 \"לבלה ניאופים\" — פירושו \u0003זקנה בנאופים.\u0004","שנינו \u0003מי שנשכו כלב שוטה\u0004 אין מאכילין אותו מחצר כבד שלו. ומבארים קצת עניינו של כלב שוטה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003חמשה דברים\u0004 (סימנים) \u0003נאמרו בכלב שוטה: פיו פתוח\u0004 תמיד, \u0003ורירו נוטף, ואזניו סרוחות\u0004 אינן עומדות, \u0003וזנבו מונח על ירכותיו, ומהלך בצידי דרכים. ויש אומרים: אף נובח ואין קולו נשמע.\u0004 ושאלו: \u0003ממאי הוי\u0004 \u0005[ממה נעשה]\u0006 שהכלב נעשה כלב שוטה? \u0003רב אמר: נשים כשפניות משחקות בו\u0004 ומנסות בו כישופיהן ולכן נעשה שוטה, \u0003ושמואל אמר: רוח רעה שורה עליו.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל\u0006 המעשי \u0005ביניהם]\u0006 אם זו או זו היא הסיבה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין"],["\u0003למקטליה בדבר הנזרק\u0004 \u0005[להרוג אותו בדבר הנזרק]\u0006 מרחוק בלבד, כגון חץ, שלא יהרגנו בידים, שאם רוח רעה היא יש להיזהר אף מפני הנגיעה בו.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל.\u0004 ששנינו: \u0003כשהורגין אותו\u0004 את הכלב השוטה — \u0003אין הורגין אותו אלא בדבר הנזרק.\u0004 ועוד בענין כלב שוטה: \u0003דחייף ביה\u0004 \u0005[מי שמתחכך בו]\u0006 כלב שוטה — \u0003מסתכן\u0004 במחלה, \u0003דנכית ליה\u0004 \u0005[מי\u0006 שהכלב \u0005נושך אותו] —\u0006 \u0003מיית\u0004 \u0005[מת].\u0006 ושואלים: על זה שאמרנו כי \u0003דחייף ביה\u0004 \u0005[מי שמתחכך בו]\u0006 כלב שוטה — הוא \u0003מסתכן,\u0004 שואלים: \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 לריפוי? ומשיבים: \u0003נישלח מאניה ונירהיט\u0004 \u0005[שיפשוט את בגדיו וירוץ].\u0006 מסופר: \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע חף ביה חד מינייהו בשוקא\u0004 \u0005[התחכך בו אחד מאלה\u0006 הכלבים השוטים \u0005בשוק],\u0006 \u0003שלחינהו למאניה ורהיט\u0004 \u0005[פשט את בגדיו ורץ].\u0006 \u0003אמר: קיימתי בעצמי \"החכמה תחיה בעליה\"\u0004 (קהלת ז, יב).","על שאמרנו \u0003דנכית ליה\u0004 \u0005[מי שנושך אותו]\u0006 הכלב \u0003— מיית\u0004 \u0005[מת],\u0006 שואלים: \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 \u0003אמר אביי: ניתי משכא דאפא דדיכרא\u0004 \u0005[שיביא עור של צבוע זכר]\u0006 \u0003וניכתוב עליה\u0004 \u0005[ושיכתוב עליו]:\u0006 \u0003אנא פלניא בר פלניתא אמשכא דאפא דיכרא כתיבנא עלך\u0004 \u0005[אני פלוני בן פלונית על עור של צבוע זכר כותב אני עליך]\u0006 לחש זה: \u0003\"כנתי כנתי קלירוס\". ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שצריך לכתוב: \u0003\"קנדי קנדי קלורוס\",\u0004 וכותב את השם \u0003י-ה י-ה ה' צבאות אמן אמן סלה. ונשלחינהו למאניה ולקברינהו בי קברי עד תריסר ירחי שתא\u0004 \u0005[ושיפשוט את בגדיו ויקבור אותם בבית הקברות עד\u0006 תום \u0005שנים עשר חדשי השנה]\u0006 \u0003ונפקינהו ונקלינהו בתנורא\u0004 \u0005[ושיוציאם\u0006 אחר כך \u0005וישרפם בתנור]\u0006 \u0003ונבדרינהו לקטמיה\u0004 \u0005[ושיפזר את אפרו]\u0006 על \u0003פרשת דרכים והנך תריסר ירחי שתא\u0004 \u0005[ואותם שנים עשר חדשי השנה]\u0006 בהם קבורים בגדיו, \u0003כי שתי מיא\u0004 \u0005[כאשר הוא שותה מים]\u0006 \u0003— לא לישתי\u0004 \u0005[ישתה]\u0006 \u0003אלא בגובתא דנחשא\u0004 \u0005[בקנה של נחושת]\u0006 ולא מן המעין, \u0003דילמא חזי בבואה דשידא וליסתכן\u0004 \u0005[כדי שלא יראה את דמותו של השד\u0006 במים \u0005ויסתכן],\u0006 \u0003כי הא\u0004 \u0005[כמו זה]\u0006 המעשה של \u0003אבא בר מרתא\u0004 ש\u0003הוא\u0004 המכונה גם \u0003אבא בר מניומי, עבדא ליה אימיה גובתא דדהבא\u0004 \u0005[עשתה לו אמו קנה של זהב]\u0006 לצורך זה.","\u0003ועוד אמר ר' מתיא\u0004 בן חרש שהחושש בגרונו נותנים לו סם אפילו בשבת. מסופר: \u0003ר' יוחנן חש\u0004 \u0005[היה סובל]\u0006 ממחלת \u0003צפידנא\u0004 שהיא מחלה הפוגעת בתחילה בשיניים ובחניכיים ולבסוף בבני המעים\u0003. אזל גבה דההיא מטרוניתא\u0004 \u0005[הלך לגברת\u0006 גויה \u0005אחת]\u0006 שהיתה מפורסמת כרופאה, \u0003עבדא ליה מלתא\u0004 \u0005[עשתה לו דבר\u0006 רפואה\u0005]\u0006 \u0003חמשא\u0004 \u0005[ביום חמישי]\u0006 \u0003ומעלי שבתא\u0004 \u0005[ובערב שבת].\u0006 \u0003אמר לה: בשבת מאי\u0004 \u0005[מה\u0006 אעשה\u0005]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]\u0006 \u0003לא צריכת\u0004 \u0005[אין אתה צריך]\u0006 לכך. שאל אותה: \u0003אי מצטריכנא מאי\u0004 \u0005[אם אצטרך\u0006 לכך \u0005מה]\u0006 אעשה? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אישתבע לי דלא מגלית\u0004 \u0005[השבע לי שאין אתה מגלה]\u0006 מה היא התרופה, ואז אומר לך ותוכל לעשות בעצמך אם תזדקק לכך, \u0003אישתבע\u0004 \u0005[נשבע]:\u0006 \u0003לאלהא דישראל לא מגלינא\u0004 \u0005[לאלהי ישראל אין אני מגלה].\u0006 \u0003נפק\u0004 \u0005[יצא]\u0006 ר' יוחנן \u0003דרשה בפירקא\u0004 \u0005[דרש בדרשה פומבית]\u0006 וגילה את סוד התרופה הזו.","ותוהים: \u0003והא אישתבע לה\u0004 \u0005[והרי נשבע לה]!\u0006 ומשיבים: הוא ניסח את השבועה כך: \u0003לאלהא דישראל לא מגלינא\u0004 \u0005[לאלהי ישראל אין אני מגלה]\u0006 ומכאן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לעמו ישראל מגלינא\u0004 \u0005[מגלה אני].\u0006 ומקשים: מכל מקום, \u0003והא איכא\u0004 \u0005[והרי יש בכך]\u0006 משום \u0003חלול השם\u0004 שהיא סבורה שאדם גדול כר' יוחנן הפר את שבועתו! ומשיבים: \u0003דמגלי לה מעיקרא\u0004 \u0005[שהוא גילה לה מתחילה],\u0006 שמיד לאחר שנשבע אמר לה ששבועה זו אינה מונעת ממנו מלפרסם ברבים.","ושואלים: \u0003מאי עבדא ליה\u0004 \u0005[מה\u0006 הרפואה \u0005שעשתה לו]?\u0006 \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי: מי שאור\u0004 (מים ששרו בהם שאור) \u0003שמן זית, ומלח. רב יימר אמר: שאור גופיה\u0004 \u0005[עצמו],\u0006 \u0003שמן זית, ומלח. רב אשי אמר:\u0004 תרופה זו היתה \u0003משחא דגדפא דאווזא\u0004 \u0005[שומן\u0006 המיוצר ממוח עצם \u0005הכנף של האווז].\u0006 \u0003אמר אביי: אנא עבדי לכולהו\u0004 \u0005[אני עשיתי את\u0006 התרופות הללו \u0005כולן]\u0006 \u0003ולא איתסאי\u0004 \u0005[התרפאתי\u0006 ממחלה זו\u0005],\u0006 \u0003עד\u0004 ש\u0003אמר לי ההוא טייעא\u0004 \u0005[ערבי אחד]\u0006 מה התרופה לכך: \u0003אייתי קשייתא דזיתא דלא מלו תילתא\u0004 \u0005[קח גרעיני זיתים שלא הגיעו לשליש\u0006 בישולם\u0005]\u0006 \u0003וקלינהו בנורא אמרא חדתא\u0004 \u0005[ושרוף אותם באש על מעדר חדש]\u0006 \u0003ואדביק בככי דריה\u0004 \u0005[והדבק אותם בשורת החניכיים].\u0006 \u0003עבדי הכי ואיתסאי\u0004 \u0005[עשיתי כן והתרפאתי].\u0006","ושואלים: \u0003ממאי הוה\u0004 \u0005[ממה נעשית]\u0006 מחלת הצפידנא? \u0003מחמימי חמימי דחיטי, ומשיורי כסא דהרסנא\u0004 \u0005[\u0006מאכילת \u0005פת חמה מדי של חיטים, ומשיירי דגים מטוגנים בשמן].\u0006 \u0003ומאי סימניה\u0004 \u0005[ומה סימנו]\u0006 של חולי זה — \u0003כד רמי מידי בככיה ואתא דמא מבי דרי\u0004 \u0005[כאשר הוא מכניס משהו בין שיניו ויוצא דם מן החניכיים].\u0006 \u0003ר' יוחנן כי חש\u0004 \u0005[כאשר היה סובל]\u0006 ממחלת ה\u0003צפידנא, עבד הכי בשבתא ואיתסי\u0004 \u0005[עשה כך\u0006 רפואה זו \u0005בשבת והתרפא].\u0006 ושואלים: \u0003ור' יוחנן היכי עביד הכי\u0004 \u0005[כיצד עשה כך]\u0006 להתרפא בשבת בדבר שהוא מחלת השיניים בלבד? \u0003אמר רב נחמן בר יצחק: שאני\u0004 \u0005[שונה]\u0006 \u0003צפידנא הואיל ומתחיל\u0004 חולי זה אכן \u0003בפה\u0004 והוא נראה כמחלת שיניים, אולם בסופו של דבר הריהו \u0003גומר בבני מעיים\u0004 והוא מסוכן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא לר' יוחנן: כמאן\u0004 \u0005[כשיטת מי]\u0006 עשה זאת — כשיטת \u0003ר' מתיא בן חרש,\u0004 ש\u0003אמר: החושש בפיו — מטילין לו\u0004 לתוך פיו \u0003סם\u0004 רפואה \u0003בשבת. אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: כן הוא, אלא \u0003שאני אומר בזו\u0004 האחרונה בלבד, בהטלת סם בפיו בשבת מודים לו חכמים, \u0003ולא באחרת.\u0004 ואם כן לגבי סם בשבת מסכימים חכמים לדעת ר' מתיא בן חרש.","\u0003לימא מסייע ליה\u0004 \u0005[האם נאמר שמסייעת לו]\u0006 ברייתא זו: \u0003מי שאחזו ירקון — מאכילין אותו בשר חמור\u0004 לרפואה, \u0003מי שנשכו כלב שוטה — מאכילין אותו מחצר כבד שלו, והחושש בפיו — מטילין לו סם בשבת, דברי ר' מתיא בן חרש. וחכמים אומרים: באילו אין בהם משום רפואה.\u0004 ונדייק מן הלשון \u0003\"באלו\" למעוטי מאי\u0004 \u0005[למעט מה]?\u0006 \u0003מאי לאו למעוטי\u0004 \u0005[האם לא הכוונה למעט]\u0006 ענין זה של \u0003סם\u0004 שחכמים מודים שמותר בשבת?","ודוחים: \u0003לא, למעוטי\u0004 \u0005[למעט]\u0006 רפואה אחרת שאמר ר' מתיא: \u0003מקיזין\u0004 [הקזת] \u0003דם\u0004 לריפוי מחלת ה\u0003סרונכי,\u0004 שמותר לעשות כן בשבת. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003שלשה דברים אמר ר' ישמעאל בר' יוסי ששמע משום\u0004 (משם) \u0003ר' מתיא בן חרש: מקיזין דם לסרונכי בשבת, ומי שנשכו כלב שוטה מאכילין אותו מחצר כבד שלו, והחושש בפיו מטילין לו סם בשבת.\u0004","\u0003וחכמים אומרים: באילו אין בהן משום רפואה. \"באילו\" למעוטי מאי\u0004 \u0005[למעט את מה]?\u0006 \u0003מאי לאו אתרתי בתרייתא\u0004 \u0005[האם לא\u0006 היתה הכונה \u0005על שני דברים האחרונים]\u0006 שאין בהם משום רפואה \u0003ולמעוטי דרישא\u0004 \u0005[ולמעט את הראשונה]\u0006 הקזה לסרונכי שהיא רפואה לדעת הכל! ודוחים: \u0003לא,\u0004 אין מכאן ראיה, כי אפשר לומר: \u0003אתרתי דרישא קמייתא\u0004 \u0005[על שתי הראשונות של\u0006 הברייתא \u0005הראשונה],\u0006 \u0003ולמעוטי דסיפא\u0004 \u0005[ולמעט\u0006 מה שאמר \u0005באחרונה]\u0006 לגבי סם בשבת, שבזו הודו לו."],["\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה לדבר, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רבה בר שמואל\u0004 ברייתא זו: \u0003עוברה\u0004 (אשה הרה) \u0003שהריחה\u0004 ונתאוותה למאכל — \u0003מאכילין אותה עד שתשוב נפשה\u0004 אפילו ביום הכיפורים. \u0003ומי שנשכו כלב שוטה — מאכילין אותו מחצר כבד שלו, והחושש בפיו — מטילין לו סם בשבת, דברי ר' אלעזר בר' יוסי, שאמר משום ר' מתיא בן חרש. וחכמים אומרים: בזו ולא באחרת.\u0004 ונברר: \u0003\"בזו\" אהייא\u0004 \u0005[על איזו]\u0006 התכוונו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003אעוברה\u0004 \u0005[\u0006לענין \u0005מעוברת]\u0006 אמרו \"בזו\", \u0003פשיטא\u0004 \u0005[פשוט\u0006 ומובן מאליו\u0005]!\u0006 \u0003עוברה מי איכא למאן דאמר דלא\u0004 \u0005[מעוברת האם יש מי שאומר שלא\u0006 יתנו לה\u0005]?\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003אסם\u0004 \u0005[על\u0006 דין \u0005הסם]\u0006 בשבת שבזו הודו לו שמותר לעשות כן בשבת. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבכך לא נחלקו חכמים.","\u0003רב אשי אמר: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כך מדוקדקת\u0006 כשיטה זו\u0005]\u0006 ששנינו במשנה: \u0003ועוד אמר ר' מתיא בן חרש: החושש בפיו מטילין לו סם בשבת, ולא פליגי רבנן עליה\u0004 \u0005[נחלקו חכמים עליו]\u0006 לומר שאינו כן. \u0003ואם איתא\u0004 \u0005[ואם יש]\u0006 מקום לומר \u0003דפליגי רבנן עליה\u0004 \u0005[שחלוקים חכמים עליו]\u0006 \u0003ליערבינהו וליתנינהו, וליפלגו רבנן בסיפא\u0004 \u0005[שיערבו\u0006 את שתי ההלכות יחד \u0005וישנו אותן ביחד, ושיחלקו חכמים בסוף\u0006 על הכל\u0005],\u0006 וכיון שלא נאמר כך אלא מחלוקת חכמים נאמרה לאחר דעתו של ר' מתיא בכלב שוטה, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבהלכה זו של סם לא נחלקו עליו חכמים.","נאמר במשנה שהחושש בגרונו מטילין סם לתוך פיו בשבת, \u0003מפני שספק נפשות הוא.\u0004 ושואלים: \u0003למה ליה\u0004 \u0005[לו]\u0006 \u0003תו למימר\u0004 \u0005[עוד\u0006 להוסיף \u0005ולומר]:\u0006 \u0003\"וכל ספק נפשות דוחה את השבת\"? אמר רב יהודה אמר רב:\u0004 הכוונה היא \u0003לא ספק שבת זו בלבד אמרו\u0004 שמותר, \u0003אלא אפילו ספק שבת אחרת\u0004 גם כן.","\u0003היכי דמי\u0004 \u0005[כיצד הוא]\u0006 הענין של ספק שבת אחרת? \u0003כגון דאמדוה לתמניא יומי\u0004 \u0005[כגון\u0006 שהרופאים \u0005שיערו\u0006 שצריך \u0005שמונה ימים\u0006 להתרפא בהם\u0005]\u0006 \u0003ויומא קמא שבתא\u0004 \u0005[ויום ראשון\u0006 של מחלתו, \u0005שבת\u0006 הוא\u0005]\u0006 \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]:\u0006 \u0003ליעכב עד לאורתא\u0004 \u0005[שיחכה עד הערב]\u0006 למוצאי שבת ויתחיל אז בריפוי \u0003כי היכי דלא ניחול עליה תרי שבתא\u0004 \u0005[כדי שלא יצטרכו לחלל עליו שתי שבתות],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמחללים עליו מיד את השבת, אף שכתוצאה מכך יצטרך לחלל שבת נוספת, כיון שספק נפשות הוא.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מחמין חמין לחולה בשבת, בין להשקותו\u0004 בחמין אלה \u0003בין להברותו\u0004 לרחצו בהם, שמא יועיל להבריאו, \u0003ולא שבת זו בלבד אמרו\u0004 שמחללים לשם כך אלא אף \u0003לשבת אחרת. ואין אומרים: נמתין לו\u0004 ונעכב עשיית מלאכה זו עד למוצאי שבת \u0003שמא יבריא\u0004 בינתיים, \u0003אלא מחמין לו מיד מפני שספק נפשות דוחה את השבת ולא ספק שבת זו\u0004 בלבד \u0003אלא אפילו ספק שבת אחרת.\u0004","\u0003ואין עושין דברים הללו לא על ידי גוים ולא על ידי כותיים\u0004 (שומרונים) \u0003אלא על ידי גדולי ישראל\u0004 שהם משתדלים בו ויודעים לנהוג כראוי. \u0003ואין אומרין יעשו דברים הללו לא על פי נשים ולא על פי כותיים,\u0004 שאין הם נחשבים מומחים דיים כדי לומר שאדם מסויים חולה עד כדי שצריכים לחלל שבת עבורו, \u0003אבל מצטרפין\u0004 אלו \u0003לדעת אחרת,\u0004 שאם יש חילוקי דעות אפשר לצרף גם את דעותיהם של אלה כדי להכריע.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003בברייתא: מפקחין פקוח נפש בשבת, והזריז\u0004 בדבר זה \u0003הרי זה משובח, ואין צריך ליטול רשות מבית דין\u0004 אלא ימהר ויעשה מעצמו. \u0003הא כיצד? ראה תינוק שנפל לים פורש מצודה\u0004 (רשת דייגים) \u0003ומעלהו\u0004 מן הים \u0003והזריז הרי זה משובח ואין צריך ליטול רשות מבית דין.\u0004 ומעירים: ומדוע הוסיפו זאת — \u0003ואף על גב דקא צייד כוורי\u0004 \u0005[ואף על פי\u0006 שדרך אגב \u0005הוא צד דגים\u0006 ברשת זו\u0005].\u0006 וכן, \u0003ראה תינוק שנפל לבור\u0004 ואינו יכול לצאת משם — \u0003עוקר חוליא\u0004 מקצה הבור ועושה לו כעין מדרגה \u0003ומעלהו, והזריז הרי זה משובח, ואין צריך ליטול רשות מבית דין.\u0004 ומעירים: \u0003ואף על גב דמתקן דרגא\u0004 \u0005[ואף על פי ש\u0006על ידי כך \u0005הוא מתקן מדרגה].\u0006","וכן: \u0003ראה שננעלה דלת בפני תינוק,\u0004 והתינוק מתיירא ובוכה — \u0003שוברה ומוציאו, והזריז הרי זה משובח ואין צריך ליטול רשות מבית דין.\u0004 ומעירים: \u0003ואף על גב דקא מיכוין למיתבר בשיפי\u0004 \u0005[ואף על פי שהוא מתכוון לשבור\u0006 את הדלת \u0005לנסרים],\u0006 שישתמש בהם למלאכה. וכן: \u0003מכבין ומפסיקין\u0004 (יוצרים חייץ על ידי כלי מתכת או כלי חרס המלאים במים) \u0003מפני הדליקה\u0004 שיש בה משום פיקוח נפש \u0003בשבת, והזריז הרי זה משובח, ואין צריך ליטול רשות מבית דין\u0004 ומעירים: \u0003ואף על גב דקא ממכיך מכוכי\u0004 \u0005[ואף על פי שהוא מניח או מציע את הגחלים]\u0006 שיוכל להשתמש בהם במוצאי שבת לצלות בהם.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 היה להשמיענו את כל הדוגמאות הללו, משום שיש בכל אחת מהם חידוש. \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 את דין התינוק שנפל ל\u0003ים,\u0004 היינו אומרים: בים דווקא הוא שצריך להזדרז \u0003משום דאדהכי והכי אזל ליה\u0004 \u0005[שבין כך וכך הולך לו]\u0006 התינוק עם הגלים ונעלם, ולכן אינו צריך לשאול רשות. \u0003אבל\u0004 בתינוק שנפל ל\u0003בור, דקא יתיב\u0004 \u0005[שהוא,\u0006 התינוק \u0005יושב\u0006 שם\u0005]\u0006 ואינו יכול להסתכן יותר \u0005—\u0006 \u0003אימא לא\u0004 \u0005[אמור שלא\u0006 יזדרז\u0005]\u0006 אלא יבקש רשות — על כן \u0003צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005].\u0006","\u0003ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 \u0003בור\u0004 היינו אומרים — \u0003משום דקא מיבעית\u0004 \u0005[משום\u0006 שהתינוק \u0005מפחד]\u0006 ממה שאינו יכול לצאת, \u0003אבל ננעלה דלת\u0004 בפני התינוק \u0003אפשר דיתיב בהאי גיסא ומשביש ליה באמגוזי\u0004 \u0005[שישב בצד השני\u0006 של הדלת \u0005וישעשע אותו\u0006 את התינוק \u0005באגוזים]\u0006 עד שתעבור השבת. על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 להשמיע לנו זאת לומר שאין מתעכבים ועושים מיד מפני ספק פיקוח נפש.","שנינו בברייתא ש\u0003מכבין ומפסיקין\u0004 מפני הדליקה בשבת. ושואלים: \u0003למה לי,\u0004 כלומר: מה החידוש שיש בדבר שהרי אף זו דוגמא של ספק פיקוח נפש, ומה חידש לנו בה? ומשיבים: ש\u0003אפילו לחצר אחרת,\u0004 כלומר: לא רק להציל נפשות בחצר שבה הדלקה, אלא גם אם יש חשש שהאנשים בחצר אחרת הם שיסתכנו, מותר לכבות שלא תגיע לשם הדליקה.","\u0003אמר רב יוסף אמר רב יהודה אמר שמואל: לא הלכו בפקוח נפש אחר הרוב,\u0004 כמו שהולכים בהלכות אחרות. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 ענין \u0005זה]\u0006 כלומר, מה הוא המצב בו דנים? \u0003אי נימא דאיכא\u0004 \u0005[שיש]\u0006 \u0003תשעה ישראל וגוי אחד בינייהו\u0004 \u0005[ביניהם]\u0006 ונפלה מפולת על אחד מהם הרי במקרה זה \u0003רובא\u0004 \u0005[רוב]\u0006 \u0003ישראל נינהו\u0004 \u0005[הם],\u0006 אלא \u0003אי נמי פלגא ופלגא\u0004 \u0005[או גם כן\u0006 שהיו שם \u0005מחצה ומחצה]\u0006 ישראל וגוים, מכל מקום הרי \u0003ספק נפשות להקל,\u0004 שאף בספק שקול צריכים להקל.","\u0003אלא\u0004 הכוונה כך: \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003תשעה גוים וישראל אחד.\u0004 אולם \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט]\u0006 שמצילים, ומדוע — \u0003דהוה ליה קבוע\u0004 \u0005[שהרי\u0006 הישראל הנמצא שם \u0005הוא קבוע\u0006 במקומו\u0005]\u0006 ולפי הכלל: \u0003כל קבוע — כמחצה על מחצה דמי\u0004 \u0005[נחשב]\u0006 ולכן אף שרוב גוים הם, כיון שהישראל דר וקבוע שם, הרי הוא נחשב לענין ספק כמחצה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה שלא נשארו בחצרם אלא \u0003דפרוש\u0004 \u0005[פרשו]\u0006 \u0003לחצר אחרת, מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 ותנהג על פי הכלל: \u0003כל דפריש\u0004 \u0005[הפורש] —\u0006 \u0003מרובא פריש\u0004 \u0005[מן הרוב הוא פורש],\u0006 וכיון שרוב גוים היה שם, מן הסתם היחיד שפרש מהם גוי הוא, ואין צורך לפקח את הגל בשבת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא הלכו בפקוח נפש אחר הרוב.\u0004","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא?!]\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אסי אמר ר' יוחנן:\u0004 היו \u0003תשעה גוים וישראל אחד\u0004 ונפלה מפולת על אחד מהם אם היה זה \u0003באותה חצר — מפקחין, בחצר אחרת — אין מפקחין!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]\u0006 ואין סתירה בין ההלכות; \u0003הא — דפרוש כולהו\u0004 \u0005[כאן\u0006 שאין חוששין לרוב מדובר \u0005שפרשו כולם]\u0006 לחצר האחרת, וכגון שברור שבין היוצאים היה ודאי ישראל, נשאר עליהם דין קבוע. \u0003הא דפרוש מקצתייהו\u0004 \u0005[כאן שפרשו מקצתם]\u0006 ואין ידוע אם הישראל פרש עמהם.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך],\u0006 שאין הולכים בפיקוח נפש אחר הרוב? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אם \u0003מצא\u0004 בעיר \u0003תינוק מושלך\u0004 ואין יודעים מי הוריו, \u0003אם רוב גוים בעיר\u0004 — הרי התינוק נחשב \u0003לגוי, ואם רוב ישראל — ישראל, מחצה על מחצה\u0004 — הרי הוא כ\u0003ישראל. ואמר רב: לא שנו\u0004 ענין זה שאומרים שדינו כישראל \u0003אלא\u0004 לענין \u0003להחיותו,\u0004 שצריך לדאוג לפרנסתו ולחייו, \u0003אבל ליחסו לא\u0004 שאין אנו אומרים על סמך הרוב שהוא ודאי יהודי, ולכן, לענין דיני נישואין הרי הוא נשאר ספק (ודינו כגר)."],["\u0003ושמואל אמר\u0004 נאמר דין זה לענין \u0003לפקח עליו את הגל.\u0004 משמע שאם היו רוב גוים בעיר אין מפקחין עליו את הגל, הרי שהולכים בנפשות אחר הרוב! ומשיבים: \u0003כי איתמר\u0004 \u0005[כאשר נאמר]\u0006 דבר זה של \u0003שמואל — ארישא איתמר\u0004 \u0005[על\u0006 ההלכה \u0005הראשונה נאמר].\u0006 וכך יש להבין: \u0003אם רוב גוים — גוי, אמר שמואל: ולענין פקוח נפש אינו כן\u0004 אלא מצילים אותו מפני הספק.","שנינו ש\u0003אם\u0004 היו \u0003רוב גוים\u0004 בעיר — הרי הוא גוי. ושואלים: \u0003למאי הילכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמרו דברים אלו? \u0003אמר רב פפא:\u0004 לענין \u0003להאכילו נבילות.\u0004 כלומר: שאין אנו צריכים לחשוש באותו ילד לכל איסור שהוא ומותר להאכילו אפילו נבילות כגוי. שנינו: \u0003אם רוב ישראל — ישראל\u0004 הוא, ושואלים: \u0003למאי הילכתא\u0004 \u0005[לאיזו הלכה]?\u0006 ומשיבים: \u0003להחזיר לו אבידתו\u0004 שאיבד, שאנו אומרים שודאי ישראל הוא, ומחייבים אפילו יהודי אחר להחזיר לו אבידתו.","שנינו עוד כי \u0003מחצה על מחצה — ישראל,\u0004 ושואלים: \u0003למאי הילכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמר דבר זה? \u0003אמר ריש לקיש:\u0004 לענין הלכות \u0003נזקין.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי נימא דנגחיה תורא דידן לתורא דידיה\u0004 \u0005[אם תאמר שנגח שור שלנו\u0006 של ישראל ודאי \u0005לשור שלו],\u0006 יש לתמוה: כיצד יכול הוא לתבוע נזיקין כישראל? \u0003נייתי ראיה ונשקול\u0004 \u0005[שיביא ראיה ויקח]\u0006 דמי הנזק, שהרי המוציא מחבירו עליו הראיה! וכיון שאין לו ראיה — שוב אינו יכול לתבוע.","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דנגחיה תורא דידיה לתורא דידן\u0004 \u0005[שנגח שור שלו שור שלנו],\u0006 של ישראל ודאי, שאז \u0003פלגא יהיב ליה\u0004 \u0005[חצי הוא נותן לו],\u0006 שהרי גם אם ישראל הוא צריך לתת, \u0003אידך פלגא\u0004 \u0005[חצי השני]\u0006 שגוי נותן לישראל אם הזיק שורו שור מישראל — אינו נותן, \u0003נימא ליה\u0004 \u0005[שיאמר לו]\u0006 לניזוק: \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה דלאו\u0004 \u0005[שאין]\u0006 \u0003ישראל אנא\u0004 \u0005[אני]\u0006 \u0003ושקול\u0004 \u0005[וקח],\u0006 ובכגון זה חובת הראיה מוטלת על הניזק.","שנינו במשנה כי \u0003מי שנפל עליו מפולת\u0004 וספק אם הוא שם או שאינו שם וכן ספק אם הוא חי או מת וספק אף אם הוא גוי או ישראל — מפקחין עליו את הגל. ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 במשנה? ומדוע הביא שלוש דוגמאות שונות להסביר אותו רעיון שיש לחלל את השבת כדי להצילו אף בשעת הספק?","ומסבירים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר]\u0006 וצריך להבין כאילו היתה שנויה כך: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 שהיה רק \u0003ספק\u0004 אם \u0003הוא שם ספק אינו שם, דאי איתיה\u0004 \u0005[שאם ישנו]\u0006 שם והוא \u0003חי — הוא שמפקחין\u0004 את הגל, \u0003אלא אפילו ספק חי ספק מת — מפקחין. ולא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003ספק חי ספק מת,\u0004 כשברור ש\u0003ישראל\u0004 הוא — מפקחין, \u0003אלא אפילו ספק גוי ספק ישראל\u0004 — גם אז \u0003מפקחין.\u0004","שנינו במשנה שאם \u0003מצאוהו חי מפקחין.\u0004 ותוהים: \u0003מצאוהו חי פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו, שהרי הוא הוא דין פיקוח נפש! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 שמותר לחלל עליו את השבת אם יחיה כתוצאה מכך לאורך ימים ושנים, אלא \u0003אפילו\u0004 אם הדבר ברור שלא יחיה לאחר מכן אלא \u0003חיי שעה\u0004 בלבד וימות בקרוב — גם אז מחללים עליו את השבת.","שנינו במשנה ש\u0003אם\u0004 לאחר שהחלו לפקח את הגל מצאוהו כשהוא \u0003מת — יניחוהו.\u0004 ותוהים: \u0003הא נמי פשיטא\u0004 \u0005[\u0006הלכה \u0005זו גם כן פשוטה],\u0006 ומה טעם לחלל את השבת עבור המת? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לדעת \u0003ר' יהודה בן לקיש. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מצילין את המת מפני הדליקה\u0004 שאין עוברים על איסורי שבת מפני כבוד מת, \u0003אמר ר' יהודה בן לקיש: שמעתי שמצילין את המת מפני הדליקה.\u0004 ומעירים: \u0003אפילו ר' יהודה בן לקיש לא קאמר\u0004 \u0005[אמר]\u0006 \u0003אלא\u0004 בדליקה, \u0003מתוך שאדם בהול על מתו\u0004 וחושש שמא ישרף מתו בדליקה \u0003אי לא שרית ליה\u0004 \u0005[אם לא תתיר לו]\u0006 להוציאו \u0005—\u0006 \u0003אתי לכבויי\u0004 \u0005[יבוא לכבות]\u0006 ויעבור על איסור תורה חמור. \u0003אבל הכא, אי לא שרית ליה\u0004 \u0005[כאן אם לא תתיר לו]\u0006 לפנות את הגל \u0003— מאי אית ליה למעבד\u0004 \u0005[מה יש לו לעשות]?\u0006 ואין כאן מקום לחשש כלשהו, ואין כבוד הבריות דוחה שבת לענין זה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אדם שהיה קבור מתחת למפולת ונראה כמת, כשמפנים מפולת זו מעליו \u0003עד היכן הוא בודק\u0004 לברר אם בכל זאת עדיין חי הוא? אמרו: \u0003עד חוטמו,\u0004 ואם אין סימן חיים בחוטמו, שאינו נושם — ודאי מת הוא. \u0003ויש אומרים: עד לבו,\u0004 אם ליבו דופק. היו קבורים תחת מפולת זו כמה אנשים ו\u0003בדק ומצא\u0004 את ה\u0003עליונים\u0004 בתוך המפולת כשהם \u0003מתים, לא יאמר:\u0004 ודאי \u0003כבר מתו\u0004 גם \u0003התחתונים\u0004 ואין לחפש עוד. ו\u0003מעשה היה ומצאו עליונים מתים ותחתונים חיים.\u0004","ומעירים: \u0003נימא הני תנאי כי הני תנאי\u0004 \u0005[נאמר שתנאים אלו\u0006 שנחלקו לענין בדיקת החיים כמחלוקת \u0005תנאים אלה]\u0006 שנחלקו בענין יצירת הוולד ששנויה ברייתא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא]: \u0003מהיכן הולד נוצר — מראשו, שנאמר: \"ממעי אמי אתה גוזי\"\u0004 (תהלים עא, ו), \u0003ואומר: \"גזי נזרך והשליכי\"\u0004 (ירמיה ז, כט), לרמז שמן הראש, מקום הנזר, הוא נוצר. \u0003אבא שאול אומר: מטיבורו\u0004 אדם נוצר, \u0003ומשלח שרשיו אילך ואילך\u0004 עד שמגיע לדמות אדם. לכאורה האומר שרוח החיים קובעים לפי בדיקת חוטמו הוא התנא הסובר כי תחילת יצירת הוולד מראשו.","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003אבא שאול, עד כאן לא קא אמר אבא שאול התם\u0004 \u0005[שם]\u0006 \u0003אלא לענין יצירה, דכל מידי ממציעתיה מיתצר\u0004 \u0005[שכל דבר מאמצעיתו הוא נוצר],\u0006 \u0003אבל לענין פקוח נפש — אפילו אבא שאול מודי\u0004 \u0005[מודה]\u0006 \u0003דעקר חיותא באפיה\u0004 \u0005[שעיקר החיים באפו]\u0006 \u0003הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל אשר נשמת רוח חיים באפיו\"\u0004 (בראשית ז, כב).","\u0003אמר רב פפא: מחלוקת ממטה למעלה,\u0004 כלומר: שמצאו רגליו תחילה, שאין די לבדוק עד לבו אלא שצריך לבדוק עד חוטמו, \u0003אבל ממעלה למטה, כיון דבדק ליה\u0004 \u0005[שבדק לו]\u0006 \u0003עד חוטמו — שוב אינו צריך, דכתיב \"כל אשר נשמת רוח חיים באפיו\"\u0004 (בראשית ז, כב).","מסופר: \u0003וכבר היה ר' ישמעאל ור' עקיבא ור' אלעזר בן עזריה מהלכין בדרך ולוי הסדר ור' ישמעאל בנו של ר' אלעזר בן עזריה מהלכין אחריהן\u0004 שהיו צעירים מהם והיו נוהגים כדרך תלמידים שאין הולכים בשורה אחת עם רבותיהם. \u0003נשאלה שאלה זו בפניהם: מניין לפקוח נפש שדוחה את השבת?\u0004","\u0003נענה ר' ישמעאל ואמר:\u0004 נאמר: \u0003\"אם במחתרת ימצא הגנב\u0004 והוכה ומת אין לו דמים\u0003\"\u0004 (שמות כב, א) \u0003ומה זה\u0004 הגנב \u0003שספק על ממון בא ספק על נפשות בא,\u0004 ויודעים אנו כי \u0003שפיכות דמים מטמא את הארץ\u0004 שנאמר בהורג נפש: \"ולא תטמא את הארץ\" (במדבר לה, לד) \u0003וגורם\u0004 בכך \u0003לשכינה שתסתלק מישראל,\u0004 שהוסיף שם הכתוב ואמר: \"אשר אני שוכן בתוכה כי אני ה' שוכן בתוך ישראל\", משמע, שההורג נפש גורם לסילוק השכינה מישראל, ובכל זאת \u0003ניתן להצילו בנפשו,\u0004 שמותר לבעל הבית לשפוך את דמו כדי להנצל מן הסכנה, \u0003קל וחומר לפקוח נפש שדוחה את השבת.\u0004","\u0003נענה ר' עקיבא ואמר:\u0004 נאמר: \u0003\"וכי יזד איש על רעהו\u0004 להרגו בערמה \u0003מעם מזבחי תקחנו למות\"\u0004 (שמות כא, יד). ונדייק: \u0003מעם מזבחי\u0004 שאם הוא כהן ובא לעבוד במזבח — אין ממתינים לו וממיתים אותו, \u0003ולא מעל מזבחי,\u0004 שאם כבר החל בעבודה והוא עובד בשעה זו ממש — אין מורידים אותו מעל המזבח, אלא משלים עבודתו. \u0003ואמר רבה בר בר חנה אמר ר' יוחנן: לא שנו\u0004 שאין מורידים כהן מעל המזבח, \u0003אלא\u0004 כדי \u0003להמית\u0004 אותו כעונש על רציחה,"],["\u0003אבל להחיות\u0004 כגון אם הוא יודע ללמד זכות לאדם שנידון בבית דין למיתה, \u0003אפילו מעל מזבחי\u0004 לוקחים אותו להעיד או לדון. \u0003ומה זה, שספק יש ממש בדבריו ספק אין ממש בדבריו\u0004 מבטלים בגלל זה את עבודת המזבח \u0003ועבודה דוחה שבת, קל וחומר\u0004 לודאי \u0003פקוח נפש, שדוחה את השבת. נענה ר' אלעזר\u0004 בן עזריה \u0003ואמר: ומה\u0004 מצות \u0003מילה שהיא\u0004 תיקון רק ל\u0003אחד ממאתים וארבעים ושמונה איברים שבאדם — דוחה את השבת, קל וחומר לכל גופו\u0004 שכולו קשור במצוות \u0003שדוחה את השבת.\u0004 תנאים אחרים דנו באותו ענין.","\u0003ר' יוסי בר' יהודה אומר:\u0004 נאמר: \u0003\"\u0004אך \u0003את שבתתי תשמרו\"\u0004 (שמות לא, יג), \u0003יכול לכל\u0004 ובכל מקרה — \u0003תלמוד לומר: \"אך\"\u0004 שהוא ביטוי הבא לצמצם ול\u0003חלק.\u0004 משמע שיש מקרים שחייבים לשמור את השבת, ויש מקרים, של פיקוח נפש, שבהם אין לשומרה. \u0003ר' יונתן בן יוסף אומר:\u0004 נאמר: \u0003\"כי קדש הוא לכם\"\u0004 (שמות לא, יד), משמע \u0003היא\u0004 השבת \u0003מסורה בידכם\u0004 (\"לכם\") \u0003ולא אתם מסורים בידה,\u0004 למות בשל השבת.","\u0003ר' שמעון בן מנסיא אומר:\u0004 נאמר: \u0003\"ושמרו בני ישראל את השבת\u0004 לעשות את השבת\u0003\"\u0004 (שמות לא, טז), \u0003אמרה תורה: חלל עליו שבת אחת כדי שישמור שבתות הרבה. אמר רב יהודה אמר שמואל: אי הואי התם\u0004 \u0005[אילו הייתי שם]\u0006 בין החכמים ההם ודן בשאלה זו \u0003הוה אמינא דידי עדיפא מדידהו\u0004 \u0005[הייתי אומר\u0006 כי הוכחתי \u0005שלי עדיפה משלהם],\u0006 שנאמר: \u0003\"\u0004ושמרתם את חוקותי ואת משפטי אשר יעשה אתם האדם \u0003וחי בהם\"\u0004 (ויקרא יח, ה) — \u0003ולא שימות בהם.\u0004 שבכל אופן צריך לדאוג שלא יגיע למיתה על ידי קיום המצוות.","על כך העיר \u0003רבא: לכולהו אית להו פירכא\u0004 \u0005[לכולם\u0006 לכל דבריהם \u0005יש מקום לפרוך],\u0006 \u0003בר\u0004 \u0005[חוץ]\u0006 מזו של \u0003שמואל דלית ליה\u0004 \u0005[שאין לה]\u0006 \u0003פרכא.\u0004 ומסבירים את דברי רבא: הראיה שהביא \u0003ר' ישמעאל\u0004 מגנב הבא במחתרת, אפשר לטעון כנגדו — כפי שאמר \u0003רבא.\u0004 ש\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה טעמה]\u0006 של הלכה זו בבא ב\u0003מחתרת? חזקה, אין אדם מעמיד עצמו על ממונו.\u0004 כלומר: אין אדם מתאפק כשרואה שנוטלים ממנו ממונו, \u0003והאי מידע ידע דקאי לאפיה\u0004 \u0005[וזה\u0006 הגנב \u0005יודע שהוא יקום לנגדו]\u0006 ויתנגד, ו\u0003אמר\u0004 מתחילה בלבו: \u0003אי קאי לאפאי\u0004 \u0005[אם הוא עומד כנגדי] —\u0006 \u0003קטילנא ליה\u0004 \u0005[הורג אני אותו],\u0006 \u0003והתורה אמרה:\u0004 כש\u0003בא\u0004 אדם \u0003להרגך\u0004 \u0005—\u0006 \u0003השכם להרגו. ואשכחן\u0004 \u0005[ומצאנו]\u0006 איפוא לשיטה זו ראיה לפיקוח נפש \u0003ודאי,\u0004 אבל \u0003ספק\u0004 פיקוח נפש \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שמחללים בגללו את השבת? ובכך פירכא לדבריו.","והראיה שהביא \u0003ר' עקיבא\u0004 ממה שמורדים את הכהן מעבודת המזבח כדי שיוכל להעיד על אחר, שמא על ידי עדותו יזוכה הנידון, \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לפרוך: \u0003דילמא\u0004 \u0005[שמא]\u0006 כשיטת \u0003אביי\u0004 ש\u0003אמר אביי: מסרינן ליה\u0004 \u0005[מוסרים לו]\u0006 לנידון שטוען שיש לו טענה לזכותו \u0003זוגא דרבנן לידע\u0004 \u0005[זוג חכמים לדעת]\u0006 \u0003אם\u0004 יש \u0003ממש בדבריו\u0004 וכן עושים בכהן זה, שבודקים אם דבריו יש בהם כדי להחיות. ואם כן \u0003אשכחן ודאי\u0004 \u0005[מצאנו\u0006 שפיקוח נפש \u0005ודאי]\u0006 דוחה עבודה, אבל \u0003ספק מנא לן\u0004 \u0005[מניין לנו]?\u0006","\u0003וכולהו\u0004 \u0005[וכל]\u0006 שאר הנימוקים גם כן \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיה לענין פיקוח נפש \u0003ודאי,\u0004 אולם \u0003ספק מנא לן\u0004 \u0005[מניין לנו]?\u0006 ובכך הפירכא אף לדבריו. אבל לראיה שהביא \u0003שמואל\u0004 משום שנאמר \"וחי בהם\" ולמדנו מזה שאין לבוא בשל דיני התורה אפילו לכלל ספק מיתה, \u0003ודאי לית ליה פירכא\u0004 \u0005[אין לו פירכה].\u0006 \u0003אמר רבינא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב נחמן בר יצחק\u0004 להעיר על כך: \u0003טבא חד פלפלתא חריפא ממלא צנא דקרי\u0004 \u0005[טוב פלפל\u0006 חריף \u0005אחד ממלוא הסל דלועים],\u0006 שיש בו טעם יותר מבכולם.","קרבן \u0003חטאת\u0004 וכן קרבן \u0003אשם ודאי\u0004 שמביאים על גזילות ומעילות — \u0003מכפרין\u0004 על העוונות שבאו עליהם. \u0003מיתה ויום הכפורים מכפרין עם התשובה. תשובה\u0004 עצמה — \u0003מכפרת על עבירות קלות; על\u0004 מצוות \u0003עשה, ועל\u0004 מצוות \u0003לא תעשה. ועל החמורות\u0004 התשובה \u0003תולה, עד שיבא יום הכפורים ויכפר. האומר: \"אחטא ואשוב\u0004 (אחר כך אעשה תשובה) \u0003אחטא ואשוב\" — אין מספיקין בידו\u0004 משמים \u0003לעשות תשובה\u0004 ונמצא חוטא כל ימיו. \u0003אחטא ויום הכפורים מכפר — אין יום הכפורים מכפר,\u0004 ועוד: \u0003עבירות שבין אדם למקום\u0004 (לה') — \u0003יום הכפורים מכפר,\u0004 אולם \u0003עבירות שבין אדם לחבירו — אין יום הכפורים מכפר, עד שירצה\u0004 (יפייס) \u0003את חבירו\u0004 ואז יתכפר לו ביום הכיפורים על החטא שיש בדבר זה למקום.","וכן \u0003דרש ר' אלעזר בן עזריה:\u0004 נאמר: \u0003\"מכל חטאתיכם לפני ה' תטהרו\"\u0004 (ויקרא טז, ל), לומר: \u0003עבירות שבין אדם למקום — יום הכפורים מכפר\u0004 שהן חטאים שלפני ה' בלבד, אבל \u0003עבירות שבין אדם לחבירו — אין יום הכפורים מכפר עד שירצה את חבירו.\u0004 ובסיכומם של דברים, \u0003אמר ר' עקיבא: אשריכם ישראל! לפני מי אתם מטהרין, מי מטהר אתכם? — אביכם שבשמים, שנאמר: \"וזרקתי עליכם מים טהורים וטהרתם\"\u0004 (יחזקאל לו, כה), \u0003ואומר: \"מקוה ישראל ה'\"\u0004 (ירמיה יז, יג), לומר: \u0003מה\u0004 ה\u0003מקוה מטהר את הטמאים — אף הקדוש ברוך הוא מטהר את ישראל.\u0004","נאמר במשנה שאשם ודאי, מכפר. ונדייק: \u0003אשם ודאי — אין\u0004 \u0005[כן]\u0006 \u0003אשם תלוי — לא.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כפרה כתיבא ביה\u0004 \u0005[כתובה בו]\u0006 ומדוע לא נאמר שמכפר? ומשיבים: \u0003הנך מכפרי\u0004 \u0005[אלו\u0006 חטאת ואשם ודאי, \u0005מכפרים]\u0006 \u0003כפרה גמורה,\u0004 אבל \u0003אשם תלוי אינו מכפר כפרה גמורה,\u0004 אלא מכפר לו בינתים כדי להצילו מיסורי העונש, עד שיתוודע חטאו ויביא קרבן ראוי.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר הבדל זה: \u0003הנך\u0004 \u0005[אלה]\u0006 חטאת ואשם ודאי \u0003אין אחר מכפר כפרתן,\u0004 ואילו \u0003אשם תלוי\u0004 גם דבר \u0003אחר מכפר כפרתן, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חייבי חטאות ואשמות ודאין שעבר עליהן יום הכפורים\u0004 — עדיין \u0003חייבין\u0004 הם להביא קרבנות אלו, ואילו חייבי \u0003אשמות תלויין — פטורין,\u0004 שיום הכיפורים כיפר להם.","שנינו במשנה כי \u0003מיתה ויום הכפורים מכפרין עם התשובה.\u0004 ונדייק מכאן: \u0003עם התשובה אין\u0004 \u0005[כן]\u0006 \u0003בפני עצמן\u0004 בלא תשובה — \u0003לא. נימא\u0004 \u0005[נאמר]\u0006 שמשנתנו זו ש\u0003לא\u0004 כשיטת \u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבי אומר: על כל עבירות שבתורה, בין עשה תשובה בין לא עשה תשובה — יום הכפורים מכפר, חוץ מפורק עול\u0004 התורה והמצוות מעליו וכופר בקדוש ברוך הוא, \u0003ומגלה פנים בתורה,\u0004 שדורש את דברי התורה לגנאי, \u0003ומיפר ברית בשר\u0004 (ברית מילה), \u0003שאם עשה תשובה — יום הכפורים מכפר\u0004 עליו, \u0003ואם לא עשה תשובה — אין יום הכפורים מכפר.\u0004","ודוחים: מכאן אין ראיה, כי \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת רבי, עדיין אפשר כך להבין את המשנה: \u0003תשובה בעיא\u0004 \u0005[צריכה]\u0006 עדיין את \u0003יום הכפורים\u0004 כדי לסיים את הכפרה, ואילו \u0003יום הכפורים — לא בעיא\u0004 \u0005[אינו צריך]\u0006 \u0003תשובה,\u0004 אלא מכפר אפילו בלעדיה.","שנינו במשנה כי \u0003תשובה מכפרת על עבירות קלות,\u0004 כגון: \u0003על עשה ועל לא תעשה.\u0004 ותוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 למדנו ש\u0003על\u0004 מצות \u0003לא תעשה\u0004 שהיא חמורה ויש בה עונש מלקות — \u0003מכפרת\u0004 התשובה, \u0003על עשה\u0004 שהוא קל יותר \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שמכפרת? \u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דברי המשנה: \u0003על עשה ועל לא תעשה שניתק לעשה,\u0004 שכל דבר האסור בלא תעשה וכתבה התורה את האפשרות לתקנו על ידי מצות עשה — אין נענשים עליו בידי אדם, ולכן דינו כעשה.","ושואלים: \u0003ועל לא תעשה גמור לא\u0004 מכפרת עשיית תשובה? \u0003ורמינהו\u0004 \u0005[ומשליכים\u0006 מראים סתירה ממקום אחר\u0005],\u0006 ששנינו: \u0003אלו הן\u0004 עבירות ה\u0003קלות: עשה ולא תעשה\u0004"]]};
